LLPipeline::~LLPipeline()
{
}

void LLPipeline::cleanup()
{
    assertInitialized();

    mGroupQ1.clear() ;

    for(pool_set_t::iterator iter = mPools.begin();
        iter != mPools.end(); )
    {
        pool_set_t::iterator curiter = iter++;
        LLDrawPool* poolp = *curiter;
        if (poolp->isFacePool())
        {
            LLFacePool* face_pool = (LLFacePool*) poolp;
            if (face_pool->mReferences.empty())
            {
                mPools.erase(curiter);
                removeFromQuickLookup( poolp );
                delete poolp;
            }
        }
        else
        {
            mPools.erase(curiter);
            removeFromQuickLookup( poolp );
            delete poolp;
        }
    }

    if (!mTerrainPools.empty())
    {
        LL_WARNS() << "Terrain Pools not cleaned up" << LL_ENDL;
    }
    if (!mTreePools.empty())
    {
        LL_WARNS() << "Tree Pools not cleaned up" << LL_ENDL;
    }

    delete mAlphaPoolPreWater;
    mAlphaPoolPreWater = nullptr;
    delete mAlphaPoolPostWater;
    mAlphaPoolPostWater = nullptr;
    delete mSkyPool;
    mSkyPool = NULL;
    delete mTerrainPool;
    mTerrainPool = NULL;
    delete mWaterPool;
    mWaterPool = NULL;
    delete mSimplePool;
    mSimplePool = NULL;
    delete mFullbrightPool;
    mFullbrightPool = NULL;
    delete mGlowPool;
    mGlowPool = NULL;
    delete mBumpPool;
    mBumpPool = NULL;
    // don't delete wl sky pool it was handled above in the for loop
    //delete mWLSkyPool;
    mWLSkyPool = NULL;
    delete mWaterExclusionPool;
    mWaterExclusionPool = nullptr;

    releaseRenderBuffers();

    mFaceSelectImagep = NULL;

    mMovedList.clear();
    mMovedBridge.clear();
    mShiftList.clear();

    mInitialized = false;

    mDeferredVB = NULL;
    mScreenTriangleVB = nullptr;

    mCubeVB = NULL;

    mReflectionMapManager.cleanup();
    mHeroProbeManager.cleanup();
}

//============================================================================

void LLPipeline::destroyResources()
{
    unloadShaders();
    mHighlightFaces.clear();

    resetDrawOrders();

    releaseRenderBuffers();

}

void LLPipeline::requestResizeScreenTexture()
{
    gResizeScreenTexture = true;
}

void LLPipeline::requestResizeShadowTexture()
{
    gResizeShadowTexture = true;
}

void LLPipeline::resizeShadowTexture()
{
    releaseSunShadowTargets();
    releaseSpotShadowTargets();
    allocateShadowBuffer(mRT->screen.getWidth(), mRT->screen.getHeight()); // <FS:Beq> revert and correct previous shadowres fix that leads to FPS drop (FIRE-3200)
    gResizeShadowTexture = false;
}

void LLPipeline::resizeScreenTexture()
{
    if (gPipeline.shadersLoaded())
    {
        U32 resX = gViewerWindow->getWorldViewWidthRaw();
        U32 resY = gViewerWindow->getWorldViewHeightRaw();

// [SL:KB] - Patch: Settings-RenderResolutionMultiplier | Checked: Catznip-5.4
        U32 scaledResX = resX;
        U32 scaledResY = resY;
        if ( (RenderResolutionDivisor > 1) && (RenderResolutionDivisor < resX) && (RenderResolutionDivisor < resY) )
        {
            scaledResX /= RenderResolutionDivisor;
            scaledResY /= RenderResolutionDivisor;
        }
        else if (RenderResolutionMultiplier > 0.f && RenderResolutionMultiplier < 1.f)
        {
            scaledResX = (U32)(scaledResX * RenderResolutionMultiplier);
            scaledResY = (U32)(scaledResY * RenderResolutionMultiplier);
        }
// [/SL:KB]

//      if (gResizeScreenTexture || (resX != mRT->screen.getWidth()) || (resY != mRT->screen.getHeight()))
// [SL:KB] - Patch: Settings-RenderResolutionMultiplier | Checked: Catznip-5.4
        if (gResizeScreenTexture || (scaledResX != mRT->screen.getWidth()) || (scaledResY != mRT->screen.getHeight()))
// [/SL:KB]
        {
            releaseScreenBuffers();
            releaseSunShadowTargets();
            releaseSpotShadowTargets();
            allocateScreenBuffer(resX,resY);
            gResizeScreenTexture = false;
        }
    }
}

bool LLPipeline::allocateScreenBuffer(U32 resX, U32 resY)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_DISPLAY;
    eFBOStatus ret = doAllocateScreenBuffer(resX, resY);

    return ret == FBO_SUCCESS_FULLRES;
}


LLPipeline::eFBOStatus LLPipeline::doAllocateScreenBuffer(U32 resX, U32 resY)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_DISPLAY;
    // try to allocate screen buffers at requested resolution and samples
    // - on failure, shrink number of samples and try again
    // - if not multisampled, shrink resolution and try again (favor X resolution over Y)
    // Make sure to call "releaseScreenBuffers" after each failure to cleanup the partially loaded state

    // refresh cached settings here to protect against inconsistent event handling order
    refreshCachedSettings();

    eFBOStatus ret = FBO_SUCCESS_FULLRES;
    if (!allocateScreenBufferInternal(resX, resY))
    {
        //failed to allocate at requested specification, return false
        ret = FBO_FAILURE;

        releaseScreenBuffers();

        //reduce resolution
        while (resY > 0 && resX > 0)
        {
            resY /= 2;
            if (allocateScreenBufferInternal(resX, resY))
            {
                return FBO_SUCCESS_LOWRES;
            }
            releaseScreenBuffers();

            resX /= 2;
            if (allocateScreenBufferInternal(resX, resY))
            {
                return FBO_SUCCESS_LOWRES;
            }
            releaseScreenBuffers();
        }

        LL_WARNS() << "Unable to allocate screen buffer at any resolution!" << LL_ENDL;
    }

    return ret;
}

bool LLPipeline::allocateScreenBufferInternal(U32 resX, U32 resY)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_DISPLAY;

    static LLCachedControl<bool> has_hdr(gSavedSettings, "RenderHDREnabled", true);
    bool hdr = gDeviceCaps.mApiVersionNumber > 4.05f && has_hdr();

    if (mRT == &mMainRT)
    { // hacky -- allocate auxillary buffer
        LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("check reflection map setup"); // <FS:Beq/> improve Tracy scoping 

        gCubeSnapshot = true;

        if (sReflectionProbesEnabled)
        {
            mReflectionMapManager.initReflectionMaps();
        }

        mRT = &mAuxillaryRT;
        U32 res = mReflectionMapManager.mProbeResolution * 4;  //multiply by 4 because probes will be 16x super sampled
        allocateScreenBufferInternal(res, res);

        if (RenderMirrors)
        {
            mHeroProbeManager.initReflectionMaps();
            res = mHeroProbeManager.mProbeResolution;  // We also scale the hero probe RT to the probe res since we don't super sample it.
            mRT = &mHeroProbeRT;
            allocateScreenBufferInternal(res, res);
            if (ll_mirror_planar())
            {   // <FS> the planar mirror's reflected view: the main view's own size (allocateScreenBufferInternal scales it by the render resolution like the main target)
                mRT = &mMirrorViewRT;
                const U32 mirror_div = mirrorViewDivisor();
                allocateScreenBufferInternal(std::max(64u, resX / mirror_div), std::max(64u, resY / mirror_div));
            }
        }

        mRT = &mMainRT;
        gCubeSnapshot = false;
    }

    // remember these dimensions
    mRT->width = resX;
    mRT->height = resY;
    const U32 window_res_x = resX;      // before any render-resolution scaling
    const U32 window_res_y = resY;

    U32 res_mod = RenderResolutionDivisor;

    //<FS:TS> FIRE-7066: RenderResolutionDivisor broken if higher than
    //      smallest screen dimension
    if (res_mod >= resX)
    {
        res_mod = resX - 1;
    }
    if (res_mod >= resY)
    {
        res_mod = resY - 1;
    }
    //</FS:TS> FIRE-7066

    if (res_mod > 1 && res_mod < resX && res_mod < resY)
    {
        resX /= res_mod;
        resY /= res_mod;
    }
// [SL:KB] - Patch: Settings-RenderResolutionMultiplier | Checked: Catznip-5.4
    else if (RenderResolutionMultiplier > 0.f && RenderResolutionMultiplier < 1.f)
    {
        resX = (U32)(resX * RenderResolutionMultiplier);
        resY = (U32)(resY * RenderResolutionMultiplier);
    }
// [/SL:KB]

    S32 shadow_detail = RenderShadowDetail;
    bool ssao = RenderDeferredSSAO;

    //allocate deferred rendering color buffers
    if (!mRT->deferredScreen.allocate(resX, resY, TexelFormat::RGBA8, true)) return false;
    if (!addDeferredAttachments(mRT->deferredScreen)) return false;

    TexelFormat screenFormat = hdr ? TexelFormat::RGBA16F : TexelFormat::RGBA8;

    if (!mRT->screen.allocate(resX, resY, TexelFormat::RGBA16F)) return false;

    mRT->deferredScreen.shareDepthBuffer(mRT->screen);

    // <FS:Beq> restore setSphere
    // if (hdr || shadow_detail > 0 || ssao || RenderDepthOfField))
    if (hdr || shadow_detail > 0 || ssao || RenderDepthOfField || RlvActions::hasPostProcess())
    // </FS:Beq>
    { //only need mRT->deferredLight for shadows OR ssao OR dof OR fxaa
        if (!mRT->deferredLight.allocate(resX, resY, screenFormat)) return false;
        if (!gCubeSnapshot)
        {
            // <FS> the half resolution sun lightmap (shaders from scratch): its pixel i stands for the 2x2 block 2i, 2i+1
            if (!mLightMapHalf.allocate((resX + 1) / 2, (resY + 1) / 2, screenFormat) || !mLightMapHalf2.allocate((resX + 1) / 2, (resY + 1) / 2, screenFormat))
            {
                mLightMapHalf.release();
                mLightMapHalf2.release();
            }
        }
        // <FS> ray traced shadows (PLAN-rt-shadow-penumbra.md step 1): the sun pass also writes the blocker distance of its centre ray, to a second attachment of the lightmap; it is copied right after
        // the pass into mRtBlocker, since the passes that rewrite the lightmap later (the history's copy, the blur) write attachment 0 only and leave attachment 1 undefined
        if (LLVkBridge::rtShadowMode() && !gCubeSnapshot)      // (the main view's buffers only: the reflection probes' sun pass has one output, and mRtBlocker is one target)
        {
            if (!mRT->deferredLight.addColorAttachment(TexelFormat::R16F) || !mRtBlocker.allocate(resX, resY, TexelFormat::R16F))
            {
                mRtBlocker.release();
            }
            if (!mRtShadowTemp.allocate(resX, resY, screenFormat))      // the penumbra filter's output, the lightmap's format
            {
                mRtShadowTemp.release();
            }
            if (!mRtSunHard.allocate(resX, resY, TexelFormat::RGBA16F, false, LLTexUnit::TT_TEXTURE, LLTexUnit::TMG_AUTO))    // the hard sun shadow, the half-width and the blocker mask with their mip chain, generated at the end of the prep pass
            {
                mRtSunHard.release();
            }
        }
        else if (!gCubeSnapshot)
        {
            mRtBlocker.release();
            mRtShadowTemp.release();
            mRtSunHard.release();
        }
        if (!gCubeSnapshot)
        LL_INFOS("VkRt") << "rt blocker distance: screen buffers " << resX << "x" << resY << ", ray traced shadows " << LLVkBridge::rtShadowMode() << ", lightmap attachments " << mRT->deferredLight.getNumTextures()
                         << ", blocker target " << (mRtBlocker.isComplete() ? "complete" : "none") << LL_ENDL;
    }
    else
    {
        mRT->deferredLight.release();
    }

    allocateShadowBuffer(resX, resY);

    if (!gCubeSnapshot) // hack to not re-allocate various targets for cube snapshots
    {
        LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("non-cube allocations"); // <FS:Beq/> improve Tracy scoping 
        if (RenderUIBuffer)
        {
            LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("UIBuffer"); // <FS:Beq/> improve Tracy scoping 
            if (!mUIScreen.allocate(resX, resY, TexelFormat::RGBA8))
            {
                return false;
            }
        }

        if (RenderFSAAType > 0)
        {
            LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("FSAABuffer"); // <FS:Beq/> improve Tracy scoping 
            if (!mFXAAMap.allocate(resX, resY, TexelFormat::RGBA8)) return false;
            if (RenderFSAAType == 2)
            {
                LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("SMAABuffer"); // <FS:Beq/> improve Tracy scoping 
                if (!mSMAABlendBuffer.allocate(resX, resY, TexelFormat::RGBA8, false)) return false;
            }
        }
        else
        {
            mFXAAMap.release();
            mSMAABlendBuffer.release();
        }

        //water reflection texture (always needed as scratch space whether or not transparent water is enabled)
        mWaterDis.allocate(resX, resY, screenFormat, true);

        // <FS> the planar mirror's view at less than full size is enlarged into this one (see mMirrorUpscaled)
        if (RenderMirrors && ll_mirror_planar() && mirrorViewDivisor() > 1)
        {
            if (!mMirrorUpscaled.allocate(resX, resY, TexelFormat::RGBA16F))
            {
                mMirrorUpscaled.release();
            }
        }
        else
        {
            mMirrorUpscaled.release();
        }

        if(RenderScreenSpaceReflections)
        {
            LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("SSRBuffer"); // <FS:Beq/> improve Tracy scoping 
            mSceneMap.allocate(resX, resY, screenFormat, true);
        }
        else
        {
            mSceneMap.release();
        }

        if (sDLSS)
        {
            // motion vectors at the render size; the upscaled picture at the window size
            if (!mMotionMap.allocate(resX, resY, TexelFormat::RG16F)) return false;
            if (!mAvatarVelocityMap.allocate(resX, resY, TexelFormat::RGBA16F)) return false;
            if (!mUpscaledMap.allocate(window_res_x, window_res_y, TexelFormat::RGBA8)) return false;
            // <FS> DLSS-NR (doc/vulkan/PLAN-dlss-nr.md step two): the neural renderer's output, window size
            if (neuralRenderMode() != 0 && LLVkBridge::neuralRenderAvailable())
            {
                if (!mNROutput.allocate(window_res_x, window_res_y, TexelFormat::RGBA16F)) return false;
                if (!mNROutputRender.allocate(resX, resY, TexelFormat::RGBA16F)) return false;
                if (!mNRLift.allocate(window_res_x, window_res_y, TexelFormat::RGBA16F)) return false;
                if (!mNRLiftRender.allocate(resX, resY, TexelFormat::RGBA16F)) return false;
            }
            else
            {
                mNROutput.release();
                mNROutputRender.release();
                mNRLift.release();
                mNRLiftRender.release();
            }
        }
        else
        {
            mMotionMap.release();
            mAvatarVelocityMap.release();
            mUpscaledMap.release();
            mNROutput.release();
            mNROutputRender.release();
            mNRLift.release();
            mNRLiftRender.release();
        }

        if (sRR && LLVkBridge::rayReconstructionAvailable())
        {
            // <FS> ray reconstruction (the albedos are 16 bit: linear 8 bit bands in the darks): the guides at the render size, its output and the post chain that follows at the window size. The chain is 16 bit
            // too: it used to run at the render size before the upscale, whose temporal averaging hid the 8 bit steps of dark gradients; after the upscale nothing hides them
            if (!mRRGuides.allocate(resX, resY, TexelFormat::RGBA16F) || !mRRGuides.addColorAttachment(TexelFormat::RGBA16F) || !mRRGuides.addColorAttachment(TexelFormat::RGBA16F) || !mRRGuides.addColorAttachment(TexelFormat::RG16F)
                || !mRRReflMotion.allocate(resX, resY, TexelFormat::RG16F) || !mRRHdr.allocate(window_res_x, window_res_y, TexelFormat::RGBA16F) || !mRRPing.allocate(window_res_x, window_res_y, TexelFormat::RGBA16F) || !mRRPong.allocate(window_res_x, window_res_y, TexelFormat::RGBA16F)
                || !mRRDenoised.allocate(resX, resY, TexelFormat::RGBA16F))
            {
                LL_WARNS("VkDlss") << "the ray reconstruction targets could not be made: ray reconstruction stays off" << LL_ENDL;
                mRRGuides.release();
                mRRReflMotion.release();
                mRRHdr.release();
                mRRPing.release();
                mRRPong.release();
                mRRDenoised.release();
            }
        }
        else
        {
            mRRGuides.release();
            mRRReflMotion.release();
            mRRHdr.release();
            mRRPing.release();
            mRRPong.release();
            mRRDenoised.release();
        }

        {LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("mPostMapBuffer"); // <FS:Beq/> improve Tracy scoping 
        mPostPingMap.allocate(resX, resY, TexelFormat::RGBA8);
        mPostPongMap.allocate(resX, resY, TexelFormat::RGBA8);
        } // <FS:Beq/> improve Tracy scoping 
        // The water exclusion mask needs its own depth buffer so we can take care of the problem of multiple water planes.
        // Should we ever make water not just a plane, it also aids with that as well as the water planes will be rendered into the mask.
        // Why do we do this? Because it saves us some janky logic in the exclusion shader when we generate the mask.
        // Regardless, this should always only be an R8 texture unless we choose to start having multiple kinds of exclusion that 8 bits can't handle.
        // - Geenz 2025-02-06
        bool success = mWaterExclusionMask.allocate(resX, resY, TexelFormat::R8, true);

        assert(success);

        // used to scale down textures
        // See LLViwerTextureList::updateImagesCreateTextures and LLImageTex::scaleDown
        {LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("DownResBuffer");// <FS:Beq/> create an independent preview screen target
        mDownResMap.allocate(1024, 1024, TexelFormat::RGBA8);
        }// <FS:Beq/> create an independent preview screen target

        // <FS:Beq> create an independent preview screen target
        {LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("PreviewScreenBuffer");
        mPreviewScreen.allocate(MAX_PREVIEW_WIDTH, MAX_PREVIEW_HEIGHT, TexelFormat::RGBA8, true); 
        } // </FS:Beq>
        {LL_PROFILE_ZONE_NAMED_CATEGORY_DISPLAY("BakeMapBuffer");// <FS:Beq/> create an independent preview screen target
        mBakeMap.allocate(LLAvatarAppearanceDefines::SCRATCH_TEX_WIDTH, LLAvatarAppearanceDefines::SCRATCH_TEX_HEIGHT, TexelFormat::RGBA8);
        }// <FS:Beq/> create an independent preview screen target
    }
    //HACK make screenbuffer allocations start failing after 30 seconds
    if (gSavedSettings.getBOOL("SimulateFBOFailure"))
    {
        return false;
    }

    gRender.getTexUnit(0)->clear();


    return true;
}

// must be even to avoid a stripe in the horizontal shadow blur
inline U32 BlurHappySize(U32 x, F32 scale) { return U32( x * scale + 16.0f) & ~0xF; }

bool LLPipeline::allocateShadowBuffer(U32 resX, U32 resY)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_DISPLAY;
    S32 shadow_detail = RenderShadowDetail;

    F32 scale = gCubeSnapshot ? 1.0f : llmax(0.f, RenderShadowResolutionScale); // Don't scale probe shadow maps
    U32 sun_shadow_map_width = BlurHappySize(resX, scale);
    U32 sun_shadow_map_height = BlurHappySize(resY, scale);

    if (shadow_detail > 0)
    { //allocate 4 sun shadow maps
        for (U32 i = 0; i < 4; i++)
        {
            if (!mRT->shadow[i].allocate(sun_shadow_map_width, sun_shadow_map_height, TexelFormat::None, true))
            {
                return false;
            }
        }
    }
    else
    {
        for (U32 i = 0; i < 4; i++)
        {
            releaseSunShadowTarget(i);
        }
    }

    if (!gCubeSnapshot) // hack to not allocate spot shadow maps during ReflectionMapManager init
    {
        U32 width = (U32)(resX * scale);
        U32 height = width;

        if (shadow_detail > 1)
        { //allocate two spot shadow maps
            U32 spot_shadow_map_width = width;
            U32 spot_shadow_map_height = height;
            for (U32 i = 0; i < 2; i++)
            {
                if (!mSpotShadow[i].allocate(spot_shadow_map_width, spot_shadow_map_height, TexelFormat::None, true))
                {
                    return false;
                }
            }
        }
        else
        {
            releaseSpotShadowTargets();
        }
    }


    // set up shadow map filtering and compare modes
    if (shadow_detail > 0)
    {
        for (U32 i = 0; i < 4; i++)
        {
            LLRenderTarget* shadow_target = getSunShadowTarget(i);
            if (shadow_target)
            {
                gRender.getTexUnit(0)->bind(getSunShadowTarget(i), true);
                gRender.getTexUnit(0)->setTextureFilteringOption(LLTexUnit::TFO_ANISOTROPIC);
                gRender.getTexUnit(0)->setTextureAddressMode(LLTexUnit::TAM_CLAMP);

                gRender.setTexCompare(shadow_target->getDepth(), true, LLRenderState::CompareOp::LessEqual);
            }
        }
    }

    if (shadow_detail > 1 && !gCubeSnapshot)
    {
        for (U32 i = 0; i < 2; i++)
        {
            LLRenderTarget* shadow_target = getSpotShadowTarget(i);
            if (shadow_target)
            {
                gRender.getTexUnit(0)->bind(shadow_target, true);
                gRender.getTexUnit(0)->setTextureFilteringOption(LLTexUnit::TFO_ANISOTROPIC);
                gRender.getTexUnit(0)->setTextureAddressMode(LLTexUnit::TAM_CLAMP);

                gRender.setTexCompare(shadow_target->getDepth(), true, LLRenderState::CompareOp::LessEqual);
            }
        }
    }

    return true;
}

