class LLOctreeDirtyTexture : public OctreeTraveler
{
public:
    const std::set<LLViewerFetchedTexture*>& mTextures;

    LLOctreeDirtyTexture(const std::set<LLViewerFetchedTexture*>& textures) : mTextures(textures) { }

    virtual void visit(const OctreeNode* node)
    {
        LLSpatialGroup* group = (LLSpatialGroup*) node->getListener(0);

        if (!group->hasState(LLSpatialGroup::GEOM_DIRTY) && !group->isEmpty())
        {
            for (LLSpatialGroup::draw_map_t::iterator i = group->mDrawMap.begin(); i != group->mDrawMap.end(); ++i)
            {
                for (LLSpatialGroup::drawmap_elem_t::iterator j = i->second.begin(); j != i->second.end(); ++j)
                {
                    LLDrawInfo* params = *j;
                    LLViewerFetchedTexture* tex = LLViewerTextureManager::staticCastToFetchedTexture(params->mTexture);
                    if (tex && mTextures.find(tex) != mTextures.end())
                    {
                        group->setState(LLSpatialGroup::GEOM_DIRTY);
                    }
                }
            }
        }

        for (LLSpatialGroup::bridge_list_t::iterator i = group->mBridgeList.begin(); i != group->mBridgeList.end(); ++i)
        {
            LLSpatialBridge* bridge = *i;
            traverse(bridge->mOctree);
        }
    }
};

// Called when a texture changes # of channels (causes faces to move to alpha pool)
void LLPipeline::dirtyPoolObjectTextures(const std::set<LLViewerFetchedTexture*>& textures)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    assertInitialized();

    // *TODO: This is inefficient and causes frame spikes; need a better way to do this
    //        Most of the time is spent in dirty.traverse.

    for (pool_set_t::iterator iter = mPools.begin(); iter != mPools.end(); ++iter)
    {
        LLDrawPool *poolp = *iter;
        if (poolp->isFacePool())
        {
            ((LLFacePool*) poolp)->dirtyTextures(textures);
        }
    }

    LLOctreeDirtyTexture dirty(textures);
    for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin();
            iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
    {
        LLViewerRegion* region = *iter;
        for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
        {
            LLSpatialPartition* part = region->getSpatialPartition(i);
            if (part)
            {
                dirty.traverse(part->mOctree);
            }
        }
    }
}

LLDrawPool *LLPipeline::findPool(const U32 type, LLViewerTexture *tex0)
{
    assertInitialized();

    LLDrawPool *poolp = NULL;
    switch( type )
    {
    case LLDrawPool::POOL_SIMPLE:
        poolp = mSimplePool;
        break;

    case LLDrawPool::POOL_GRASS:
        poolp = mGrassPool;
        break;

    case LLDrawPool::POOL_ALPHA_MASK:
        poolp = mAlphaMaskPool;
        break;

    case LLDrawPool::POOL_FULLBRIGHT_ALPHA_MASK:
        poolp = mFullbrightAlphaMaskPool;
        break;

    case LLDrawPool::POOL_FULLBRIGHT:
        poolp = mFullbrightPool;
        break;

    case LLDrawPool::POOL_GLOW:
        poolp = mGlowPool;
        break;

    case LLDrawPool::POOL_TREE:
        poolp = get_if_there(mTreePools, (uintptr_t)tex0, (LLDrawPool*)0 );
        break;

    case LLDrawPool::POOL_TERRAIN:
        poolp = get_if_there(mTerrainPools, (uintptr_t)tex0, (LLDrawPool*)0 );
        break;

    case LLDrawPool::POOL_BUMP:
        poolp = mBumpPool;
        break;
    case LLDrawPool::POOL_MATERIALS:
        poolp = mMaterialsPool;
        break;
    case LLDrawPool::POOL_ALPHA_PRE_WATER:
        poolp = mAlphaPoolPreWater;
        break;
    case LLDrawPool::POOL_ALPHA_POST_WATER:
        poolp = mAlphaPoolPostWater;
        break;

    case LLDrawPool::POOL_AVATAR:
    case LLDrawPool::POOL_CONTROL_AV:
        break; // Do nothing

    case LLDrawPool::POOL_SKY:
        poolp = mSkyPool;
        break;

    case LLDrawPool::POOL_WATER:
        poolp = mWaterPool;
        break;

    case LLDrawPool::POOL_WL_SKY:
        poolp = mWLSkyPool;
        break;

    case LLDrawPool::POOL_GLTF_PBR:
        poolp = mPBROpaquePool;
        break;
    case LLDrawPool::POOL_GLTF_PBR_ALPHA_MASK:
        poolp = mPBRAlphaMaskPool;
        break;

    case LLDrawPool::POOL_WATEREXCLUSION:
        poolp = mWaterExclusionPool;
        break;

    default:
        llassert(0);
        LL_ERRS() << "Invalid Pool Type in  LLPipeline::findPool() type=" << type << LL_ENDL;
        break;
    }

    return poolp;
}


LLDrawPool *LLPipeline::getPool(const U32 type, LLViewerTexture *tex0)
{
    LLDrawPool *poolp = findPool(type, tex0);
    if (poolp)
    {
        return poolp;
    }

    LLDrawPool *new_poolp = LLDrawPool::createPool(type, tex0);
    addPool( new_poolp );

    return new_poolp;
}


// static
LLDrawPool* LLPipeline::getPoolFromTE(const LLTextureEntry* te, LLViewerTexture* imagep)
{
    U32 type = getPoolTypeFromTE(te, imagep);
    return gPipeline.getPool(type, imagep);
}

//static
U32 LLPipeline::getPoolTypeFromTE(const LLTextureEntry* te, LLViewerTexture* imagep)
{
    if (!te || !imagep)
    {
        return 0;
    }

    LLMaterial* mat = te->getMaterialParams().get();
    LLGLTFMaterial* gltf_mat = te->getGLTFRenderMaterial();

    bool color_alpha = te->getColor().mV[3] < 0.999f;
    bool alpha = color_alpha;
    if (imagep)
    {
        alpha = alpha || (imagep->getComponents() == 4 && imagep->getType() != LLViewerTexture::MEDIA_TEXTURE) || (imagep->getComponents() == 2);
    }

    if (alpha && mat)
    {
        switch (mat->getDiffuseAlphaMode())
        {
            case 1:
                alpha = true; // Material's alpha mode is set to blend.  Toss it into the alpha draw pool.
                break;
            case 0: //alpha mode set to none, never go to alpha pool
            case 3: //alpha mode set to emissive, never go to alpha pool
                alpha = color_alpha;
                break;
            default: //alpha mode set to "mask", go to alpha pool if fullbright
                alpha = color_alpha; // Material's alpha mode is set to none, mask, or emissive.  Toss it into the opaque material draw pool.
                break;
        }
    }

    if (alpha || (gltf_mat && gltf_mat->mAlphaMode == LLGLTFMaterial::ALPHA_MODE_BLEND))
    {
        return LLDrawPool::POOL_ALPHA;
    }
    else if ((te->getBumpmap() || te->getShiny()) && (!mat || mat->getNormalID().isNull()))
    {
        return LLDrawPool::POOL_BUMP;
    }
    else if (gltf_mat)
    {
        return LLDrawPool::POOL_GLTF_PBR;
    }
    else if (mat && !alpha)
    {
        return LLDrawPool::POOL_MATERIALS;
    }
    else
    {
        return LLDrawPool::POOL_SIMPLE;
    }
}


void LLPipeline::addPool(LLDrawPool *new_poolp)
{
    assertInitialized();
    mPools.insert(new_poolp);
    addToQuickLookup( new_poolp );
}

void LLPipeline::allocDrawable(LLViewerObject *vobj)
{
    LLDrawable *drawable = new LLDrawable(vobj);
    vobj->mDrawable = drawable;

    //encompass completely sheared objects by taking
    //the most extreme point possible (<1,1,0.5>)
    drawable->setRadius(LLVector3(1,1,0.5f).scaleVec(vobj->getScale()).length());
    if (vobj->isOrphaned())
    {
        drawable->setState(LLDrawable::FORCE_INVISIBLE);
    }
    drawable->updateXform(true);
}


bool LLPipeline::inMovedList(const LLDrawable* drawablep) const
{
    for (const LLPointer<LLDrawable>& d : mMovedList)
    {
        if (d.get() == drawablep)
        {
            return true;
        }
    }
    return false;
}

void LLPipeline::unlinkDrawable(LLDrawable *drawable)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;

    assertInitialized();

    LLPointer<LLDrawable> drawablep = drawable; // make sure this doesn't get deleted before we are done

    // Based on flags, remove the drawable from the queues that it's on.
    if (drawablep->isState(LLDrawable::ON_MOVE_LIST))
    {
        LLDrawable::drawable_vector_t::iterator iter = std::find(mMovedList.begin(), mMovedList.end(), drawablep);
        if (iter != mMovedList.end())
        {
            // <FS> LL_VK_DRAWABLE_TRACE: the entry the moved list pass is working on is taken off the list from inside its own updateMove (see updateMovedListSerial): who does it
            static const bool trace = getenv("LL_VK_DRAWABLE_TRACE") ? atoi(getenv("LL_VK_DRAWABLE_TRACE")) != 0 : true;
            static std::atomic<int> logged{0};
            if (trace && drawablep.get() == sMovedCurrent && logged.fetch_add(1) < 8)
            {
                extern std::string fs_stack_here(int skip, int max_frames);
                LL_WARNS("DrawableTrace") << "the moved list pass's current drawable is unlinked from inside its updateMove (dead " << drawablep->isDead() << "):\n" << fs_stack_here(0, 30) << LL_ENDL;
            }
            mMovedList.erase(iter);
        }
    }

    if (drawablep->getSpatialGroup())
    {
        if (!drawablep->getSpatialGroup()->getSpatialPartition()->remove(drawablep, drawablep->getSpatialGroup()))
        {
#ifdef LL_RELEASE_FOR_DOWNLOAD
            LL_WARNS() << "Couldn't remove object from spatial group!" << LL_ENDL;
#else
            LL_ERRS() << "Couldn't remove object from spatial group!" << LL_ENDL;
#endif
        }
    }

    mLights.erase(drawablep);
    ++mLightsVersion;

    for (light_set_t::iterator iter = mNearbyLights.begin();
                iter != mNearbyLights.end(); iter++)
    {
        if (iter->drawable == drawablep)
        {
            mNearbyLights.erase(iter);
            break;
        }
    }

    for (U32 i = 0; i < 2; ++i)
    {
        if (mShadowSpotLight[i] == drawablep)
        {
            mShadowSpotLight[i] = NULL;
        }

        if (mTargetShadowSpotLight[i] == drawablep)
        {
            mTargetShadowSpotLight[i] = NULL;
        }
    }
}

//static
void LLPipeline::removeMutedAVsLights(LLVOAvatar* muted_avatar)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    light_set_t::iterator iter = gPipeline.mNearbyLights.begin();
    while (iter != gPipeline.mNearbyLights.end())
    {
        const LLViewerObject* vobj = iter->drawable->getVObj();
        if (vobj
            && vobj->getAvatar()
            && vobj->isAttachment()
            && vobj->getAvatar() == muted_avatar)
        {
            gPipeline.mLights.erase(iter->drawable);
            ++gPipeline.mLightsVersion;
            iter = gPipeline.mNearbyLights.erase(iter);
        }
        else
        {
            iter++;
        }
    }
}

U32 LLPipeline::addObject(LLViewerObject *vobj)
{
    if (RenderDelayCreation)
    {
        mCreateQ.push_back(vobj);
    }
    else
    {
        createObject(vobj);
    }

    return 1;
}

void LLPipeline::createObjects(F32 max_dtime)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;

    LLTimer update_timer;

    while (!mCreateQ.empty() && update_timer.getElapsedTimeF32() < max_dtime)
    {
        LLViewerObject* vobj = mCreateQ.front();
        if (!vobj->isDead())
        {
            createObject(vobj);
        }
        mCreateQ.pop_front();
    }

    //for (LLViewerObject::vobj_list_t::iterator iter = mCreateQ.begin(); iter != mCreateQ.end(); ++iter)
    //{
    //  createObject(*iter);
    //}

    //mCreateQ.clear();
}

void LLPipeline::createObject(LLViewerObject* vobj)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    LLDrawable* drawablep = vobj->mDrawable;

    if (!drawablep)
    {
        drawablep = vobj->createDrawable(this);
    }
    else
    {
        LL_ERRS() << "Redundant drawable creation!" << LL_ENDL;
    }

    llassert(drawablep);

    if (vobj->getParent())
    {
        vobj->setDrawableParent(((LLViewerObject*)vobj->getParent())->mDrawable); // LLPipeline::addObject 1
    }
    else
    {
        vobj->setDrawableParent(NULL); // LLPipeline::addObject 2
    }

    markRebuild(drawablep, LLDrawable::REBUILD_ALL);

    // <FS:Beq> FIRE-23122 BUG-225920 Remove broken RenderAnimateRes functionality.
    //if (drawablep->getVOVolume() && RenderAnimateRes)
    //{
    //  // fun animated res
    //  drawablep->updateXform(true);
    //  drawablep->clearState(LLDrawable::MOVE_UNDAMPED);
    //  drawablep->setScale(LLVector3(0,0,0));
    //  drawablep->makeActive();
    //}
}


void LLPipeline::resetFrameStats()
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    assertInitialized();

    sCompiles        = 0;
    mNumVisibleFaces = 0;

    if (mOldRenderDebugMask != mRenderDebugMask)
    {
        gObjectList.clearDebugText();
        mOldRenderDebugMask = mRenderDebugMask;
    }
}

//external functions for asynchronous updating
// <FS> view rework A1: the recorded writes of an avatar's attachment loop, made in the order they were requested
void LLPipeline::applyAvOps(std::vector<AvOp>& ops)
{
    applyAvOpsRange(ops.data(), ops.data() + ops.size());
    ops.clear();
}

void LLPipeline::applyAvOpsRange(const AvOp* begin, const AvOp* end)
{
    sAvSink = nullptr;
    static U64 calls = 0, total_ops = 0, by_kind[12] = {}, stale_group = 0, orders = 0;
    for (const AvOp* op_ptr = begin; op_ptr != end; ++op_ptr)
    {
        const AvOp& op = *op_ptr;
        // <FS> the recorded request names its drawable by a raw pointer, made on a pool thread and replayed here: one that was freed since is not touched (and a moved list entry made of it would dangle). Logged with the stack of its destruction.
        // C1a: the vtable test alone passes a drawable freed earlier in this very replay (its base class vtable stays in the freed block): a MOVED_BRIDGE op for a bridge that an earlier MOVE_PARTITION op of the same avatar
        // just destroyed pushed it onto the moved bridge list as a counted pointer to freed memory (the stale entries of lap c1b-new1: "moved list entry 0 ... is not a live drawable", destroyed in the same frame by markDead
        // < cleanupReferences). The instance row names its owner only while the drawable lives.
        if (op.mDrawable && op.mKind != AvOp::UPDATE_TEXT && op.mKind != AvOp::DIRTY_GROUP && !(fs_drawable_looks_live(op.mDrawable) && op.mDrawable->ownsInstanceRow()))
        {
            static std::atomic<int> logged{0};
            if (logged.fetch_add(1) < 8)
            {
                LL_WARNS("DrawableTrace") << "an avatar attachment request (kind " << (int)op.mKind << ") names a drawable that is already freed (" << (const void*)op.mDrawable << "), dropped; "
                    << fs_drawable_destroy_info(op.mDrawable) << LL_ENDL;
            }
            continue;
        }
        ++by_kind[op.mKind];
        switch (op.mKind)
        {
        case AvOp::MOVED_LIST:
            mMovedList.push_back(op.mDrawable);
            break;
        case AvOp::MOVED_BRIDGE:
            mMovedBridge.push_back(op.mDrawable);
            break;
        case AvOp::MOVE_PARTITION:
            if (!op.mDrawable->isDead())
            {
                op.mDrawable->movePartition();
            }
            break;
        case AvOp::BRIDGE_MOVE:
            if (!op.mDrawable->isDead())
            {
                ((LLSpatialBridge*)op.mDrawable)->moveInPartition();
            }
            break;
        case AvOp::MAKE_ACTIVE_SHARED:
            if (!op.mDrawable->isDead())
            {
                op.mDrawable->makeActiveShared();
            }
            break;
        case AvOp::UPDATE_TEXT:
            if (op.mObject && !op.mObject->isDead())
            {
                op.mObject->updateText();
            }
            break;
        case AvOp::DIRTY_GROUP:
            if (op.mObject && !op.mObject->isDead())
            {
                op.mObject->dirtySpatialGroup();
            }
            break;
        case AvOp::RENDER_ORDER:
        {
            ++orders;
            LLSpatialGroup* group = op.mDrawable->getSpatialGroup();
            if (group != op.mSeenGroup)
            {
                ++stale_group;      // the loop saw another group than the one the drawable is in once the moves before this request were made
            }
            if (group)
            {
                group->mAvatarp = op.mAvatar;
                group->mRenderOrder = op.mOrder;
            }
            break;
        }
        }
    }
    total_ops += (U64)(end - begin);
    if (++calls % 6000 == 0)
    {
        LL_INFOS("AvLedger") << "avatar attachment ledger: " << calls << " avatar loops, " << (double)total_ops / calls << " writes each (moved list " << by_kind[AvOp::MOVED_LIST] << ", moved bridge " << by_kind[AvOp::MOVED_BRIDGE]
                             << ", partition moves " << by_kind[AvOp::MOVE_PARTITION] << ", bridge moves " << by_kind[AvOp::BRIDGE_MOVE] << ", render orders " << orders << "); render orders whose group differed from the one the loop saw: " << stale_group << LL_ENDL;
    }
}

void LLPipeline::updateMoveDampedAsync(LLDrawable* drawablep)
{
    LL_CPU_ZONE("pipeline: updateMoveDampedAsync");
    LL_PROFILE_ZONE_SCOPED;
    if (FreezeTime)
    {
        return;
    }
    if (!drawablep)
    {
        LL_ERRS() << "updateMove called with NULL drawablep" << LL_ENDL;
        return;
    }
    if (drawablep->isState(LLDrawable::EARLY_MOVE))
    {
        return;
    }

    assertInitialized();

    // update drawable now
    drawablep->clearState(LLDrawable::MOVE_UNDAMPED); // force to DAMPED
    drawablep->updateMove(); // returns done
    drawablep->setState(LLDrawable::EARLY_MOVE); // flag says we already did an undamped move this frame
    // Put on move list so that EARLY_MOVE gets cleared
    if (!drawablep->isState(LLDrawable::ON_MOVE_LIST))
    {
        if (sAvSink)
        {
            sAvSink->push_back({ AvOp::MOVED_LIST, drawablep, nullptr, nullptr, 0 });      // <FS> A1: the push is replayed, the bit is set at once
        }
        else
        {
            mMovedList.push_back(drawablep);
        }
        drawablep->setState(LLDrawable::ON_MOVE_LIST);
    }
}

void LLPipeline::updateMoveNormalAsync(LLDrawable* drawablep)
{
    LL_CPU_ZONE("pipeline: updateMoveNormalAsync");
    LL_PROFILE_ZONE_SCOPED;
    if (FreezeTime)
    {
        return;
    }
    if (!drawablep)
    {
        LL_ERRS() << "updateMove called with NULL drawablep" << LL_ENDL;
        return;
    }
    if (drawablep->isState(LLDrawable::EARLY_MOVE))
    {
        return;
    }

    assertInitialized();

    // update drawable now
    drawablep->setState(LLDrawable::MOVE_UNDAMPED); // force to UNDAMPED
    drawablep->updateMove();
    drawablep->setState(LLDrawable::EARLY_MOVE); // flag says we already did an undamped move this frame
    // Put on move list so that EARLY_MOVE gets cleared
    if (!drawablep->isState(LLDrawable::ON_MOVE_LIST))
    {
        if (sAvSink)
        {
            sAvSink->push_back({ AvOp::MOVED_LIST, drawablep, nullptr, nullptr, 0 });      // <FS> A1: the push is replayed, the bit is set at once
        }
        else
        {
            mMovedList.push_back(drawablep);
        }
        drawablep->setState(LLDrawable::ON_MOVE_LIST);
    }
}

int LLPipeline::coldMode()
{
    // <FS> default: the setting FSObjectExpiry (on = mode 4, Cold + Released + the object kill, as soaked in laps clK/clL/clQ on 2026-10-30); LL_VK_EXPIRY=0..4 overrides it (read once, a change needs a restart)
    static const int mode = getenv("LL_VK_EXPIRY") ? atoi(getenv("LL_VK_EXPIRY")) : (gSavedSettings.controlExists("FSObjectExpiry") && gSavedSettings.getBOOL("FSObjectExpiry") ? 4 : 0);
    return mode;
}

U64 LLPipeline::sRelReleased = 0, LLPipeline::sRelReleasedInfos = 0, LLPipeline::sRelWoken = 0, LLPipeline::sRelScans = 0;

// <FS> the groups of the VOLUME partitions that nobody has accepted for LL_VK_REL_FRAMES: release their draw infos
class LLReleaseTraveler : public OctreeTraveler
{
public:
    S32 mMinAge = 3600;
    U32 mLimit = 200;
    U32 mReleased = 0;
    virtual void visit(const OctreeNode* node)
    {
        if (mReleased >= mLimit)
        {
            return;
        }
        LLSpatialGroup* group = (LLSpatialGroup*)node->getListener(0);
        if (!group || group->isDead() || group->isEmpty() || group->mDrawMap.empty() || group->isHUDGroup() || !group->mBridgeList.empty())
        {
            return;
        }
        if (group->hasState(LLSpatialGroup::IN_BUILD_Q1 | LLSpatialGroup::IN_BUILD_Q2 | LLSpatialGroup::FS_RELEASED | LLSpatialGroup::FS_WAKING | LLSpatialGroup::GEOM_DIRTY | LLSpatialGroup::MESH_DIRTY | LLSpatialGroup::ALPHA_DIRTY))
        {
            return;
        }
        S32 latest = 0;
        for (S32 c = 0; c < LLViewerCamera::NUM_CAMERAS; ++c)
        {
            latest = std::max(latest, group->getVisible((LLViewerCamera::eCameraID)c));
        }
        if (latest <= 0 || LLViewerOctreeEntryData::getCurrentFrame() - latest <= mMinAge)
        {
            return;
        }
        U64 infos = 0;
        for (const auto& kv : group->mDrawMap)
        {
            infos += kv.second.size();
        }
        group->clearDrawMap();
        group->setState(LLSpatialGroup::GEOM_DIRTY | LLSpatialGroup::FS_RELEASED);
        ++mReleased;
        ++LLPipeline::sRelReleased;
        LLPipeline::sRelReleasedInfos += infos;
    }
};

void LLPipeline::releaseScan()
{
    if (coldMode() < 3)
    {
        return;
    }
    static const S32 min_age = getenv("LL_VK_REL_FRAMES") ? atoi(getenv("LL_VK_REL_FRAMES")) : 5400;
    static U32 last = 0;
    const U32 frame = (U32)LLFrameTimer::getFrameCount();
    if (frame - last < 60)
    {
        return;
    }
    last = frame;
    LL_CPU_ZONE("expiry: release scan");
    ++sRelScans;
    LLReleaseTraveler traveler;
    traveler.mMinAge = min_age;
    for (LLViewerRegion* region : LLWorld::getInstance()->getRegionList())
    {
        if (LLSpatialPartition* part = region->getSpatialPartition(LLViewerRegion::PARTITION_VOLUME))
        {
            traveler.traverse(part->mOctree);
        }
    }
}

// <FS> the wake queue is written by the threads of the parallel shadow preparation (markNotCulled of a Released group) as well as by the main thread: one lock for the queue and the FS_WAKING bit
static std::mutex sWakeMutex;

void LLPipeline::wakeRequest(LLSpatialGroup* group)
{
    std::lock_guard<std::mutex> lock(sWakeMutex);
    if (!group->hasState(LLSpatialGroup::FS_WAKING))
    {
        group->setState(LLSpatialGroup::FS_WAKING);
        mWakeQ.push_back(group);
    }
}

void LLPipeline::wakeForget(LLSpatialGroup* group)
{
    std::lock_guard<std::mutex> lock(sWakeMutex);
    mWakeQ.erase(std::remove(mWakeQ.begin(), mWakeQ.end(), group), mWakeQ.end());
}

void LLPipeline::wakeGroups()
{
    std::vector<LLSpatialGroup*> now;
    {
        std::lock_guard<std::mutex> lock(sWakeMutex);
        if (mWakeQ.empty())
        {
            return;
        }
        static const size_t per_frame = getenv("LL_VK_WAKE_PER_FRAME") ? (size_t)atoi(getenv("LL_VK_WAKE_PER_FRAME")) : 48;
        const size_t n = std::min(per_frame, mWakeQ.size());
        std::partial_sort(mWakeQ.begin(), mWakeQ.begin() + n, mWakeQ.end(), [](const LLSpatialGroup* a, const LLSpatialGroup* b) { return a->row().distance < b->row().distance; });
        now.assign(mWakeQ.begin(), mWakeQ.begin() + n);
        mWakeQ.erase(mWakeQ.begin(), mWakeQ.begin() + n);
    }
    LL_CPU_ZONE("expiry: wake groups");
    for (LLSpatialGroup* group : now)
    {
        group->clearState(LLSpatialGroup::FS_WAKING);
        if (!group->isDead() && group->hasState(LLSpatialGroup::FS_RELEASED))
        {
            group->setState(LLSpatialGroup::GEOM_DIRTY);
            markRebuild(group);
            ++sRelWoken;
        }
    }
}

U64 LLPipeline::sColdMovedSeen = 0, LLPipeline::sColdMovedSkipped = 0, LLPipeline::sColdTexAnimSeen = 0, LLPipeline::sColdTexAnimSkipped = 0, LLPipeline::sColdMovedWoken = 0;

bool LLPipeline::coldGroup(const LLSpatialGroup* group)
{
    static const S32 cold_frames = getenv("LL_VK_COLD_FRAMES") ? atoi(getenv("LL_VK_COLD_FRAMES")) : 600;
    if (!group)
    {
        return false;
    }
    S32 latest = 0;
    for (S32 c = 0; c < LLViewerCamera::NUM_CAMERAS; ++c)
    {
        latest = std::max(latest, group->getVisible((LLViewerCamera::eCameraID)c));
    }
    // (a group that was never accepted is not Cold: it may be new, and nothing is known about it yet)
    return latest > 0 && LLViewerOctreeEntryData::getCurrentFrame() - latest > cold_frames;
}

void LLPipeline::updateMovedList(LLDrawable::drawable_vector_t& moved_list)
{
    if (&moved_list == &mMovedList && updateMovedListParallel(moved_list))
    {
        return;
    }
    updateMovedListSerial(moved_list, 0);
}

void LLPipeline::updateMovedListSerial(LLDrawable::drawable_vector_t& moved_list, size_t first)
{
    LL_CPU_ZONE("pipeline: updateMovedList");
    LL_PROFILE_ZONE_SCOPED;
    // <FS> by index: updateMove marks the parent and the children of a drawable moved (markMoved, from makeActive), which pushes onto this very list; a push that moves the vector's storage left the iterator of the
    // old loop pointing at freed memory (a crash reading 0xFFFFFFFFFFFFFFFF during the loading of a crowd). An entry pushed during the pass is reached later in the same pass, as the loop always meant.
    size_t next = first;
    while (next < moved_list.size())
    {
        const size_t cur = next++;
        // <FS> an entry that is not a live drawable any more (the crashes of 2026-11-01 read a freed one at the start of the pass): logged with the stack of its destruction, taken off the list without touching it
        // (the slot is cleared in place: dropping the LLPointer would write the reference count of freed memory)
        if (const LLDrawable* raw = moved_list[cur].get())
        {
            // <FS> C1a: a destroyed drawable's instance row no longer names it (a vtable test alone passes a drawable that is mid-destruction or freed with its base class vtable still in place)
            if (!fs_drawable_looks_live(raw) || !raw->ownsInstanceRow())
            {
                static std::atomic<int> logged{0};
                if (logged.fetch_add(1) < 8)
                {
                    LL_WARNS("DrawableTrace") << "moved list entry " << cur << " of " << moved_list.size() << " (" << (const void*)raw << ") is not a live drawable; dropped; " << fs_drawable_destroy_info(raw) << LL_ENDL;
                }
                static_assert(sizeof(LLPointer<LLDrawable>) == sizeof(void*), "the slot is cleared as one pointer");
                *reinterpret_cast<void**>(&moved_list[cur]) = nullptr;
                moved_list.erase(moved_list.begin() + cur);
                next = cur;
                continue;
            }
        }
        // <FS> a counted reference for the pass over this entry: updateMove can unlink the drawable (unlinkDrawable erases its entry, which was the last reference), and the raw pointer was then used freed
        // (crashes of 2026-11-01 in updateMovedListSerial: the dump stopped at isRoot() after updateMove and clearState on the freed drawable, ~33 s after the login)
        LLPointer<LLDrawable> hold = moved_list[cur];
        LLDrawable *drawablep = hold.get();
        sMovedCurrent = drawablep;
        if (!drawablep)
        {
            moved_list.erase(moved_list.begin() + cur);
            next = cur;
            continue;
        }
        bool done = true;
        if (coldMode() > 0 && !drawablep->isDead() && drawablep->isRoot() && !drawablep->isState(LLDrawable::RIGGED | LLDrawable::RIGGED_CHILD | LLDrawable::EARLY_MOVE))
        {
            // Cold (see coldGroup): a plain root object whose group nobody has looked at for a while, and which is still inside that group, is left on the list unmoved; it is marked undamped so that it
            // jumps to where it is when the group is looked at again instead of sliding there. (Children of a Cold root were tried in lap cold2: 42 of the 89 children after a turn have a Cold root, skipping
            // them saved 0.03 ms in updateMovedList; the entries left are in view or are avatars' attachments. Not kept.)
            LLViewerObject* vobj = drawablep->getVObj();
            LLSpatialGroup* group = drawablep->getSpatialGroup();
            if (vobj && group && !vobj->isAvatar() && !vobj->isAttachment() && !vobj->isHUDAttachment())
            {
                ++sColdMovedSeen;
                if (coldGroup(group))
                {
                    const LLVector4a* b = group->getBounds();
                    LLVector4a p;
                    p.load3(vobj->getPositionAgent().mV);
                    LLVector4a d;
                    d.setSub(p, b[0]);
                    d.setAbs(d);
                    LLVector4a over;
                    over.setSub(d, b[1]);
                    if (over.getF32ptr()[0] <= 0.f && over.getF32ptr()[1] <= 0.f && over.getF32ptr()[2] <= 0.f)
                    {
                        ++sColdMovedSkipped;
                        if (coldMode() >= 2)
                        {
                            drawablep->setState(LLDrawable::MOVE_UNDAMPED);
                            continue;
                        }
                    }
                }
            }
        }
        if (LLAttCensus::sOn)
        {
            const LLAttCensus::Kind kind = LLAttCensus::kindOf(drawablep);
            ++LLAttCensus::sMovedListIter[kind];
            if (drawablep->isState(LLDrawable::EARLY_MOVE)) { ++LLAttCensus::sMovedListEarly[kind]; }
            else if (!drawablep->isDead()) { ++LLAttCensus::sMovedListByUpdate[kind]; }
        }
        if (!drawablep->isDead() && (!drawablep->isState(LLDrawable::EARLY_MOVE)))
        {
            done = drawablep->updateMove();
        }
        drawablep->clearState(LLDrawable::EARLY_MOVE | LLDrawable::MOVE_UNDAMPED);
        if (done)
        {
            if (drawablep->isRoot() && !drawablep->isState(LLDrawable::ACTIVE))
            {
                drawablep->makeStatic();
            }
            drawablep->clearState(LLDrawable::ON_MOVE_LIST);
            if (drawablep->isState(LLDrawable::ANIMATED_CHILD))
            { //will likely not receive any future world matrix updates
                // -- this keeps attachments from getting stuck in space and falling off your avatar
                drawablep->clearState(LLDrawable::ANIMATED_CHILD);
                markRebuild(drawablep, LLDrawable::REBUILD_VOLUME);
                if (drawablep->getVObj())
                {
                    drawablep->getVObj()->dirtySpatialGroup();
                }
            }
            // (the entry is where it was unless something erased entries of the list meanwhile)
            size_t at = cur;
            if (at >= moved_list.size() || moved_list[at].get() != drawablep)
            {
                at = moved_list.size();
                for (size_t k = 0; k < moved_list.size(); ++k)
                {
                    if (moved_list[k].get() == drawablep)
                    {
                        at = k;
                        break;
                    }
                }
            }
            if (at < moved_list.size())
            {
                moved_list.erase(moved_list.begin() + at);
                next = at;
            }
        }
    }
    sMovedCurrent = nullptr;
}

// <FS> view rework O1 (LL_VK_MOVED_PARALLEL=1; default off until soaked): see pipeline.h. The unit of a job is a linkset (a child reads its parent's transform, and the list holds parents first): every entry of
// a root, in list order, runs in one job whose writes to shared state (the moved lists, the octree moves, makeActive, the HUD text, the rebuild and partition marks, the group flags, the texture stamps) go
// into the job's ledgers. A serial pass in list order then makes each entry's writes and does its done handling, or runs the entry the old way when it is not plain (an avatar, an attachment, a flexible
// prim, a rigged or animated object, a linkset with one of those in it).
enum MovedAction : U8 { ERASE_NULL, KEEP, SERIAL, JOB };
struct MovedEnt
{
    LLDrawable* mDrawable = nullptr;
    MovedAction mAction = SERIAL;
    bool mDone = false;
    U32 mLinkset = 0;
    size_t mOps[2] = { 0, 0 };
    size_t mSort[2] = { 0, 0 };
    size_t mStamps[2] = { 0, 0 };
};
struct MovedLed
{
    std::vector<LLPipeline::AvOp> mOps;
    std::vector<LLPipeline::SortDelta> mSort;
    std::vector<LLFace*> mStamps;
    std::vector<U32> mEntries;
    bool mPlain = true;
};

static bool moved_entry_plain(LLDrawable* d)
{
    if (!d || d->isDead() || d->isSpatialBridge() || d->isState(LLDrawable::RIGGED | LLDrawable::RIGGED_CHILD))
    {
        return false;
    }
    LLViewerObject* vobj = d->getVObj();
    if (!vobj || vobj->isDead() || vobj->getPCode() != LL_PCODE_VOLUME || vobj->isAvatar() || vobj->isAttachment() || vobj->isHUDAttachment() || vobj->isAnimatedObject() || vobj->isRiggedMesh())
    {
        return false;
    }
    return !static_cast<LLVOVolume*>(vobj)->isFlexible();
}

bool LLPipeline::updateMovedListParallel(LLDrawable::drawable_vector_t& moved_list)
{
    static const int mode = getenv("LL_VK_MOVED_PARALLEL") ? atoi(getenv("LL_VK_MOVED_PARALLEL")) : 0;
    static const size_t kMinEntries = 48;
    if (mode == 0 || moved_list.size() < kMinEntries || LLAttCensus::sOn || ItemCensus::on() || LLGpuZoneTimer::isActive())
    {
        return false;
    }
    LLForkJoinPool* pool = LLForkJoinPool::shared();
    if (!pool)
    {
        return false;
    }
    LL_CPU_ZONE("pipeline: updateMovedList (parallel)");

    typedef MovedAction Action __attribute__((unused));
    typedef MovedEnt Ent;
    typedef MovedLed Led;
    static std::vector<Ent> ents;
    static std::vector<Led> leds;
    static std::unordered_map<LLDrawable*, U32> linkset_of;
    ents.clear();
    linkset_of.clear();
    size_t used_leds = 0;

    const size_t n = moved_list.size();
    ents.resize(n);
    for (size_t i = 0; i < n; ++i)
    {
        Ent& e = ents[i];
        LLDrawable* drawablep = moved_list[i];
        e.mDrawable = drawablep;
        if (!drawablep)
        {
            e.mAction = ERASE_NULL;
            continue;
        }
        // the cold skip, as in the serial loop (it leaves the entry on the list unmoved)
        if (coldMode() > 0 && !drawablep->isDead() && drawablep->isRoot() && !drawablep->isState(LLDrawable::RIGGED | LLDrawable::RIGGED_CHILD | LLDrawable::EARLY_MOVE))
        {
            LLViewerObject* vobj = drawablep->getVObj();
            LLSpatialGroup* group = drawablep->getSpatialGroup();
            if (vobj && group && !vobj->isAvatar() && !vobj->isAttachment() && !vobj->isHUDAttachment())
            {
                ++sColdMovedSeen;
                if (coldGroup(group))
                {
                    const LLVector4a* b = group->getBounds();
                    LLVector4a p;
                    p.load3(vobj->getPositionAgent().mV);
                    LLVector4a d;
                    d.setSub(p, b[0]);
                    d.setAbs(d);
                    LLVector4a over;
                    over.setSub(d, b[1]);
                    if (over.getF32ptr()[0] <= 0.f && over.getF32ptr()[1] <= 0.f && over.getF32ptr()[2] <= 0.f)
                    {
                        ++sColdMovedSkipped;
                        if (coldMode() >= 2)
                        {
                            drawablep->setState(LLDrawable::MOVE_UNDAMPED);
                            e.mAction = KEEP;
                            continue;
                        }
                    }
                }
            }
        }
        e.mAction = SERIAL;
        if (!drawablep->isDead() && !drawablep->isState(LLDrawable::EARLY_MOVE))
        {
            LLDrawable* root = drawablep->getRoot();
            auto it = linkset_of.find(root);
            if (it == linkset_of.end())
            {
                if (used_leds == leds.size())
                {
                    leds.emplace_back();
                }
                Led& led = leds[used_leds];
                led.mOps.clear();
                led.mSort.clear();
                led.mStamps.clear();
                led.mEntries.clear();
                led.mPlain = moved_entry_plain(root);
                it = linkset_of.emplace(root, (U32)used_leds).first;
                ++used_leds;
            }
            Led& led = leds[it->second];
            led.mPlain = led.mPlain && moved_entry_plain(drawablep);
            led.mEntries.push_back((U32)i);
            e.mLinkset = it->second;
        }
    }
    // a linkset becomes jobs only when every entry of it is plain
    std::vector<U32> job_leds;
    for (size_t k = 0; k < used_leds; ++k)
    {
        if (leds[k].mPlain)
        {
            job_leds.push_back((U32)k);
            for (U32 i : leds[k].mEntries)
            {
                ents[i].mAction = JOB;
            }
        }
    }
    static U64 calls = 0, entries_total = 0, job_entries = 0, linksets = 0, ops_total = 0, stamps_total = 0;
    ++calls;
    entries_total += n;
    job_entries += std::count_if(ents.begin(), ents.end(), [](const Ent& e) { return e.mAction == JOB; });
    linksets += job_leds.size();

    if (job_leds.size() >= 2)
    {
        const std::function<void(size_t)> job = [&](size_t j)
        {
            Led& led = leds[job_leds[j]];
            std::vector<AvOp>* saved_av = sAvSink;
            std::vector<SortDelta>* saved_sort = sSortSink;
            std::vector<LLFace*>* saved_stamps = LLFace::sStampSink;
            sAvSink = &led.mOps;
            sSortSink = &led.mSort;
            LLFace::sStampSink = &led.mStamps;
            for (U32 i : led.mEntries)
            {
                Ent& e = ents[i];
                e.mOps[0] = led.mOps.size();
                e.mSort[0] = led.mSort.size();
                e.mStamps[0] = led.mStamps.size();
                e.mDone = e.mDrawable->updateMove();
                e.mOps[1] = led.mOps.size();
                e.mSort[1] = led.mSort.size();
                e.mStamps[1] = led.mStamps.size();
            }
            sAvSink = saved_av;
            sSortSink = saved_sort;
            LLFace::sStampSink = saved_stamps;
        };
        pool->runLabeled("avatar attachment ledger", job_leds.size(), job);
    }
    else
    {
        // nothing worth a launch: every entry the old way
        for (Ent& e : ents)
        {
            if (e.mAction == JOB)
            {
                e.mAction = SERIAL;
            }
        }
    }

    // the writes and the done handling, in list order
    LLDrawable::drawable_vector_t kept;
    kept.reserve(n);
    for (size_t i = 0; i < n; ++i)
    {
        Ent& e = ents[i];
        LLDrawable* drawablep = e.mDrawable;
        if (e.mAction == ERASE_NULL)
        {
            continue;
        }
        if (e.mAction == KEEP)
        {
            kept.push_back(drawablep);
            continue;
        }
        bool done = true;
        if (e.mAction == JOB)
        {
            Led& led = leds[e.mLinkset];
            applyAvOpsRange(led.mOps.data() + e.mOps[0], led.mOps.data() + e.mOps[1]);
            applySortDeltasRange(led.mSort.data() + e.mSort[0], led.mSort.data() + e.mSort[1]);
            for (size_t k = e.mStamps[0]; k < e.mStamps[1]; ++k)
            {
                led.mStamps[k]->stampTextures();
            }
            ops_total += e.mOps[1] - e.mOps[0];
            stamps_total += e.mStamps[1] - e.mStamps[0];
            done = e.mDone;
        }
        else if (!drawablep->isDead() && !drawablep->isState(LLDrawable::EARLY_MOVE))
        {
            done = drawablep->updateMove();
        }
        drawablep->clearState(LLDrawable::EARLY_MOVE | LLDrawable::MOVE_UNDAMPED);
        if (done)
        {
            if (drawablep->isRoot() && !drawablep->isState(LLDrawable::ACTIVE))
            {
                drawablep->makeStatic();
            }
            drawablep->clearState(LLDrawable::ON_MOVE_LIST);
            if (drawablep->isState(LLDrawable::ANIMATED_CHILD))
            {
                drawablep->clearState(LLDrawable::ANIMATED_CHILD);
                markRebuild(drawablep, LLDrawable::REBUILD_VOLUME);
                if (drawablep->getVObj())
                {
                    drawablep->getVObj()->dirtySpatialGroup();
                }
            }
        }
        else
        {
            kept.push_back(drawablep);
        }
    }
    // what the serial entries and the replayed writes pushed while this ran is the tail of the list: the old loop reached those entries in the same call
    LLDrawable::drawable_vector_t tail;
    if (moved_list.size() > n)
    {
        tail.assign(moved_list.begin() + n, moved_list.end());
    }
    moved_list = kept;
    const size_t first_tail = moved_list.size();
    moved_list.insert(moved_list.end(), tail.begin(), tail.end());
    if (!tail.empty())
    {
        updateMovedListSerial(moved_list, first_tail);
    }
    if (calls % 3000 == 0)
    {
        LL_INFOS("MovedParallel") << "moved list in " << calls << " calls: " << (double)entries_total / calls << " entries a call, " << (double)job_entries / calls << " of them run as jobs in "
                                  << (double)linksets / calls << " linksets; writes replayed a call " << (double)ops_total / calls << ", texture stamps " << (double)stamps_total / calls << LL_ENDL;
    }
    return true;
}

// <FS> LL_VK_SCENECENSUS=1: how much the scene holds (objects, drawables, spatial groups with built geometry, draw infos and triangles, lights, queues) against what is inside the world camera's frustum.
// The cost that stays after a turn (section 17.16) grows with what has been built; this shows how much of it is in view.
static void shadow_census_report(U32 frames);       // (below, with the shadow pass)

// <FS> LL_VK_SCENECENSUS: what calcNearbyLights goes through each call (the nearby set holds every light within the far clip, not only the ones drawn)
static struct LightLoopCensus
{
    U64 mCalls = 0, mUpdated = 0, mScans = 0, mScanned = 0, mDropped = 0, mInserted = 0;
} sLightLoopCensus;

void LLPipeline::sceneStateCensus()
{
    static const bool on = getenv("LL_VK_SCENECENSUS") != nullptr;
    if (!on)
    {
        return;
    }
    static U32 last = 0;
    const U32 frame = (U32)LLFrameTimer::getFrameCount();
    if (frame - last < 600)
    {
        return;
    }
    last = frame;
    shadow_census_report(600);
    if (coldMode() > 0)
    {
        LL_INFOS("SceneCensus") << "Cold (LL_VK_EXPIRY=" << coldMode() << "): over 600 frames, moved list entries looked at " << sColdMovedSeen / 600.0 << "/frame, " << (coldMode() >= 2 ? "skipped " : "that would be skipped ")
            << sColdMovedSkipped / 600.0 << "/frame; animated texture objects looked at " << sColdTexAnimSeen / 600.0 << "/frame, " << (coldMode() >= 2 ? "skipped " : "that would be skipped ") << sColdTexAnimSkipped / 600.0 << "/frame" << LL_ENDL;
        sColdMovedSeen = sColdMovedSkipped = sColdTexAnimSeen = sColdTexAnimSkipped = 0;
        if (coldMode() >= 3)
        {
            LL_INFOS("SceneCensus") << "Released: " << sRelReleased << " groups released so far (" << sRelReleasedInfos << " draw infos), woken " << sRelWoken << ", waiting in the wake queue " << mWakeQ.size() << ", scans " << sRelScans << LL_ENDL;
        }
        if (coldMode() >= 4)
        {
            extern void fs_kill_report();       // (llviewerregion.cpp: the object kill stage)
            fs_kill_report();
        }
    }
    LLCamera& camera = *LLViewerCamera::getInstance();
    U64 objects = 0, drawables = 0, active = 0, avatars = 0, attachments = 0, rigged = 0, with_text = 0;
    U64 act_kind[7][2] = {}, list_kind[7][2] = {};      // [kind][in view]: avatar, HUD attachment, attachment, child prim, root with a cache entry, other root volume, other pcode
    U64 act_reason[12][2] = {};                         // [why it can be on the active lists][in view]; an object can have several, the last row is the ones with none of them
    std::unordered_set<LLSpatialGroup*> groups;
    const S32 count = gObjectList.getNumObjects();
    for (S32 i = 0; i < count; ++i)
    {
        LLViewerObject* object = gObjectList.getObject(i);
        if (!object || object->isDead())
        {
            continue;
        }
        ++objects;
        avatars += object->isAvatar();
        attachments += object->isAttachment();
        LLDrawable* drawable = object->mDrawable;
        if (!drawable)
        {
            continue;
        }
        ++drawables;
        active += drawable->isState(LLDrawable::ACTIVE);
        if (drawable->isState(LLDrawable::ACTIVE) || object->onActiveList())
        {
            // who the active ones are (they cost a little every frame, and they roughly double after a turn): kind x (in view or not); "list" = on the object list that gets an idleUpdate every frame
            const bool view = camera.sphereInFrustum(drawable->getPositionAgent(), drawable->getRadius()) != 0;
            int kind = object->isAvatar() ? 0 : object->isHUDAttachment() ? 1 : object->isAttachment() ? 2 : drawable->getParent() ? 3
                : (drawable->getEntry() && drawable->getEntry()->hasVOCacheEntry()) ? 4 : object->getPCode() == LL_PCODE_VOLUME ? 5 : 6;
            if (drawable->isState(LLDrawable::ACTIVE)) { ++act_kind[kind][view]; }
            if (object->onActiveList()) { ++list_kind[kind][view]; }
            {
                LLVOVolume* vol = object->getPCode() == LL_PCODE_VOLUME ? (LLVOVolume*)object : nullptr;
                bool any = false;
                auto note = [&](int reason, bool yes) { if (yes) { ++act_reason[reason][view]; any = true; } };
                note(0, drawable->isState(LLDrawable::ON_MOVE_LIST));
                note(1, vol && vol->mTextureAnimp);
                note(2, object->isParticleSource());
                note(3, vol && vol->isFlexible());
                note(4, object->mText.notNull());
                note(5, object->isAudioSource());
                note(6, object->isAnimatedObject());
                note(7, vol && vol->getIsLight());
                note(8, vol && vol->hasMedia());
                note(9, object->isSelected());
                if (!any) { ++act_reason[11][view]; }
            }
        }
        rigged += drawable->isState(LLDrawable::RIGGED | LLDrawable::RIGGED_CHILD);
        with_text += object->mText.notNull();
        if (LLSpatialGroup* group = drawable->getSpatialGroup())
        {
            groups.insert(group);
        }
    }
    U64 built = 0, in_frustum = 0, built_out = 0, infos = 0, infos_in = 0, tris = 0, tris_in = 0, elements = 0, elements_in = 0, visible_flag = 0;
    constexpr int kAgeBuckets = 8;
    struct AgeBucket { U64 mGroups = 0, mBuilt = 0, mInfos = 0, mTris = 0, mBytes = 0, mElements = 0, mActive = 0; };
    AgeBucket ages[2][kAgeBuckets];
    static std::chrono::steady_clock::time_point last_time;
    const auto now_time = std::chrono::steady_clock::now();
    const F64 seconds_per_frame = last_time.time_since_epoch().count() ? std::chrono::duration<F64>(now_time - last_time).count() / 600.0 : 0.0166;
    last_time = now_time;
    for (LLSpatialGroup* group : groups)
    {
        if (group->isDead())
        {
            continue;
        }
        const LLVector4a* b = group->getBounds();
        const bool in = camera.AABBInFrustum(b[0], b[1]) != 0;
        U64 group_infos = 0, group_tris = 0;
        for (const auto& kv : group->mDrawMap)
        {
            for (const LLDrawInfo* info : kv.second)
            {
                ++group_infos;
                group_tris += info->mCount / 3;
            }
        }
        const bool has = group_infos > 0;
        built += has;
        in_frustum += in;
        built_out += has && !in;
        infos += group_infos;
        tris += group_tris;
        elements += group->getElementCount();
        if (in)
        {
            infos_in += group_infos;
            tris_in += group_tris;
            elements_in += group->getElementCount();
        }
        visible_flag += group->isVisible();
        {
            // stage 1 of doc/vulkan/EXPIRY-design.md: the age of the group's relevance, the latest frame any camera accepted it (world, cascades, reflection probes, mirrors, snapshots)
            S32 latest = 0;
            for (S32 c = 0; c < LLViewerCamera::NUM_CAMERAS; ++c)
            {
                latest = std::max(latest, group->getVisible((LLViewerCamera::eCameraID)c));
            }
            S32 bucket = kAgeBuckets - 1;     // never accepted
            if (latest > 0)
            {
                const F64 age_s = (F64)(LLViewerOctreeEntryData::getCurrentFrame() - latest) * seconds_per_frame;
                bucket = age_s < 1.0 ? 0 : age_s < 5.0 ? 1 : age_s < 10.0 ? 2 : age_s < 30.0 ? 3 : age_s < 60.0 ? 4 : age_s < 300.0 ? 5 : 6;
            }
            U64 group_active = 0;
            for (LLSpatialGroup::element_iter i = group->getDataBegin(); i != group->getDataEnd(); ++i)
            {
                const LLDrawable* d = (const LLDrawable*)(*i)->getDrawable();
                group_active += d && d->isState(LLDrawable::ACTIVE);
            }
            const bool volume = group->getSpatialPartition() && group->getSpatialPartition()->mPartitionType == LLViewerRegion::PARTITION_VOLUME;
            for (int set = 0; set < 2; ++set)
            {
                if (set == 1 && !volume)
                {
                    continue;
                }
                AgeBucket& a = ages[set][bucket];
                ++a.mGroups;
                a.mBuilt += has;
                a.mInfos += group_infos;
                a.mTris += group_tris;
                a.mBytes += group->mGeometryBytes;
                a.mElements += group->getElementCount();
                a.mActive += group_active;
            }
        }
    }
    {
        static const char* const names[kAgeBuckets] = { "<1 s", "1-5 s", "5-10 s", "10-30 s", "30-60 s", "60-300 s", ">300 s", "never" };
        for (int set = 0; set < 2; ++set)
        {
            std::string text;
            for (int k = 0; k < kAgeBuckets; ++k)
            {
                const AgeBucket& a = ages[set][k];
                text += llformat(" [%s: %llu groups, %llu built, %llu draw infos, %llu k tris, %.1f MB, %llu elements, %llu active]", names[k], (unsigned long long)a.mGroups, (unsigned long long)a.mBuilt,
                    (unsigned long long)a.mInfos, (unsigned long long)(a.mTris / 1000), (double)a.mBytes / 1048576.0, (unsigned long long)a.mElements, (unsigned long long)a.mActive);
            }
            LL_INFOS("SceneCensus") << "age of relevance (" << (set ? "VOLUME partition" : "all groups of the objects") << ", " << seconds_per_frame * 1000.0 << " ms a frame):" << text << LL_ENDL;
        }
    }
    {
        static const char* const kinds[7] = { "avatars", "HUD", "attachments", "child prims", "roots cached", "roots uncached", "other" };
        std::string a, l;
        for (int k = 0; k < 7; ++k)
        {
            a += llformat(" %s %llu (%llu in view)", kinds[k], (unsigned long long)(act_kind[k][0] + act_kind[k][1]), (unsigned long long)act_kind[k][1]);
            l += llformat(" %s %llu (%llu in view)", kinds[k], (unsigned long long)(list_kind[k][0] + list_kind[k][1]), (unsigned long long)list_kind[k][1]);
        }
        LL_INFOS("SceneCensus") << "active drawables by kind:" << a << " | on the active object list:" << l << LL_ENDL;
        static const char* const reasons[12] = { "on the moved list", "texture animation", "particle source", "flexible", "hover text", "audio source", "animated object", "light", "media", "selected", "(unused)", "none of these" };
        std::string r;
        for (int k = 0; k < 12; ++k)
        {
            if (k == 10) { continue; }
            r += llformat(" %s %llu (%llu in view)", reasons[k], (unsigned long long)(act_reason[k][0] + act_reason[k][1]), (unsigned long long)act_reason[k][1]);
        }
        LL_INFOS("SceneCensus") << "why the active and listed objects are active (an object can have several):" << r << LL_ENDL;
    }
    {
        extern void fs_leave_census_report(double frames);      // (llspatialpartition.cpp, LL_VK_LEAVECENSUS=1)
        fs_leave_census_report(600.0);
    }
    {
        // why the entries of the moved list are not skipped by the Cold stage (coldGroup / updateMovedList): not a plain root, or which cameras still had their group within LL_VK_COLD_FRAMES (600)
        static const S32 cold_frames = getenv("LL_VK_COLD_FRAMES") ? atoi(getenv("LL_VK_COLD_FRAMES")) : 600;
        const S32 now_frame = LLViewerOctreeEntryData::getCurrentFrame();
        U64 total = 0, dead = 0, avatars = 0, rigged = 0, children = 0, no_group = 0, eligible = 0, never = 0, cold = 0, outside_group = 0, children_cold = 0, children_world = 0, children_other = 0;
        U64 fresh_by[LLViewerCamera::NUM_CAMERAS] = {}, only_by[LLViewerCamera::NUM_CAMERAS] = {}, world_fresh = 0, shadow_only = 0, water_only = 0, shadow_or_water_only = 0;
        for (const auto& moved : mMovedList)
        {
            LLDrawable* d = moved;
            ++total;
            if (!d || d->isDead()) { ++dead; continue; }
            LLViewerObject* vobj = d->getVObj();
            if (!vobj || vobj->isAvatar() || vobj->isAttachment() || vobj->isHUDAttachment()) { ++avatars; continue; }
            if (d->isState(LLDrawable::RIGGED | LLDrawable::RIGGED_CHILD)) { ++rigged; continue; }
            if (!d->isRoot())
            {
                // a child follows its linkset's root: how many have a root nobody has looked at (the Cold test below for roots), and how many a root the world camera has
                ++children;
                LLDrawable* top = d;
                while (top->getParent()) { top = top->getParent(); }
                LLSpatialGroup* top_group = top->getSpatialGroup();
                LLViewerObject* top_vobj = top->getVObj();
                if (!top_group || !top_vobj || top_vobj->isAvatar()) { ++children_other; continue; }
                S32 latest = 0;
                for (S32 c = 0; c < LLViewerCamera::NUM_CAMERAS; ++c) { latest = std::max(latest, top_group->getVisible((LLViewerCamera::eCameraID)c)); }
                const S32 world_stamp = top_group->getVisible(LLViewerCamera::CAMERA_WORLD);
                if (latest > 0 && now_frame - latest > cold_frames) { ++children_cold; }
                else if (world_stamp > 0 && now_frame - world_stamp <= cold_frames) { ++children_world; }
                else { ++children_other; }
                continue;
            }
            LLSpatialGroup* group = d->getSpatialGroup();
            if (!group) { ++no_group; continue; }
            ++eligible;
            S32 fresh_count = 0, last_fresh = -1;
            bool any_seen = false;
            for (S32 c = 0; c < LLViewerCamera::NUM_CAMERAS; ++c)
            {
                const S32 stamp = group->getVisible((LLViewerCamera::eCameraID)c);
                any_seen |= stamp > 0;
                if (stamp > 0 && now_frame - stamp <= cold_frames)
                {
                    ++fresh_by[c];
                    ++fresh_count;
                    last_fresh = c;
                }
            }
            if (!any_seen) { ++never; continue; }
            if (fresh_count == 0) { ++cold; continue; }
            if (fresh_count == 1) { ++only_by[last_fresh]; }
            const bool world = now_frame - group->getVisible(LLViewerCamera::CAMERA_WORLD) <= cold_frames && group->getVisible(LLViewerCamera::CAMERA_WORLD) > 0;
            if (world) { ++world_fresh; }
            else
            {
                bool shadow = false, water = false;
                for (S32 c = LLViewerCamera::CAMERA_SUN_SHADOW0; c < LLViewerCamera::NUM_CAMERAS; ++c)
                {
                    const S32 stamp = group->getVisible((LLViewerCamera::eCameraID)c);
                    if (stamp > 0 && now_frame - stamp <= cold_frames)
                    {
                        (c <= LLViewerCamera::CAMERA_SPOT_SHADOW1 ? shadow : water) = true;
                    }
                }
                if (shadow && !water) { ++shadow_only; } else if (water && !shadow) { ++water_only; } else { ++shadow_or_water_only; }
            }
            if (!world) { /* (counted above) */ }
        }
        (void)outside_group;
        LL_INFOS("SceneCensus") << "moved list " << total << ": dead " << dead << ", avatars/attachments " << avatars << ", rigged " << rigged << ", children " << children << " (root cold " << children_cold << ", root fresh for the world camera " << children_world << ", other " << children_other << "), no group " << no_group
            << "; plain roots " << eligible << " of which never accepted by a camera " << never << ", cold (no camera within " << cold_frames << " frames) " << cold << ", fresh for the world camera " << world_fresh
            << ", fresh only for the shadow cameras " << shadow_only << ", only for the water cameras " << water_only << ", for both and not the world " << shadow_or_water_only
            << " | groups fresh by camera: world " << fresh_by[0] << ", sun0-3 " << fresh_by[1] << "/" << fresh_by[2] << "/" << fresh_by[3] << "/" << fresh_by[4] << ", spot " << fresh_by[5] << "/" << fresh_by[6]
            << ", water " << fresh_by[7] << "/" << fresh_by[8] << LL_ENDL;
    }
    {
        const LightLoopCensus& c = sLightLoopCensus;
        const F64 n = (F64)std::max<U64>(1, c.mCalls);
        LL_INFOS("SceneCensus") << "calcNearbyLights over " << c.mCalls << " calls: nearby lights updated " << (F64)c.mUpdated / n << " a call (dropped " << (F64)c.mDropped / n << ", inserted " << (F64)c.mInserted / n
            << "), scans " << (F64)c.mScans / n << " a call each over " << (c.mScans ? (F64)c.mScanned / (F64)c.mScans : 0.0) << " lights; RenderLocalLightCount "
            << gSavedSettings.getS32("RenderLocalLightCount") << " is how many of the nearby set are drawn" << LL_ENDL;
        sLightLoopCensus = LightLoopCensus();
        U64 hud_total, hud_visible, hud_unreferenced, hud_types[24];
        LLHUDObject::census(hud_total, hud_visible, hud_unreferenced, hud_types);
        std::string types;
        for (U32 i = 0; i < 24; ++i)
        {
            if (hud_types[i])
            {
                types += llformat(" type %u: %llu,", i, (unsigned long long)hud_types[i]);
            }
        }
        LL_INFOS("SceneCensus") << "HUD objects (sorted by distance every frame): " << hud_total << " (visible " << hud_visible << ", with no owner left " << hud_unreferenced << "), by type:" << types << LL_ENDL;
    }
    {
        // a read-only walk over every object and its drawable (what the per-frame loops over the object list do, without the work): ns an object, best of 3. If it grows after a turn, the same
        // walk is slower for the same instructions: the objects are further apart in memory (cache and TLB misses), not more work.
        const S32 n = gObjectList.getNumObjects();
        F64 best = 1e30;
        U64 sink = 0;
        for (int pass = 0; pass < 3; ++pass)
        {
            const auto t0 = std::chrono::steady_clock::now();
            for (S32 i = 0; i < n; ++i)
            {
                LLViewerObject* object = gObjectList.getObject(i);
                if (object)
                {
                    LLDrawable* drawable = object->mDrawable;
                    sink += (U64)object->getPCode() + (drawable ? (U64)drawable->getState() : 0u);
                }
            }
            const F64 ns = std::chrono::duration<F64, std::nano>(std::chrono::steady_clock::now() - t0).count();
            best = std::min(best, ns);
        }
        static volatile U64 sink_out;
        sink_out = sink;
        LL_INFOS("SceneCensus") << "object walk: " << n << " objects, " << (n ? best / n : 0.0) << " ns an object (" << best / 1.0e6 << " ms the whole list, best of 3, touching the object and its drawable)" << LL_ENDL;
    }
    U64 lights_visible = 0;
    for (LLDrawable* light : mLights)
    {
        lights_visible += light && light->isVisible();
    }
    LL_INFOS("SceneCensus") << "objects " << objects << " (avatars " << avatars << ", attachments " << attachments << ", active objects " << gObjectList.getNumActiveObjects() << "), drawables " << drawables
        << " (active " << active << ", rigged " << rigged << ", with hover text " << with_text << ") | spatial groups of the objects " << groups.size() << ": with built geometry " << built << ", inside the frustum " << in_frustum
        << ", built and outside " << built_out << ", flagged visible " << visible_flag << " | draw infos " << infos << " (inside the frustum " << infos_in << "), triangles " << (tris / 1000) << " k (inside " << (tris_in / 1000)
        << " k), elements " << elements << " (inside " << elements_in << ") | lights " << mLights.size() << " (visible " << lights_visible << ", nearby " << mNearbyLights.size() << ") | queues: moved " << mMovedList.size()
        << ", moved bridges " << mMovedBridge.size() << ", build " << mBuildQ1.size() << ", groups to rebuild " << mGroupQ1.size() << ", mesh dirty " << mMeshDirtyGroup.size() << ", retextured " << mRetexturedList.size() << LL_ENDL;
}

// <FS> LL_VK_CPUPROBE=1 (doc/vulkan/PLAN-texture-handles.md section 17.22): after a turn the main thread loop is 2.8 ms slower and zones that do not depend on the scene (the UI) are 14-26% slower too.
// Three fixed pieces of work with the same input every frame, in zones of their own: a chain of dependent adds and multiplies (clock speed, a busy sibling thread), a pointer chase through 128 KB
// (the L2 cache) and through 128 MB (past the L3 cache, to memory). If they get slower after the turn the thread itself is slower (cache, clock, scheduling) and not only the work it does.
extern std::atomic<int> gFsWorkerCpu;
extern std::atomic<unsigned> gFsWorkerTid;

void LLPipeline::pinMainThread()
{
    static bool done = false;
    if (done)
    {
        return;
    }
    done = true;
    char pin[16] = {};
    if (GetEnvironmentVariableA("LL_VK_PIN_MAIN", pin, sizeof(pin)) > 0)
    {
        const int cpu = atoi(pin);
        const DWORD_PTR previous = SetThreadAffinityMask(GetCurrentThread(), (DWORD_PTR)1 << cpu);
        LL_INFOS("CpuProbe") << "main thread pinned to logical cpu " << cpu << (previous ? " (done)" : " (FAILED)") << LL_ENDL;
    }
}

// <FS> LL_VK_CPUPROBE core census: which logical processor the main thread runs on each frame (and the one the render worker last ran on at its frame end), how often either moves, and how often they sit on the same physical
// core (logical processors 2k and 2k+1 are the two threads of a core on this chip) or in the same group of 16 (one CCD, assuming the numbering). Logged every 600 frames.
static void core_census()
{
    static U32 hist_main[64] = {}, hist_worker[64] = {};
    static int prev_main = -1, prev_worker = -1;
    static U64 frames = 0, main_moves = 0, main_ccd_moves = 0, worker_moves = 0, worker_ccd_moves = 0, same_core = 0, same_ccd = 0, worker_is_main = 0;
    const int m = (int)GetCurrentProcessorNumber();
    const int w = gFsWorkerCpu.load(std::memory_order_relaxed);
    ++frames;
    ++hist_main[m & 63];
    if (prev_main >= 0 && m != prev_main) { ++main_moves; main_ccd_moves += (m >> 4) != (prev_main >> 4); }
    prev_main = m;
    if (w >= 0)
    {
        ++hist_worker[w & 63];
        if (prev_worker >= 0 && w != prev_worker) { ++worker_moves; worker_ccd_moves += (w >> 4) != (prev_worker >> 4); }
        prev_worker = w;
        same_core += (m >> 1) == (w >> 1);
        same_ccd += (m >> 4) == (w >> 4);
        worker_is_main += gFsWorkerTid.load(std::memory_order_relaxed) == (unsigned)GetCurrentThreadId();
    }
    if (frames < 600)
    {
        return;
    }
    auto top = [](const U32* hist_in)
    {
        U32 hist[64];
        memcpy(hist, hist_in, sizeof(hist));
        std::string text;
        for (int k = 0; k < 4; ++k)
        {
            int best = -1;
            for (int i = 0; i < 64; ++i) if (hist[i] && (best < 0 || hist[i] > hist[best])) best = i;
            if (best < 0) break;
            char buf[48];
            snprintf(buf, sizeof(buf), "cpu %d %.0f%%  ", best, hist[best] * 100.0 / 600.0);
            text += buf;
            hist[best] = 0;
        }
        return text;
    };
    LL_INFOS("CpuProbe") << "core census over 600 frames: main thread on [" << top(hist_main) << "] moved " << main_moves / 600.0 << "/frame (to the other group of 16: " << main_ccd_moves / 600.0
        << "); render worker (at its frame end) on [" << top(hist_worker) << "] moved " << worker_moves / 600.0 << "/frame (other group: " << worker_ccd_moves / 600.0 << "); same physical core "
        << same_core * 100.0 / 600.0 << "% of frames, same group of 16 " << same_ccd * 100.0 / 600.0 << "%" << (worker_is_main ? " (the worker sample came from the main thread itself)" : "") << LL_ENDL;
    memset(hist_main, 0, sizeof(hist_main));
    memset(hist_worker, 0, sizeof(hist_worker));
    frames = main_moves = main_ccd_moves = worker_moves = worker_ccd_moves = same_core = same_ccd = worker_is_main = 0;
}

void LLPipeline::cpuProbe()
{
    static const bool on = getenv("LL_VK_CPUPROBE") != nullptr;
    if (!on)
    {
        return;
    }
    core_census();
    static std::vector<U32> small_chain, big_chain, l2_chain, l3_chain, l3big_chain;
    if (small_chain.empty())
    {
        auto make = [](std::vector<U32>& chain, size_t count)
        {
            chain.resize(count);
            std::vector<U32> order(count);
            for (size_t i = 0; i < count; ++i) order[i] = (U32)i;
            U64 s = 0x9E3779B97F4A7C15ull;
            for (size_t i = count - 1; i > 0; --i)      // (a fixed shuffle: one cycle through every element)
            {
                s = s * 6364136223846793005ull + 1442695040888963407ull;
                std::swap(order[i], order[(size_t)((s >> 33) % (i + 1))]);
            }
            for (size_t i = 0; i < count; ++i) chain[order[i]] = order[(i + 1) % count];
        };
        make(small_chain, 32768);           // 128 KB
        make(big_chain, 32u << 20);         // 128 MB
        make(l2_chain, 512u << 10);         // 2 MB (about L2)
        make(l3_chain, 2u << 20);           // 8 MB (inside L3)
        make(l3big_chain, 8u << 20);        // 32 MB (the edge of L3)
    }
    static volatile U64 sink = 0;
    {
        LL_CPU_ZONE("probe: dependent arithmetic (100k)");
        U64 x = 12345;
        for (int i = 0; i < 100000; ++i) x = x * 2862933555777941757ull + 3037000493ull;
        sink = x;
    }
    {
        LL_CPU_ZONE("probe: pointer chase 128 KB (20k)");
        U32 p = 0;
        for (int i = 0; i < 20000; ++i) p = small_chain[p];
        sink = p;
    }
    {
        // the middle sizes (a chase that fits L1 or reaches DRAM does not feel another thread's data in the shared cache; these do)
        LL_CPU_ZONE("probe: pointer chase 2 MB (20k)");
        static U32 q2 = 0;
        for (int i = 0; i < 20000; ++i) q2 = l2_chain[q2];
        sink = q2;
    }
    {
        LL_CPU_ZONE("probe: pointer chase 8 MB (20k)");
        static U32 q3 = 0;
        for (int i = 0; i < 20000; ++i) q3 = l3_chain[q3];
        sink = q3;
    }
    {
        LL_CPU_ZONE("probe: pointer chase 32 MB (10k)");
        static U32 q4 = 0;
        for (int i = 0; i < 10000; ++i) q4 = l3big_chain[q4];
        sink = q4;
    }
    {
        LL_CPU_ZONE("probe: pointer chase 128 MB (1k)");
        static U32 q = 0;
        for (int i = 0; i < 1000; ++i) q = big_chain[q];
        sink = q;
    }
}

void LLPipeline::updateMove()
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;

    { extern void fs_growth_probe(); fs_growth_probe(); }   // <FS> LL_VK_GROWTH=1

    if (FreezeTime)
    {
        return;
    }

    assertInitialized();

    for (LLDrawable::drawable_set_t::iterator iter = mRetexturedList.begin();
            iter != mRetexturedList.end(); ++iter)
    {
        LLDrawable* drawablep = *iter;
        if (drawablep && !drawablep->isDead())
        {
            drawablep->updateTexture();
        }
    }
    mRetexturedList.clear();

    updateMovedList(mMovedList);

    //balance octrees
    LL_CPU_ZONE("octree: balance (all partitions)");
    ItemCensus::Scope census_scope(ItemCensus::BALANCE);
    for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin();
        iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
    {
        LLViewerRegion* region = *iter;
        for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
        {
            LLSpatialPartition* part = region->getSpatialPartition(i);
            if (part)
            {
                part->mOctree->balance();
                ItemCensus::add(ItemCensus::BALANCE, 1);
            }
        }

        //balance the VO Cache tree
        LLVOCachePartition* vo_part = region->getVOCachePartition();
        if(vo_part)
        {
            vo_part->mOctree->balance();
        }
    }
}

