bool LLPipeline::visibleObjectsInFrustum(LLCamera& camera)
{
    for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin();
            iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
    {
        LLViewerRegion* region = *iter;

        for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
        {
            LLSpatialPartition* part = region->getSpatialPartition(i);
            if (part)
            {
                if (hasRenderType(part->mDrawableType))
                {
                    if (part->visibleObjectsInFrustum(camera))
                    {
                        return true;
                    }
                }
            }
        }
    }

    return false;
}

bool LLPipeline::getVisibleExtents(LLCamera& camera, LLVector3& min, LLVector3& max)
{
    const F32 X = 65536.f;

    min = LLVector3(X,X,X);
    max = LLVector3(-X,-X,-X);

    LLViewerCamera::eCameraID saved_camera_id = LLViewerCamera::sCurCameraID;
    LLViewerCamera::sCurCameraID = LLViewerCamera::CAMERA_WORLD;

    bool res = true;

    for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin();
            iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
    {
        LLViewerRegion* region = *iter;

        for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
        {
            LLSpatialPartition* part = region->getSpatialPartition(i);
            if (part)
            {
                if (hasRenderType(part->mDrawableType))
                {
                    if (!part->getVisibleExtents(camera, min, max))
                    {
                        res = false;
                    }
                }
            }
        }
    }

    LLViewerCamera::sCurCameraID = saved_camera_id;
    return res;
}

static LLTrace::BlockTimerStatHandle FTM_CULL("Object Culling");

// static
bool LLPipeline::isWaterClip()
{
    // We always pretend that we're not clipping water when rendering mirrors.
    return (gPipeline.mHeroProbeManager.isMirrorPass()) ? false : (!sRenderTransparentWater || gCubeSnapshot) && !sRenderingHUDs;
}

// <FS> The occlusion groups of a cull result were flagged ACTIVE_OCCLUSION by markOccluder(); doOcclusion() clears the flag when it queries them. A result thrown away before that (the early
// sort redoes the cull of a frame) leaves the flag on: markOccluder() skips a flagged group, so it would never be queried again and would stay occluded. Called with the result of this frame.
void LLPipeline::dropOcclusionMarks(LLCullResult& result)
{
    for (LLCullResult::sg_iterator iter = result.beginOcclusionGroups(); iter != result.endOcclusionGroups(); ++iter)
    {
        LLSpatialGroup* group = *iter;
        if (!group->isDead())
        {
            group->clearOcclusionState(LLSpatialGroup::ACTIVE_OCCLUSION);
        }
    }
}

// <FS> native-vk diagnostic (LL_VK_AVLOG=1, LL_VK_AVLOG_NAME=part of a name, any case): every 5 seconds one line per avatar (all of the nearest twelve, or those whose name contains the text): what kind of avatar it is
// (self, animesh control avatar, fully loaded, impostor, sitting, distance) and its attachments with their faces: rigged or not, mesh, fullbright, glow, blended (alpha below 1), shiny, glTF material. Tag VkAvLog.
static void vk_avatar_log()
{
    static const bool on = getenv("LL_VK_AVLOG") != nullptr;
    if (!on)
    {
        return;
    }
    static LLFrameTimer timer;
    if (timer.getElapsedTimeF32() < 5.f)
    {
        return;
    }
    timer.reset();
    static std::string needle = []() {
        std::string n = getenv("LL_VK_AVLOG_NAME") ? getenv("LL_VK_AVLOG_NAME") : "";
        std::transform(n.begin(), n.end(), n.begin(), [](unsigned char c) { return (char)tolower(c); });
        return n;
    }();
    const LLVector3 cam = LLViewerCamera::getInstance()->getOrigin();
    S32 shown = 0;
    for (LLCharacter* c : LLCharacter::sInstances)
    {
        LLVOAvatar* av = dynamic_cast<LLVOAvatar*>(c);
        if (!av || av->isDead())
        {
            continue;
        }
        std::string name = av->getFullname();
        std::string lower = name;
        std::transform(lower.begin(), lower.end(), lower.begin(), [](unsigned char ch) { return (char)tolower(ch); });
        if (!needle.empty() && lower.find(needle) == std::string::npos)
        {
            continue;
        }
        if (needle.empty() && ++shown > 12)
        {
            break;
        }
        std::string text;
        S32 objects = 0;
        for (auto& kv : av->mAttachmentPoints)
        {
            LLViewerJointAttachment* att = kv.second;
            if (!att)
            {
                continue;
            }
            for (auto& obj_ptr : att->mAttachedObjects)
            {
                LLViewerObject* root = obj_ptr.get();
                if (!root)
                {
                    continue;
                }
                std::vector<LLViewerObject*> prims;
                prims.push_back(root);
                for (auto& child : root->getChildren())
                {
                    prims.push_back(child);
                }
                S32 faces = 0, rigged = 0, mesh = 0, fullbright = 0, glow = 0, blend = 0, shiny = 0, pbr = 0, animesh = 0;
                for (LLViewerObject* o : prims)
                {
                    LLVOVolume* vol = dynamic_cast<LLVOVolume*>(o);
                    if (vol)
                    {
                        mesh += vol->isMesh() ? 1 : 0;
                        rigged += vol->isRiggedMesh() ? 1 : 0;
                        animesh += vol->isAnimatedObject() ? 1 : 0;
                    }
                    for (U8 i = 0; i < o->getNumTEs(); ++i)
                    {
                        const LLTextureEntry* te = o->getTE(i);
                        if (!te)
                        {
                            continue;
                        }
                        ++faces;
                        fullbright += te->getFullbright() ? 1 : 0;
                        glow += te->getGlow() > 0.f ? 1 : 0;
                        blend += te->getColor().mV[3] < 0.999f ? 1 : 0;
                        shiny += te->getShiny() ? 1 : 0;
                        pbr += te->getGLTFRenderMaterial() ? 1 : 0;
                    }
                }
                char buf[300];
                snprintf(buf, sizeof(buf), " [%s: %s, %zu prims, %d faces, mesh %d, rigged %d, animesh %d, fullbright %d, glow %d, alpha<1 %d, shiny %d, pbr %d]", att->getName().c_str(), root->getID().asString().substr(0, 8).c_str(),
                         prims.size(), faces, mesh, rigged, animesh, fullbright, glow, blend, shiny, pbr);
                text += buf;
                ++objects;
            }
        }
        LL_INFOS("VkAvLog") << "avatar '" << name << "'" << (av->isSelf() ? " (self)" : "") << (av->isControlAvatar() ? " (animesh control avatar)" : "") << ", " << (av->isFullyLoaded() ? "loaded" : "not fully loaded")
                            << ", " << (av->isImpostor() ? "impostor" : "full") << ", " << (av->isSitting() ? "sitting" : "not sitting") << ", " << (av->getPositionAgent() - cam).length() << " m, " << objects
                            << " attached objects:" << text << LL_ENDL;
    }
}

// <FS> ---- the main view's cull on the pool (doc/vulkan/PLAN-statesort-offmain.md, stage 3a) ----
// Every partition has an octree of its own and the walk of one writes only what belongs to its groups (visibility stamps, distances, occlusion state, the group's alpha-dirty bit), to the lists of the
// cull result, and, through markNotCulled, to the rebuild queue (calcDistance) and the wake queue. The partitions are cut into runs of the list they come in (a run is a job); each job culls into a result
// of its own and records the queue writes in a ledger (sSortSink); the results are appended and the ledgers applied in list order, which is the order the serial loop made them in.
// LL_VK_CULL_SPLIT=<mode> (3 on the pool, default; 0 off; 4 check: the pool's lists are compared with the serial loop's, which makes the frame).
namespace
{
int cull_split_setting()
{
    static const int env_mode = getenv("LL_VK_CULL_SPLIT") ? atoi(getenv("LL_VK_CULL_SPLIT")) : 3;
    return env_mode;
}

// what a job does: the walk of a whole partition, or of one subtree of a partition that was split (mSplit)
struct CullItem
{
    LLSpatialPartition* mPart = nullptr;
    bool mTask = false;
    LLViewerOctreeCull::SplitTask mSplit = { nullptr, 0 };
    float mUs = 0.f;
    bool mReplay = false;       // C4.5 S1c: the retained set is replayed instead of the walk
    size_t mBegin = 0, mEnd = 0;        // (of the replay list)
};

// a unit of the result, in the order of the serial loop: a segment (what the top levels of a split partition did, on the calling thread, before the jobs) or a run of items (a job)
struct CullChunk
{
    size_t mBegin = 0, mEnd = 0;
    bool mSegment = false;
    std::vector<LLPipeline::SortDelta> mLedger;
    LLCullResult* mLocal = nullptr;
    double mUs = 0.0;
};

// <FS> view rework W3: the jobs of a stage work for a view. The scope installs it for the thread (the flags and the render type mask the job reads come from it, see LLPipeline::sJobView) and its camera id, and puts both back
// afterwards (the calling thread runs jobs too). The view must outlive the jobs.
struct ViewScope
{
    const LLPipeline::View* mPrev = LLPipeline::sJobView;
    LLViewerCamera::eCameraID mCameraID = LLViewerCamera::sCurCameraID;

    ViewScope(const LLPipeline::View& view)
    {
        LLPipeline::sJobView = &view;
        LLViewerCamera::sCurCameraID = (LLViewerCamera::eCameraID)view.mCameraID;
    }
    ~ViewScope()
    {
        LLPipeline::sJobView = mPrev;
        LLViewerCamera::sCurCameraID = mCameraID;
    }
};

// the thread-local state of a cull job, put back afterwards (the calling thread runs jobs too)
struct CullTaskScope
{
    LLCullResult* mCull = sCull;
    std::vector<LLPipeline::SortDelta>* mSink = LLPipeline::sSortSink;
    bool mParallel = LLPipeline::sParallelPrep;
    ViewScope mView;        // (the camera id the walks read and the flags: a pool thread's own camera id is CAMERA_WORLD whatever the view is)

    CullTaskScope(CullChunk& chunk, const LLPipeline::View& view) : mView(view)
    {
        LLPipeline::sParallelPrep = true;       // (no shared statistics: mNumVisibleNodes is added by the caller)
        sCull = chunk.mLocal;
        LLPipeline::sSortSink = &chunk.mLedger;
    }
    ~CullTaskScope()
    {
        sCull = mCull;
        LLPipeline::sSortSink = mSink;
        LLPipeline::sParallelPrep = mParallel;
    }
};

bool sVisSetReplay = false;       // C4.5 S1c: this frame the tracked partitions with a current retained set are replayed (set by updateCull around the pool cull)
std::vector<std::unique_ptr<LLCullResult>> sCullLocals;
std::unordered_map<LLSpatialPartition*, float> sCullCostUs;     // the last measured cost of a partition's walk (smoothed), the weight when the runs are cut
LLCullResult* sCullCheckResult = nullptr;
std::unordered_map<const void*, float> sCullNodeUs;       // the same for the subtrees that were jobs (smoothed): a node that cost more than the limit is walked on the calling thread, its children are the jobs

struct CullSplitStats
{
    U32 mCalls[2] = {};             // 0: the serial loop, 1: the pool path
    double mMs[2] = {};
    double mApplyMs = 0.0, mLongestUs = 0.0, mSumUs = 0.0, mTopUs = 0.0;
    U64 mChunks = 0, mInline = 0, mSegments = 0;
    U64 mCheckRuns = 0, mCheckBad = 0, mCkJobs = 0, mCkSegments = 0;
    double mCkTopUs = 0.0, mCkSumUs = 0.0, mCkLongestUs = 0.0;
    U32 mReport = 0;
};
CullSplitStats sCullSplitStats;
std::vector<LLSpatialPartition*> sCullParts;

void cull_split_report()
{
    CullSplitStats& s = sCullSplitStats;
    const double pool_n = std::max<U32>(s.mCalls[1], 1), ser_n = std::max<U32>(s.mCalls[0], 1);
    std::string list;
    {
        std::vector<std::pair<float, LLSpatialPartition*>> v;
        double total = 0.0;
        for (LLSpatialPartition* p : sCullParts)
        {
            auto it = sCullCostUs.find(p);
            if (it != sCullCostUs.end())
            {
                v.push_back({ it->second, p });
                total += it->second;
            }
        }
        std::sort(v.begin(), v.end(), [](const auto& a, const auto& b) { return a.first > b.first; });
        char b[96];
        snprintf(b, sizeof(b), "%zu partitions, the sum of their costs %.0f us; the largest: ", v.size(), total);
        list = b;
        for (size_t k = 0; k < v.size() && k < 8; ++k)
        {
            snprintf(b, sizeof(b), "[type %u %.0f us] ", v[k].second->mPartitionType, v[k].first);
            list += b;
        }
    }
    LL_INFOS("CullSplit") << "main cull, partition stage (ms per frame): serial loop " << s.mMs[0] / ser_n << " over " << s.mCalls[0] << " frames | pool " << s.mMs[1] / pool_n << " over " << s.mCalls[1]
        << " frames (of it the apply pass " << s.mApplyMs / pool_n << "; " << (double)s.mChunks / pool_n << " jobs a frame, sum of the jobs " << s.mSumUs / pool_n << " us, the longest " << s.mLongestUs / pool_n << " us, the top levels of the split partitions " << s.mTopUs / pool_n << " us in " << (double)s.mSegments / pool_n << " segments"
        << " us; " << s.mInline << " frames run inline) | check: " << s.mCheckRuns << " runs, " << s.mCheckBad << " differ (pool run: " << (double)s.mCkJobs / std::max<U64>(s.mCheckRuns, 1) << " jobs, sum " << s.mCkSumUs / std::max<U64>(s.mCheckRuns, 1) << " us, longest " << s.mCkLongestUs / std::max<U64>(s.mCheckRuns, 1) << " us, top levels " << s.mCkTopUs / std::max<U64>(s.mCheckRuns, 1) << " us in " << (double)s.mCkSegments / std::max<U64>(s.mCheckRuns, 1) << " segments) | " << list << LL_ENDL;
    LL_INFOS("CullSplit") << "fork-join pool: " << LLForkJoinPool::sNestedRuns.load() << " runs found the pool busy and ran inline (a run inside a run; 0 is the expectation); runs whose executed jobs were not the count "
        << LLForkJoinPool::sMismatchRuns.load() << ", given up on after a wait " << LLForkJoinPool::sRecoveredRuns.load() << ", decrements refused at zero " << LLForkJoinPool::sUnderflows.load() << " (all 0 is the expectation)" << LL_ENDL;
    s = CullSplitStats();
}

// the lists of two culls of the same camera must be the same, in the same order
bool cull_lists_equal(LLCullResult& a, LLCullResult& b)
{
    bool same = true;
    auto cmp = [&](const char* name, LLCullResult::sg_iterator ab, LLCullResult::sg_iterator ae, LLCullResult::sg_iterator bb, LLCullResult::sg_iterator be)
    {
        const size_t na = ae - ab, nb = be - bb;
        size_t first = ~(size_t)0;
        for (size_t k = 0; k < std::min(na, nb); ++k)
        {
            if (ab[k] != bb[k])
            {
                first = k;
                break;
            }
        }
        if (na != nb || first != ~(size_t)0)
        {
            same = false;
            static int logged = 0;
            if (++logged <= 8)
            {
                LL_WARNS("CullSplit") << "cull check: " << name << " differ: pool " << na << " entries, serial " << nb << ", first difference at " << (S64)first << LL_ENDL;
            }
        }
    };
    cmp("drawable groups", a.beginDrawableGroups(), a.endDrawableGroups(), b.beginDrawableGroups(), b.endDrawableGroups());
    cmp("visible groups", a.beginVisibleGroups(), a.endVisibleGroups(), b.beginVisibleGroups(), b.endVisibleGroups());
    // (markOccluder lists a group twice when it is the first of its parent's children to be listed, and a flag left on a parent by an earlier frame changes that: the first occurrences are compared)
    auto first_occurrences = [](LLCullResult& r)
    {
        std::vector<LLSpatialGroup*> v;
        std::unordered_set<LLSpatialGroup*> seen;
        for (LLCullResult::sg_iterator g = r.beginOcclusionGroups(); g != r.endOcclusionGroups(); ++g)
        {
            if (seen.insert(*g).second)
            {
                v.push_back(*g);
            }
        }
        return v;
    };
    std::vector<LLSpatialGroup*> occ_a = first_occurrences(a), occ_b = first_occurrences(b);
    cmp("occlusion groups", occ_a.data(), occ_a.data() + occ_a.size(), occ_b.data(), occ_b.data() + occ_b.size());
    {
        // (the groups only one side listed, with what decides the listing: the first few, to find the cause of a difference)
        static int shown = 0;
        std::unordered_set<LLSpatialGroup*> sa(occ_a.begin(), occ_a.end()), sb(occ_b.begin(), occ_b.end());
        auto show = [&](const char* side, const std::vector<LLSpatialGroup*>& v, const std::unordered_set<LLSpatialGroup*>& other)
        {
            for (LLSpatialGroup* g : v)
            {
                if (other.count(g) || shown >= 24)
                {
                    continue;
                }
                ++shown;
                LLSpatialGroup* par = g->getParent();
                LL_WARNS("CullSplit") << "cull check: only the " << side << " listed an occlusion group: partition type " << g->getSpatialPartition()->mPartitionType << ", stored stamp " << g->row().visible[LLViewerCamera::CAMERA_WORLD]
                    << ", slot " << g->row().retainedSlot << " (its frame " << g->retainedFrame(LLViewerCamera::CAMERA_WORLD) << "), frame " << LLViewerOctreeEntryData::getCurrentFrame() << ", needsUpdate " << g->needsUpdate() << ", occlusion state " << g->row().occlusion[LLViewerCamera::CAMERA_WORLD]
                    << ", parent " << (par ? (par->isOcclusionState(LLSpatialGroup::OCCLUDED) ? "occluded" : "not occluded") : "none") << ", empty " << g->isEmpty() << LL_ENDL;
            }
        };
        show("pool (replay)", occ_a, sb);
        show("serial walk", occ_b, sa);
    }
    if (a.getVisibleListSize() != b.getVisibleListSize() || a.getVisibleBridgeSize() != b.getVisibleBridgeSize())
    {
        same = false;
        LL_WARNS("CullSplit") << "cull check: the drawable or bridge lists differ in size" << LL_ENDL;
    }
    return same;
}

// the walks of the partitions of every region, as jobs. into == nullptr: the result is the real one (sCull) and the object cache is culled too, 1 is returned.
// into != nullptr (the check): the results go there, the queue writes are made, the occlusion flags the walks set are cleared again so that the serial loop that follows sees what the first run saw; 2 is returned.
int cull_partitions_parallel(const LLPipeline::View& view, LLCullResult* into)
{
    LLCamera& camera = *view.mCamera;
    LLForkJoinPool* pool = LLForkJoinPool::shared();
    if (!pool)
    {
        return 0;
    }
    std::vector<LLSpatialPartition*>& parts = sCullParts;
    parts.clear();
    for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin(); iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
    {
        for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
        {
            LLSpatialPartition* part = (*iter)->getSpatialPartition(i);
            if (part && (LLViewerRegion::PARTITION_BRIDGE == i || gPipeline.hasRenderType(part->mDrawableType)))
            {
                parts.push_back(part);
            }
        }
    }
    if (parts.empty())
    {
        return 0;
    }

    const auto t_start = std::chrono::steady_clock::now();
    const size_t workers = pool->workerCount();

    // the runs: contiguous stretches of the list of about the same cost (the cost of a partition is what its walk took the last time)
    std::vector<float> cost(parts.size(), 0.f);
    double known_sum = 0.0;
    size_t known = 0;
    for (size_t k = 0; k < parts.size(); ++k)
    {
        auto it = sCullCostUs.find(parts[k]);
        if (it != sCullCostUs.end())
        {
            cost[k] = it->second;
            known_sum += it->second;
            ++known;
        }
        else
        {
            cost[k] = -1.f;
        }
    }
    std::vector<char> replay(parts.size(), 0);
    for (size_t k = 0; k < parts.size(); ++k)
    {
        if (sVisSetReplay && LLVisSet::replayable(parts[k]))
        {
            replay[k] = 1;
            cost[k] = 0.2f * (float)LLVisSet::replayCount(parts[k]) + 1.f;        // (about 0.2 us a group)
        }
    }
    const float unknown_cost = known ? (float)(known_sum / known) : 6.f;
    double total = 0.0;
    for (float& c : cost)
    {
        if (c < 0.f)
        {
            c = unknown_cost;
        }
        total += c;
    }
    const double target = std::max(total / (double)((workers + 1) * 2), 12.0);

    // the units, in the order of the serial loop. A partition that cost more than split_cost the last time is walked in pieces: its top levels here (a segment of the result), the subtrees below them as
    // jobs of their own (each between two segments); the other partitions go into runs of about the same cost, one job a run.
    static const double split_cost = getenv("LL_VK_CULL_SPLIT_US") ? atof(getenv("LL_VK_CULL_SPLIT_US")) : 80.0;
    std::deque<CullChunk> chunks;
    std::vector<CullItem> items;
    items.reserve(parts.size() + 64);
    auto new_chunk = [&](bool segment) -> CullChunk&
    {
        chunks.emplace_back();
        CullChunk& c = chunks.back();
        const size_t idx = chunks.size() - 1;
        if (sCullLocals.size() <= idx)
        {
            sCullLocals.push_back(std::make_unique<LLCullResult>());
        }
        sCullLocals[idx]->clear();
        c.mLocal = sCullLocals[idx].get();
        c.mSegment = segment;
        c.mBegin = c.mEnd = items.size();
        return c;
    };
    std::unordered_map<LLSpatialPartition*, float> part_us;     // what each partition cost this time (its top levels and every job together)
    double top_us = 0.0;
    size_t segments = 0;
    {
        CullChunk* run = nullptr;
        double run_cost = 0.0;
        for (size_t k = 0; k < parts.size(); ++k)
        {
            LLSpatialPartition* part = parts[k];
            if (cost[k] > split_cost && !replay[k])
            {
                run = nullptr;
                static const double node_split = getenv("LL_VK_CULL_NODE_US") ? atof(getenv("LL_VK_CULL_NODE_US")) : 100.0;
                const auto w0 = std::chrono::steady_clock::now();
                CullChunk& first_segment = new_chunk(true);
                ++segments;
                CullTaskScope scope(first_segment, view);
                const OctreeNode* root = part->mOctree;
                part->cullSplit(camera, 8, [&](const OctreeNode* n)
                {
                    if (n == root)
                    {
                        return true;
                    }
                    auto it = sCullNodeUs.find(n);
                    return it != sCullNodeUs.end() && it->second > node_split;
                }, [&](const LLViewerOctreeCull::SplitTask& task)
                {
                    CullChunk& w = new_chunk(false);
                    items.push_back({ part, true, task, 0.f });
                    w.mEnd = items.size();
                    CullChunk& next_segment = new_chunk(true);
                    ++segments;
                    sCull = next_segment.mLocal;                    // (the scope puts the thread's own back at the end)
                    LLPipeline::sSortSink = &next_segment.mLedger;
                });
                const double us = std::chrono::duration<double, std::micro>(std::chrono::steady_clock::now() - w0).count();
                top_us += us;
                part_us[part] += (float)us;
            }
            else
            {
                if (!run)
                {
                    run = &new_chunk(false);
                    run_cost = 0.0;
                }
                if (replay[k])
                {
                    // a replayed partition in pieces of the same size as a walk job's share: the pieces are consecutive in the result, as the walk's would be
                    const size_t n = LLVisSet::replayCount(part);
                    const size_t piece = std::max<size_t>(64, (size_t)(target / 0.2));
                    for (size_t b = 0; b < std::max<size_t>(n, 1); b += piece)
                    {
                        if (!run)
                        {
                            run = &new_chunk(false);
                            run_cost = 0.0;
                        }
                        items.push_back({ part, false, { nullptr, 0 }, 0.f });
                        items.back().mReplay = true;
                        items.back().mBegin = b;
                        items.back().mEnd = std::min(n, b + piece);
                        run->mEnd = items.size();
                        run_cost += 0.2 * (double)(items.back().mEnd - b) + 0.5;
                        if (run_cost >= target)
                        {
                            run = nullptr;
                        }
                    }
                    continue;
                }
                items.push_back({ part, false, { nullptr, 0 }, 0.f });
                run->mEnd = items.size();
                run_cost += cost[k];
                if (run_cost >= target)
                {
                    run = nullptr;
                }
            }
        }
    }
    std::vector<size_t> work;
    for (size_t c = 0; c < chunks.size(); ++c)
    {
        if (!chunks[c].mSegment)
        {
            work.push_back(c);
        }
    }

    const std::function<void(size_t)> job = [&](size_t w)
    {
        CullChunk& chunk = chunks[work[w]];
        CullTaskScope scope(chunk, view);
        const auto t0 = std::chrono::steady_clock::now();
        for (size_t k = chunk.mBegin; k < chunk.mEnd; ++k)
        {
            CullItem& item = items[k];
            const auto p0 = std::chrono::steady_clock::now();
            {
                LL_CPU_ZONE("updateCull: partition cull");
                if (item.mReplay)
                {
                    LLVisSet::replay(item.mPart, camera, item.mBegin, item.mEnd);
                }
                else if (item.mTask)
                {
                    item.mPart->cullTask(camera, item.mSplit);
                }
                else
                {
                    item.mPart->cull(camera);
                }
            }
            item.mUs = (float)std::chrono::duration<double, std::micro>(std::chrono::steady_clock::now() - p0).count();
        }
        chunk.mUs = std::chrono::duration<double, std::micro>(std::chrono::steady_clock::now() - t0).count();
    };
    // (a frame whose walks cost less than a wake-up is run here, in the same units: the costs go on being measured)
    const bool inline_run = total < 100.0;
    if (inline_run)
    {
        for (size_t w = 0; w < work.size(); ++w)
        {
            job(w);
        }
    }
    else
    {
        LL_CPU_ZONE("updateCull: partition cull jobs (wait for the pool)");
        pool->runLabeled("updateCull: partition cull", work.size(), job);
    }

    // the results in the order of the units, the ledgers applied in the same order
    LLCullResult& target_result = into ? *into : *sCull;
    if (into)
    {
        into->clear();
    }
    const auto t_apply = std::chrono::steady_clock::now();
    std::vector<LLPipeline::SortDelta> ledger;
    size_t pushed = 0;
    double longest = 0.0, sum = 0.0;
    for (CullChunk& chunk : chunks)
    {
        LLCullResult& l = *chunk.mLocal;
        for (LLCullResult::drawable_iterator d = l.beginVisibleList(); d != l.endVisibleList(); ++d) target_result.pushDrawable(*d);
        for (LLCullResult::bridge_iterator b = l.beginVisibleBridge(); b != l.endVisibleBridge(); ++b) target_result.pushBridge(*b);
        for (LLCullResult::sg_iterator g = l.beginDrawableGroups(); g != l.endDrawableGroups(); ++g) { target_result.pushDrawableGroup(*g); ++pushed; }
        for (LLCullResult::sg_iterator g = l.beginVisibleGroups(); g != l.endVisibleGroups(); ++g) { target_result.pushVisibleGroup(*g); ++pushed; }
        for (LLCullResult::sg_iterator g = l.beginOcclusionGroups(); g != l.endOcclusionGroups(); ++g) target_result.pushOcclusionGroup(*g);
        ledger.insert(ledger.end(), chunk.mLedger.begin(), chunk.mLedger.end());
        if (!chunk.mSegment)
        {
            longest = std::max(longest, chunk.mUs);
            sum += chunk.mUs;
        }
    }
    gPipeline.applySortDeltas(ledger);
    for (const CullItem& item : items)
    {
        part_us[item.mPart] += item.mUs;
        if (item.mTask)
        {
            float& c = sCullNodeUs[item.mSplit.mNode];
            c = c > 0.f ? c * 0.7f + item.mUs * 0.3f : item.mUs;
        }
    }
    if (sCullNodeUs.size() > 8192)
    {
        sCullNodeUs.clear();
    }
    for (size_t k = 0; k < parts.size(); ++k)
    {
        if (replay[k])
        {
            continue;       // (the cost of the walk of a replayed partition stays what it was: the weights are for the walk)
        }
        LLSpatialPartition* part = parts[k];
        float& c = sCullCostUs[part];
        const float now_us = part_us[part];
        c = c > 0.f ? c * 0.8f + now_us * 0.2f : now_us;
    }
    if (sCullCostUs.size() > 4096)
    {
        sCullCostUs.clear();        // (partitions of regions that are gone: the weights come back within a frame)
    }

    int result = 1;
    if (into)
    {
        for (LLCullResult::sg_iterator g = into->beginOcclusionGroups(); g != into->endOcclusionGroups(); ++g)
        {
            (*g)->clearOcclusionState(LLSpatialGroup::ACTIVE_OCCLUSION);        // (the parents markOccluder flagged stay flagged: that only changes which entries are listed twice)
        }
        result = 2;
    }
    else
    {
        gPipeline.mNumVisibleNodes += (S32)pushed;
        for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin(); iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
        {
            LLVOCachePartition* vo_part = (*iter)->getVOCachePartition();
            if (vo_part)
            {
                LL_CPU_ZONE("updateCull: VO cache cull");
                vo_part->cull(camera, LLPipeline::useOcclusion() > 0 && !gAgent.getFSAreaSearchActive());
            }
        }
    }

    CullSplitStats& s = sCullSplitStats;
    if (into)
    {
        s.mCkJobs += work.size();
        s.mCkSegments += segments;
        s.mCkTopUs += top_us;
        s.mCkSumUs += sum;
        s.mCkLongestUs += longest;
    }
    if (!into)
    {
        ++s.mCalls[1];
        s.mMs[1] += std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t_start).count();
        s.mApplyMs += std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t_apply).count();
        s.mChunks += work.size();
        s.mSegments += segments;
        s.mTopUs += top_us;
        s.mSumUs += sum;
        s.mLongestUs += longest;
        s.mInline += inline_run;
    }
    return result;
}
}

// <FS> view rework W1: the state a stage reads, taken once (see LLPipeline::View)
LLPipeline::View LLPipeline::currentView(LLCamera& camera, bool hud)
{
    View view;
    view.mCamera = &camera;
    view.mCameraID = (S32)LLViewerCamera::sCurCameraID;
    view.mUseOcclusion = useOcclusion();
    view.mWorldCameraID = LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD;
    view.mHud = hud;
    view.mShadowRender = shadowRender();
    view.mReflectionRender = reflectionRender();
    view.mCubeSnapshot = gCubeSnapshot;
    view.mViewerCamera = &camera == LLViewerCamera::getInstance();
    view.mRenderingHUDs = sRenderingHUDs;
    memcpy(view.mRenderTypes, gPipeline.mRenderTypeEnabled, sizeof(view.mRenderTypes));
    return view;
}

// <FS> C4.5 census (LL_VK_MAINCENSUS=1, off by default; the main view's partition cull, in the production path): the walk's counts (LLCullCensus, written by the walks and markNotCulled on every thread), and
// per frame a comparison of the groups the cull listed with the last frame's, by the type of the group's partition. A group list a retained cull would replay is exact when the camera is the same, the partition's
// change epoch is the same and no group of it changed its occlusion state: for each type the frames where that key holds ("hit") and how many groups differed from the last frame on them (it must be 0), the groups that
// differed on the other frames and which of the three changed. The report is a line every 600 frames (tag MainCull).
void LLCullCensus::noteOcc(LLOcclusionCullingGroup* g, bool now_occluded, int source)
{
    if (!sOn)
    {
        return;
    }
    sOccSrc[source & 3].fetch_add(1, std::memory_order_relaxed);
    (now_occluded ? sOccSet : sOccClear).fetch_add(1, std::memory_order_relaxed);
    static std::mutex mtx;
    static std::unordered_map<const void*, std::pair<S32, S32>> last;       // group -> (frame of its last change, state after it)
    const S32 frame = (S32)LLFrameTimer::getFrameCount();
    {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = last.find(g);
        if (it == last.end())
        {
            sOccFirst.fetch_add(1, std::memory_order_relaxed);
            last.emplace(g, std::make_pair(frame, now_occluded ? 1 : 0));
        }
        else
        {
            const S32 gap = frame - it->second.first;
            sOccDwell[now_occluded ? 0 : 1][gap <= 2 ? 0 : gap <= 8 ? 1 : gap <= 60 ? 2 : 3].fetch_add(1, std::memory_order_relaxed);      // [the state it left: 0 visible, 1 occluded][how long]
            it->second = { frame, now_occluded ? 1 : 0 };
        }
    }
    if (LLSpatialGroup* sg = dynamic_cast<LLSpatialGroup*>(g))
    {
        if (const OctreeNode* node = sg->getOctreeNode())
        {
            if (node->getChildCount() == 0)
            {
                sOccLeaf.fetch_add(1, std::memory_order_relaxed);
            }
            U64 nodes = 0;
            std::function<void(const OctreeNode*)> count = [&](const OctreeNode* n)
            {
                ++nodes;
                for (U32 i = 0; i < n->getChildCount(); ++i)
                {
                    count(n->getChild(i));
                }
            };
            count(node);
            sOccSubtree.fetch_add(nodes, std::memory_order_relaxed);
        }
        bool avatar = false, active = false;
        for (LLSpatialGroup::element_iter i = sg->getDataBegin(); i != sg->getDataEnd(); ++i)
        {
            LLDrawable* d = (LLDrawable*)(*i)->getDrawable();
            if (!d)
            {
                continue;
            }
            if (d->isAvatar() || d->isSpatialBridge())
            {
                avatar = true;
            }
            else if (d->isActive())
            {
                active = true;
            }
        }
        sOccAvatar.fetch_add(avatar ? 1 : 0, std::memory_order_relaxed);
        sOccActive.fetch_add(active ? 1 : 0, std::memory_order_relaxed);
    }
}

static void main_cull_census(LLCamera& camera)
{
    using C = LLCullCensus;
    static const char* const names[16] = { "hud", "terrain", "voidwater", "water", "tree", "particle", "grass", "volume", "bridge", "avatar", "control_av", "hud_particle", "t12", "t13", "t14", "t15" };
    static LLVector3 prev_origin, prev_at;
    static bool have_prev = false;
    static std::unordered_map<const void*, U8> prev_groups;
    static U64 frames = 0, cam_still_frames = 0, all_hit_frames = 0;
    static U64 w_nodes = 0, w_early = 0, w_occdrop = 0, w_inside = 0, w_frustum = 0, w_out = 0, w_marks = 0, w_empty = 0, w_pd = 0, w_pv = 0, w_ticks = 0;
    struct Per { U64 mGroupsB = 0, mHitChangedB = 0, mMissChangedB = 0, mGroups = 0, mHit = 0, mHitChanged = 0, mMiss = 0, mMissChanged = 0, mMissCam = 0, mMissEpoch = 0, mMissOcc = 0, mOccChanges = 0, mPresent = 0; };
    static Per per[16];
    static std::chrono::steady_clock::time_point t0 = std::chrono::steady_clock::now();
    static U64 tsc0 = LLVisCensus::now();

    const LLVector3 origin = camera.getOrigin(), at = camera.getAtAxis();
    const bool cam_same = have_prev && origin == prev_origin && at == prev_at;
    prev_origin = origin;
    prev_at = at;
    have_prev = true;
    ++frames;
    cam_still_frames += cam_same ? 1 : 0;

    w_nodes += C::sNodes.exchange(0); w_early += C::sEarlyFail.exchange(0); w_occdrop += C::sOccDropped.exchange(0); w_inside += C::sAllInside.exchange(0);
    w_frustum += C::sFrustumTests.exchange(0); w_out += C::sFrustumOut.exchange(0); w_marks += C::sMarkCalls.exchange(0); w_empty += C::sMarkEmpty.exchange(0);
    w_pd += C::sMarkDrawable.exchange(0); w_pv += C::sMarkVisible.exchange(0); w_ticks += C::sMarkTicks.exchange(0);

    // the partitions' change epochs: the partitions of the regions, and the own partition of every listed group (the bridges' partitions hold the attachments' groups, typed like the region's: they are not in the region's list)
    static std::unordered_map<const void*, std::pair<U8, U64>> prev_parts;      // partition -> (type, epoch) as last seen
    std::unordered_map<const void*, std::pair<U8, U64>> cur_parts;
    auto note_part = [&](LLSpatialPartition* part)
    {
        if (part)
        {
            cur_parts.emplace((const void*)part, std::make_pair((U8)std::min<U32>(part->mPartitionType, 15), (U64)part->mEpoch.load(std::memory_order_relaxed)));
        }
    };
    for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin(); iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
    {
        for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
        {
            note_part((*iter)->getSpatialPartition(i));
        }
    }
    U32 occ[16];
    for (int t = 0; t < 16; ++t)
    {
        occ[t] = C::sOccChanges[t].exchange(0);
        per[t].mOccChanges += occ[t];
    }

    std::unordered_map<const void*, U8> cur;
    cur.reserve(sCull->getDrawableGroupsSize() + sCull->getVisibleGroupsSize());
    auto take = [&](LLCullResult::sg_iterator b, LLCullResult::sg_iterator e)
    {
        for (LLCullResult::sg_iterator g = b; g != e; ++g)
        {
            cur.emplace((const void*)*g, (U8)(std::min<U32>((*g)->getSpatialPartition()->mPartitionType, 15) | ((*g)->getSpatialPartition()->isBridge() ? 0x80u : 0u)));      // (bit 7: the group is in a bridge's own partition: the attachments of an avatar)
            note_part((*g)->getSpatialPartition());
        }
    };
    take(sCull->beginDrawableGroups(), sCull->endDrawableGroups());
    take(sCull->beginVisibleGroups(), sCull->endVisibleGroups());
    bool epoch_changed[16] = {};
    for (const auto& kv : cur_parts)
    {
        auto it = prev_parts.find(kv.first);
        if (it == prev_parts.end() || it->second.second != kv.second.second)
        {
            epoch_changed[kv.second.first] = true;
        }
        prev_parts[kv.first] = kv.second;
    }
    U64 changed[16] = {}, count[16] = {}, changed_b[16] = {}, count_b[16] = {};
    for (const auto& kv : cur)
    {
        ++count[kv.second & 15];
        count_b[kv.second & 15] += (kv.second & 0x80) ? 1 : 0;
        if (!prev_groups.count(kv.first))
        {
            ++changed[kv.second & 15];
            changed_b[kv.second & 15] += (kv.second & 0x80) ? 1 : 0;
        }
    }
    for (const auto& kv : prev_groups)
    {
        if (!cur.count(kv.first))
        {
            ++changed[kv.second & 15];
            changed_b[kv.second & 15] += (kv.second & 0x80) ? 1 : 0;
        }
    }
    bool all_hit = true;
    for (int t = 0; t < 16; ++t)
    {
        const bool epoch_same = !epoch_changed[t];
        const bool hit = cam_same && epoch_same && occ[t] == 0;
        per[t].mGroups += count[t];
        per[t].mGroupsB += count_b[t];
        if (count[t] || changed[t])
        {
            ++per[t].mPresent;
            if (hit)
            {
                ++per[t].mHit;
                per[t].mHitChanged += changed[t];
                per[t].mHitChangedB += changed_b[t];
            }
            else
            {
                all_hit = false;
                ++per[t].mMiss;
                per[t].mMissChanged += changed[t];
                per[t].mMissChangedB += changed_b[t];
                per[t].mMissCam += cam_same ? 0 : 1;
                per[t].mMissEpoch += epoch_same ? 0 : 1;
                per[t].mMissOcc += occ[t] ? 1 : 0;
            }
        }
    }
    all_hit_frames += (all_hit && cam_same) ? 1 : 0;
    prev_groups.swap(cur);

    if (frames % 600 == 0)
    {
        const double wall_ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
        const double ms_per_tick = wall_ms / (double)std::max<U64>(1, LLVisCensus::now() - tsc0);
        const double n = 600.0;
        LL_INFOS("MainCull") << "main cull census over 600 frames, per frame: camera unchanged on " << cam_still_frames << " frames, every partition's key held on " << all_hit_frames
            << " | walk: nodes " << w_nodes / n << " (early fail " << w_early / n << " of them " << w_occdrop / n << " dropped as occluded, fully inside " << w_inside / n << ", frustum tests " << w_frustum / n << " of them out " << w_out / n
            << ") | markNotCulled: calls " << w_marks / n << " (empty " << w_empty / n << "), drawable groups " << w_pd / n << ", visible groups " << w_pv / n << ", time inside it on all threads " << (double)w_ticks * ms_per_tick / n << " ms" << LL_ENDL;
        for (int t = 0; t < 16; ++t)
        {
            const Per& p = per[t];
            if (!p.mPresent)
            {
                continue;
            }
            LL_INFOS("MainCull") << "main cull census, partition " << names[t] << ": groups listed " << p.mGroups / n << " a frame, present on " << p.mPresent << " frames: key held on " << p.mHit << " ("
                << (p.mHit ? (double)p.mHitChanged / p.mHit : 0.0) << " groups differed from the frame before on those, 0 expected; " << (p.mHit ? (double)p.mHitChangedB / p.mHit : 0.0) << " of them in bridge partitions; " << p.mGroupsB / n << " of the listed groups are in bridge partitions), not held on " << p.mMiss << " (" << (p.mMiss ? (double)p.mMissChanged / p.mMiss : 0.0)
                << " groups differed a frame; camera changed on " << p.mMissCam << ", epoch on " << p.mMissEpoch << ", occlusion state on " << p.mMissOcc << "), occlusion state changes " << p.mOccChanges << LL_ENDL;
        }
        {
            const U64 set = C::sOccSet.exchange(0), clr = C::sOccClear.exchange(0), leaf = C::sOccLeaf.exchange(0), sub = C::sOccSubtree.exchange(0), av = C::sOccAvatar.exchange(0), act = C::sOccActive.exchange(0), first = C::sOccFirst.exchange(0);
            const U64 all = std::max<U64>(1, set + clr);
            U64 dw[2][4];
            for (int a = 0; a < 2; ++a) { for (int b = 0; b < 4; ++b) { dw[a][b] = C::sOccDwell[a][b].exchange(0); } }
            LL_INFOS("MainCull") << "main cull census, occlusion state changes over 600 frames: " << set << " set, " << clr << " cleared (by a verdict " << C::sOccSrc[0].exchange(0) << ", a discard in checkOcclusion " << C::sOccSrc[1].exchange(0)
                << ", the eye inside the box " << C::sOccSrc[2].exchange(0) << ", hizEntryMoved " << C::sOccSrc[3].exchange(0) << "); leaf groups " << leaf << ", nodes below the group on average " << (double)sub / all
                << "; the group holds an avatar or bridge " << av << ", another moving drawable " << act << "; first change seen of the group " << first
                << "; how long the group had been in the state it left (frames <= 2 / <= 8 / <= 60 / longer): visible " << dw[0][0] << " / " << dw[0][1] << " / " << dw[0][2] << " / " << dw[0][3]
                << ", occluded " << dw[1][0] << " / " << dw[1][1] << " / " << dw[1][2] << " / " << dw[1][3] << LL_ENDL;
        }
        for (Per& p : per) { p = Per(); }
        prev_parts.clear();
        frames = cam_still_frames = all_hit_frames = 0;
        w_nodes = w_early = w_occdrop = w_inside = w_frustum = w_out = w_marks = w_empty = w_pd = w_pv = w_ticks = 0;
        t0 = std::chrono::steady_clock::now();
        tsc0 = LLVisCensus::now();
    }
}

// <FS> C4.5 S1a (LL_VK_VISSET=2): after the main view's cull, every partition's membership is worked out again by the collecting walk (LLSpatialPartition::collectCull: the same frustum and occlusion verdicts,
// nothing written) and compared with the groups the real cull listed for that partition. The collector is what the retained set will be built from: this proves it gives what the walk gives.
static void main_vis_verify(LLCamera& camera)
{
    static U64 frames = 0, parts_checked = 0, groups_checked = 0, extra = 0, missing = 0, bad_frames = 0;
    std::unordered_set<const LLSpatialGroup*> real_d, real_v;
    std::unordered_map<const void*, std::pair<U32, U32>> real_count;
    for (LLCullResult::sg_iterator g = sCull->beginDrawableGroups(); g != sCull->endDrawableGroups(); ++g)
    {
        real_d.insert(*g);
        ++real_count[(*g)->getSpatialPartition()].first;
    }
    for (LLCullResult::sg_iterator g = sCull->beginVisibleGroups(); g != sCull->endVisibleGroups(); ++g)
    {
        real_v.insert(*g);
        ++real_count[(*g)->getSpatialPartition()].second;
    }
    static LLSpatialPartition::CullCollect collect;
    bool bad = false;
    for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin(); iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
    {
        for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
        {
            LLSpatialPartition* part = (*iter)->getSpatialPartition(i);
            if (!part || !(LLViewerRegion::PARTITION_BRIDGE == i || gPipeline.hasRenderType(part->mDrawableType)))
            {
                continue;
            }
            part->collectCull(camera, collect);
            ++parts_checked;
            U32 ex = 0;
            for (LLSpatialGroup* g : collect.mDrawable) { if (!real_d.count(g)) { ++ex; } }
            for (LLSpatialGroup* g : collect.mVisible) { if (!real_v.count(g)) { ++ex; } }
            const auto rc = real_count.count(part) ? real_count[part] : std::make_pair(0u, 0u);
            const S64 miss = ((S64)rc.first - (S64)collect.mDrawable.size()) + ((S64)rc.second - (S64)collect.mVisible.size()) + ex;      // (what the real cull listed and the collector did not)
            groups_checked += rc.first + rc.second;
            extra += ex;
            missing += miss > 0 ? miss : 0;
            if (ex || miss)
            {
                bad = true;
                static int logged = 0;
                if (++logged <= 8)
                {
                    LL_WARNS("VisSet") << "collector differs from the cull: partition type " << part->mPartitionType << " region partition " << i << ": real " << rc.first << " drawable + " << rc.second << " visible groups, collector "
                        << collect.mDrawable.size() << " + " << collect.mVisible.size() << ", collector groups the cull did not list " << ex << LL_ENDL;
                }
            }
        }
    }
    bad_frames += bad ? 1 : 0;
    if (++frames % 600 == 0)
    {
        LL_INFOS("VisSet") << "collector check: " << frames << " frames, " << parts_checked << " partition walks, " << groups_checked << " groups listed by the cull, " << extra << " the collector listed and the cull did not, " << missing
            << " the cull listed and the collector did not, " << bad_frames << " frames with a difference" << LL_ENDL;
    }
}

void LLPipeline::updateCull(LLCamera& camera, LLCullResult& result, bool hud_attachments)
{
    vk_avatar_log();
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE; //LL_RECORD_BLOCK_TIME(FTM_CULL);
    LL_PROFILE_GPU_ZONE("updateCull"); // should always be zero GPU time, but drop a timer to flush stuff out

    const View view = currentView(camera, hud_attachments);

    bool water_clip = isWaterClip();

    if (water_clip)
    {

        LLVector3 pnorm;

        F32 water_height = LLEnvironment::instance().getWaterHeight();

        if (sUnderWaterRender)
        {
            //camera is below water, cull above water
            pnorm.setVec(0, 0, 1);
        }
        else
        {
            //camera is above water, cull below water
            pnorm = LLVector3(0, 0, -1);
        }

        LLPlane plane;
        plane.setVec(LLVector3(0, 0, water_height), pnorm);

        camera.setUserClipPlane(plane);
    }
    else
    {
        camera.disableUserClipPlane();
    }

    { LL_CPU_ZONE("grabReferences"); grabReferences(result); }

    // <FS> S7 C0 (LL_VK_VISCENSUS=1): the main view's cull
    const bool vis_cull = LLVisCensus::sOn && view.isWorld();
    struct VisCullEnd
    {
        bool mOn; U64 mT0;
        ~VisCullEnd() { if (mOn) { LLVisCensus::sCullTicks += LLVisCensus::now() - mT0; ++LLVisCensus::sCullFrames; } }
    } vis_cull_end = { vis_cull, vis_cull ? LLVisCensus::now() : 0 };
    // <FS> S7 C2 (LL_VK_CULL_USE=2): the covered partitions are not walked, useVerdict makes their lists. rt-debug.txt culluse=N changes it live while the table runs (a same-lap A/B)
    if (LLCullShadow::sOn && view.mWorldCameraID && !view.mShadowRender && !view.mHud)
    {
        const S32 live_use = LLVkBridge::rtCullUse();
        const unsigned want_use = live_use >= 0 ? (unsigned)live_use : LLCullShadow::sUseEnv;       // (the key taken out of the file: back to what the environment says)
        if (want_use != LLCullShadow::sUse.load())
        {
            LLCullShadow::sUse = want_use;
        }
    }
    const bool cull_use = LLCullShadow::sUse == 2 && view.isWorld()
        && LLCullShadow::useMatches(camera);        // (a frame whose frustum has another shape than the verdict's is walked: the exit snapshot has no UI, so another aspect)
    struct CullShadowEnd
    {
        bool mOn; LLCamera* mCamera;
        ~CullShadowEnd() { if (mOn) { if (LLCullShadow::sOn) { LLCullShadow::build(*mCamera); } else { LLCullShadow::poseLog(*mCamera); } } }       // <FS> S7 C1: after everything the cull did
    } cull_shadow_end = { (LLCullShadow::sOn || LLCullShadow::sPoseLog) && view.isWorld(), &camera };

    if (view.mWorldCameraID && !view.mHud && !view.mCubeSnapshot)
    {
        LL_CPU_ZONE("occlusion: Hi-Z results");
        LLHiz::apply();        // <FS> S7 H3: the verdicts of the boxes sent a few frames ago
    }

    sCull->clear();

    static const bool main_census_env = (LLCullCensus::sOn = getenv("LL_VK_MAINCENSUS") != nullptr);
    const bool main_census = main_census_env && view.isMainWorld() && !gCubeSnapshot;
    if (main_census)
    {
        LLCullCensus::sActive.store(true);
    }

    // <FS> stage 3a: the main view's partition walks on the pool (see cull_partitions_parallel)
    const bool main_cull = view.isMainWorld()
        && !cull_use && !vis_cull && !LLOccCensus::sOn && !LLCullShadow::sOn && !LLGpuZoneTimer::isActive();     // (the pose log only reads the camera after the cull: it does not need the serial path)
    // <FS> C4.5 S1b/S1c (LL_VK_VISSET: 2 the collecting walk is compared with the cull, 3 the retained set kept by events is compared with it, 4 the pool cull replays the retained set of the tracked partitions on frames the camera did not change;
    // every 60th frame of 4 the replay and the real walk both run and their lists are compared, the way LL_VK_CULL_SPLIT=4 compares the pool walk with the serial one)
    static const int visset_mode = [] { const int m = getenv("LL_VK_VISSET") ? atoi(getenv("LL_VK_VISSET")) : 6; LLVisSetHooks::sOn = m >= 3; return m; }();      // default 6: replay, and every 300th frame the real walk too, compared (0 = the old path only)
    static std::vector<LLSpatialPartition*> vs_parts;
    bool vs_replay = false, vs_check = false;
    if (visset_mode >= 3 && view.isMainWorld() && !gCubeSnapshot && main_cull)
    {
        vs_parts.clear();
        for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin(); iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
        {
            for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
            {
                LLSpatialPartition* part = (*iter)->getSpatialPartition(i);
                // (the partitions whose groups keep their place: the moving ones, avatars, bridges, particles and control avatars, are walked every frame and not part of the retained set)
                if (part && gPipeline.hasRenderType(part->mDrawableType)
                    && (i == LLViewerRegion::PARTITION_TERRAIN || i == LLViewerRegion::PARTITION_VOIDWATER || i == LLViewerRegion::PARTITION_WATER || i == LLViewerRegion::PARTITION_TREE || i == LLViewerRegion::PARTITION_GRASS || i == LLViewerRegion::PARTITION_VOLUME))
                {
                    vs_parts.push_back(part);
                }
            }
        }
        // the camera signature the verdicts were made for: the planes, the corner distance, the origin, and the settings the culler reads
        static F32 sig[40] = {};
        F32 now[40] = {};
        int k = 0;
        for (U32 i = 0; i < 7; ++i)
        {
            const LLPlane& pl = camera.getAgentPlane(i);
            now[k++] = pl[0]; now[k++] = pl[1]; now[k++] = pl[2]; now[k++] = pl[3];
        }
        now[k++] = (F32)camera.getPlaneCount();
        now[k++] = camera.mFrustumCornerDist;
        const LLVector3& o = camera.getOrigin();
        now[k++] = o.mV[0]; now[k++] = o.mV[1]; now[k++] = o.mV[2];
        now[k++] = (F32)LLPipeline::useOcclusion();
        now[k++] = LLPipeline::sUseFarClip ? 1.f : 0.f;
        const bool camera_changed = memcmp(sig, now, sizeof(sig)) != 0;
        memcpy(sig, now, sizeof(sig));
        vs_replay = visset_mode >= 4 && cull_split_setting() >= 3;
        vs_check = vs_replay && ((visset_mode == 4 && (LLFrameTimer::getFrameCount() % 60) == 0) || (visset_mode == 6 && (LLFrameTimer::getFrameCount() % 300) == 0));       // (5: the replay alone, nothing is compared: for the cost)
        // (a check frame runs the real walk, which stamps the groups itself and must see the stamps of the frame before: the sets claim the frame only when the replay is the only thing that runs)
        LLVisSet::update(camera, vs_parts, camera_changed, vs_replay && !vs_check);
    }
    sVisSetReplay = vs_replay;
    const int cull_mode = main_cull ? (vs_check ? 4 : cull_split_setting()) : 0;
    int cull_done = 0;
    if (cull_mode >= 3)
    {
        if (cull_mode == 4 && !sCullCheckResult)
        {
            sCullCheckResult = new LLCullResult();
        }
        cull_done = cull_partitions_parallel(view, cull_mode == 4 ? sCullCheckResult : nullptr);
    }
    const auto serial_t0 = main_cull && cull_done != 1 ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point();

    for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin();
            cull_done != 1 && iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
    {
        LLViewerRegion* region = *iter;

        for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
        {
            LLSpatialPartition* part = region->getSpatialPartition(i);
            if (part)
            {
                if (!hud_attachments ? LLViewerRegion::PARTITION_BRIDGE == i || hasRenderType(part->mDrawableType) : hasRenderType(part->mDrawableType))
                {
                    // (one zone a partition: a few calls a frame each, so the zone cost stays small)
                    static const char* const part_zones[] = { "updateCull: cull HUD", "updateCull: cull TERRAIN", "updateCull: cull VOIDWATER", "updateCull: cull WATER", "updateCull: cull TREE", "updateCull: cull PARTICLE",
                        "updateCull: cull GRASS", "updateCull: cull VOLUME", "updateCull: cull BRIDGE", "updateCull: cull AVATAR", "updateCull: cull CONTROL_AV", "updateCull: cull HUD_PARTICLE", "updateCull: cull (other)" };
                    LL_CPU_ZONE(part_zones[i < 12 ? i : 12]);
                    if (cull_use && LLCullShadow::useSkip(part))
                    {
                        continue;
                    }
                    { LL_CPU_ZONE("updateCull: partition cull"); part->cull(camera); }
                }
            }
        }

        //scan the VO Cache tree
        LLVOCachePartition* vo_part = region->getVOCachePartition();
        if(vo_part)
        {
            // <FS:Beq> Fix area search again
            //vo_part->cull(camera, sUseOcclusion > 0);
            { LL_CPU_ZONE("updateCull: VO cache cull"); vo_part->cull(camera, LLPipeline::useOcclusion() > 0 && !gAgent.getFSAreaSearchActive()); }
        }
    }
    if (main_cull)
    {
        CullSplitStats& s = sCullSplitStats;
        if (cull_done != 1)
        {
            ++s.mCalls[0];
            s.mMs[0] += std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - serial_t0).count();
        }
        if (cull_done == 2)
        {
            ++s.mCheckRuns;
            if (!cull_lists_equal(*sCullCheckResult, *sCull))
            {
                ++s.mCheckBad;
            }
            if (sVisSetReplay && LLVisSet::checkStamps((S32)LLViewerOctreeEntryData::getCurrentFrame()) != 0)      // <FS> C4.5 R2: the stamps the real walk wrote against the frame the sets claim
            {
                ++s.mCheckBad;
            }
        }
        if (++s.mReport >= 600)
        {
            cull_split_report();
        }
    }

    if (main_census)
    {
        LLCullCensus::sActive.store(false);
        main_cull_census(camera);
    }
    if (visset_mode >= 2 && visset_mode != 5 && visset_mode != 6 && view.isMainWorld() && !gCubeSnapshot && main_cull)
    {
        main_vis_verify(camera);
    }
    if (visset_mode >= 3 && visset_mode != 5 && visset_mode != 6 && view.isMainWorld() && !gCubeSnapshot && main_cull)
    {
        LLVisSet::verify(camera, vs_parts);
    }
    if (visset_mode >= 4 && view.isMainWorld() && !gCubeSnapshot)
    {
        LLVisSet::finishFrame();
    }
    sVisSetReplay = false;

    if (cull_use)
    {
        LL_CPU_ZONE("updateCull: C2 flat cull");
        LLCullShadow::useVerdict(camera);
    }

    if (hasRenderType(LLPipeline::RENDER_TYPE_SKY) &&
        gSky.mVOSkyp.notNull() &&
        gSky.mVOSkyp->mDrawable.notNull())
    {
        gSky.mVOSkyp->mDrawable->setVisible(camera);
        sCull->pushDrawable(gSky.mVOSkyp->mDrawable);
        gSky.updateCull();
    }

    if (hasRenderType(LLPipeline::RENDER_TYPE_WL_SKY) &&
        gPipeline.canUseWindLightShaders() &&
        gSky.mVOWLSkyp.notNull() &&
        gSky.mVOWLSkyp->mDrawable.notNull())
    {
        gSky.mVOWLSkyp->mDrawable->setVisible(camera);
        sCull->pushDrawable(gSky.mVOWLSkyp->mDrawable);
    }
}

void LLPipeline::markNotCulled(LLSpatialGroup* group, LLCamera& camera)
{
    // <FS> C4.5 census (LL_VK_MAINCENSUS=1): the calls, what they push, and the time inside them (all threads)
    struct MarkCensus
    {
        bool mOn; U64 mT0;
        ~MarkCensus() { if (mOn) { LLCullCensus::sMarkTicks.fetch_add(LLVisCensus::now() - mT0, std::memory_order_relaxed); } }
    } census = { LLCullCensus::sOn && LLCullCensus::sActive.load(std::memory_order_relaxed) && LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD && !gCubeSnapshot, 0 };
    if (census.mOn)
    {
        census.mT0 = LLVisCensus::now();
        LLCullCensus::sMarkCalls.fetch_add(1, std::memory_order_relaxed);
    }
    if (group->isEmpty())
    {
        if (census.mOn)
        {
            LLCullCensus::sMarkEmpty.fetch_add(1, std::memory_order_relaxed);
        }
        return;
    }

    if (group->hasState(LLSpatialGroup::FS_RELEASED))
    {
        if (sSortSink)
        {
            sSortSink->push_back({ SortDelta::WAKE_GROUP, 0, nullptr, group, 0.f });      // <FS> stateSort split: the wake queue is the main thread's
        }
        else
        {
            if (sSortTee)
            {
                sSortTee->push_back({ SortDelta::WAKE_GROUP, 0, nullptr, group, 0.f });
            }
            wakeRequest(group);        // <FS> Released: a camera wants it again
        }
    }

    group->setVisible();

    if (LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD && !gCubeSnapshot)
    {
        group->updateDistance(camera);
    }

    assertInitialized();

    if (census.mOn)
    {
        (group->getSpatialPartition()->mRenderByGroup ? LLCullCensus::sMarkVisible : LLCullCensus::sMarkDrawable).fetch_add(1, std::memory_order_relaxed);
    }
    if (!group->getSpatialPartition()->mRenderByGroup)
    { //render by drawable
        sCull->pushDrawableGroup(group);
    }
    else
    {   //render by group
        sCull->pushVisibleGroup(group);
        if (sCullCollectLod && group->changeLOD())      // <FS> C4.4: the row was just written, the answer costs no second visit (the mark job used to ask every visible group)
        {
            sCull->mLodGroups.push_back(group);
        }
    }

    if (group->needsUpdate() ||
        group->getVisible(LLViewerCamera::sCurCameraID) < LLDrawable::getCurrentFrame() - 1)
    {
        // include this group in occlusion groups, not because it is an occluder, but because we want to run
        // an occlusion query to find out if it's an occluder
        markOccluder(group);
    }
    if (!sParallelPrep) // <FS> only a statistic: not worth sharing between the threads of the parallel shadow preparation
    {
        mNumVisibleNodes++;
    }
}

void LLPipeline::replayMember(LLSpatialGroup* group, U8 kind, bool occlude)
{
    if (kind == 1)
    {
        sCull->pushDrawableGroup(group);
    }
    else
    {
        sCull->pushVisibleGroup(group);
    }
    if (occlude)
    {
        markOccluder(group);
    }
}

void LLPipeline::replayAdopted(LLSpatialGroup* group, LLCamera& camera, bool world)
{
    if (group->hasState(LLSpatialGroup::FS_RELEASED))
    {
        wakeRequest(group);
    }
    if (world && LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD && !gCubeSnapshot)
    {
        group->updateDistance(camera);
    }
}

void LLPipeline::replayMemberShadow(LLSpatialGroup* group, U8 kind)
{
    if (kind == 1)
    {
        sCull->pushDrawableGroup(group);
    }
    else
    {
        sCull->pushVisibleGroup(group);
        if (sCullCollectLod && group->changeLOD())      // (markNotCulled's second half for a cascade: the row is read here, the list is the mark job's)
        {
            sCull->mLodGroups.push_back(group);
        }
    }
}

void LLPipeline::markOccluder(LLSpatialGroup* group)
{
    if (LLPipeline::useOcclusion() > 1 && group && !group->isOcclusionState(LLSpatialGroup::ACTIVE_OCCLUSION))
    {
        LLSpatialGroup* parent = group->getParent();

        if (!parent || !parent->isOcclusionState(LLSpatialGroup::OCCLUDED))
        { //only mark top most occluders as active occlusion
            sCull->pushOcclusionGroup(group);
            group->setOcclusionState(LLSpatialGroup::ACTIVE_OCCLUSION);

            if (parent &&
                !parent->isOcclusionState(LLSpatialGroup::ACTIVE_OCCLUSION) &&
                parent->getElementCount() == 0 &&
                parent->needsUpdate())
            {
                sCull->pushOcclusionGroup(group);
                parent->setOcclusionState(LLSpatialGroup::ACTIVE_OCCLUSION);
            }
        }
    }
}

// <FS> S7 H3 (doc/vulkan/S7-design.md): the occlusion pass of the world camera. The boxes of the occlusion groups, the reflection and hero probes and the object cache's groups go to the worker as one record at
// this point of the G-buffer pass (after the big occluders were drawn); the worker's Hi-Z test answers one to four frames later (LLHiz::apply). No cube is drawn and no query is issued.
void LLPipeline::doOcclusion(LLCamera& camera)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    LL_PROFILE_GPU_ZONE("doOcclusion");
    LL_CPU_ZONE("occlusion: doOcclusion");
    llassert(!gCubeSnapshot);

    // the shadow cascades, reflections and cube snapshots have no occlusion data of their own (it is the world camera's); without the Vulkan worker nothing is tested and nothing is occluded
    if (LLPipeline::useOcclusion() <= 1 || LLViewerCamera::sCurCameraID != LLViewerCamera::CAMERA_WORLD || LLPipeline::shadowRender() || gCubeSnapshot || !LLVkBridge::hizAvailable())
    {
        return;
    }

    // <FS> (LL_VK_OCC_CENSUS=1): the pass and its parts
    const U64 occ_t0 = LLOccCensus::sOn ? LLOccCensus::now() : 0;
    if (LLOccCensus::sOn)
    {
        ++LLOccCensus::sPasses[LLViewerCamera::CAMERA_WORLD];
        if (!LLOccCensus::sQpc0)
        {
            LARGE_INTEGER q;
            QueryPerformanceCounter(&q);
            LLOccCensus::sQpc0 = q.QuadPart;
            LLOccCensus::sTsc0 = LLOccCensus::now();
        }
        ++LLOccCensus::sFrames;
    }
    struct OccPassEnd
    {
        U64 mT0;
        ~OccPassEnd()
        {
            if (LLOccCensus::sOn)
            {
                LLOccCensus::sTicksPass[LLViewerCamera::CAMERA_WORLD] += LLOccCensus::now() - mT0;
                if (LLOccCensus::sFrames >= 600)
                {
                    LLOccCensus::report();
                }
            }
        }
    } occ_end = { occ_t0 };

    LLHiz::begin();

    if (sReflectionProbesEnabled)
    {
        const U64 occ_p0 = LLOccCensus::sOn ? LLOccCensus::now() : 0;
        mReflectionMapManager.doOcclusion();
        mHeroProbeManager.doOcclusion();
        if (LLOccCensus::sOn)
        {
            LLOccCensus::sTicksProbes += LLOccCensus::now() - occ_p0;
        }
    }

    if (sCull->hasOcclusionGroups() || LLVOCachePartition::sNeedsOcclusionCheck)
    {
        const U64 occ_g0 = LLOccCensus::sOn ? LLOccCensus::now() : 0;
        for (LLCullResult::sg_iterator iter = sCull->beginOcclusionGroups(); iter != sCull->endOcclusionGroups(); ++iter)
        {
            LLSpatialGroup* group = *iter;
            if (LLOccCensus::sOn)
            {
                ++LLOccCensus::sListGroups[LLViewerCamera::CAMERA_WORLD];
                LLOccCensus::sListDead[LLViewerCamera::CAMERA_WORLD] += group->isDead();
                LLOccCensus::sListOccluded[LLViewerCamera::CAMERA_WORLD] += !group->isDead() && group->isOcclusionState(LLSpatialGroup::OCCLUDED);
            }
            if (!group->isDead())
            {
                const U64 hiz_t0 = LLOccCensus::sOn ? LLOccCensus::now() : 0;
                group->hizCollect(&camera);
                if (LLOccCensus::sOn)
                {
                    LLOccCensus::sHizTicksCollect += LLOccCensus::now() - hiz_t0;
                }
                group->clearOcclusionState(LLSpatialGroup::ACTIVE_OCCLUSION);
            }
        }
        if (LLOccCensus::sOn)
        {
            LLOccCensus::sTicksGroups[LLViewerCamera::CAMERA_WORLD] += LLOccCensus::now() - occ_g0;
        }

        //apply occlusion culling to object cache tree
        const U64 occ_c0 = LLOccCensus::sOn ? LLOccCensus::now() : 0;
        for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin();
            iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
        {
            LLVOCachePartition* vo_part = (*iter)->getVOCachePartition();
            if(vo_part)
            {
                vo_part->processOccluders(&camera);
            }
        }
        if (LLOccCensus::sOn)
        {
            LLOccCensus::sTicksCache += LLOccCensus::now() - occ_c0;
        }
    }

    if (LLCullShadow::sOn)
    {
        LLCullShadow::send(camera);         // <FS> S7 C1: the flat group table, shadow mode
    }
    if (LLVisCensus::sBoxes)
    {
        ll_vis_census_items(camera);        // <FS> S7 B0: the table items' boxes ride in the same batch
    }
    {
        LL_CPU_ZONE("occlusion: Hi-Z send");
        LL_PROFILE_GPU_ZONE("hiz");
        const glm::mat4 hiz_view_proj = gRender.getProjectionMatrix() * glm::make_mat4(gRenderModelView);
        LLHiz::send(glm::value_ptr(hiz_view_proj));
    }
}

bool LLPipeline::updateDrawableGeom(LLDrawable* drawablep)
{
    bool update_complete = drawablep->updateGeometry();
    if (update_complete && assertInitialized())
    {
        drawablep->setState(LLDrawable::BUILT);
    }
    return update_complete;
}

void LLPipeline::updateResources()
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    {
        while (!LLRenderUpdate::sUpdateQueue.empty())
        {
            LLRenderUpdate* glu = LLRenderUpdate::sUpdateQueue.front();
            glu->updateResources();
            glu->mInQ = false;
            LLRenderUpdate::sUpdateQueue.pop_front();
        }
    }
}

void LLPipeline::clearRebuildGroups()
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    LLSpatialGroup::sg_vector_t hudGroups;

    mGroupQ1Locked = true;
    // Iterate through all drawables on the priority build queue,
    for (LLSpatialGroup::sg_vector_t::iterator iter = mGroupQ1.begin();
         iter != mGroupQ1.end(); ++iter)
    {
        LLSpatialGroup* group = *iter;

        if (!group || group->isDead())
        {
            continue;
        }
        // If the group contains HUD objects, save the group
        if (group->isHUDGroup())
        {
            hudGroups.push_back(group);
        }
        // Else, no HUD objects so clear the build state
        else
        {
            group->clearState(LLSpatialGroup::IN_BUILD_Q1);
        }
    }

    // Clear the group
    mGroupQ1.clear();

    // Copy the saved HUD groups back in
    mGroupQ1.assign(hudGroups.begin(), hudGroups.end());
    mGroupQ1Locked = false;
}

void LLPipeline::clearRebuildDrawables()
{
    // Clear all drawables on the priority build queue,
    for (LLDrawable::drawable_list_t::iterator iter = mBuildQ1.begin();
         iter != mBuildQ1.end(); ++iter)
    {
        LLDrawable* drawablep = *iter;
        if (drawablep && !drawablep->isDead())
        {
            drawablep->clearState(LLDrawable::IN_REBUILD_Q);
        }
    }
    mBuildQ1.clear();

    //clear all moving bridges
    for (LLDrawable::drawable_vector_t::iterator iter = mMovedBridge.begin();
         iter != mMovedBridge.end(); ++iter)
    {
        LLDrawable *drawablep = *iter;
        drawablep->clearState(LLDrawable::EARLY_MOVE | LLDrawable::MOVE_UNDAMPED | LLDrawable::ON_MOVE_LIST | LLDrawable::ANIMATED_CHILD);
    }
    mMovedBridge.clear();

    //clear all moving drawables
    for (LLDrawable::drawable_vector_t::iterator iter = mMovedList.begin();
         iter != mMovedList.end(); ++iter)
    {
        LLDrawable *drawablep = *iter;
        drawablep->clearState(LLDrawable::EARLY_MOVE | LLDrawable::MOVE_UNDAMPED | LLDrawable::ON_MOVE_LIST | LLDrawable::ANIMATED_CHILD);
    }
    mMovedList.clear();

    for (LLDrawable::drawable_vector_t::iterator iter = mShiftList.begin();
        iter != mShiftList.end(); ++iter)
    {
        LLDrawable *drawablep = *iter;
        drawablep->clearState(LLDrawable::EARLY_MOVE | LLDrawable::MOVE_UNDAMPED | LLDrawable::ON_MOVE_LIST | LLDrawable::ANIMATED_CHILD | LLDrawable::ON_SHIFT_LIST);
    }
    mShiftList.clear();
}

void LLPipeline::rebuildPriorityGroups()
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    LL_PROFILE_GPU_ZONE("rebuildPriorityGroups");

    LLTimer update_timer;
    assertInitialized();

    gMeshRepo.notifyLoadedMeshes();

    wakeGroups();       // <FS> Released groups a camera wants again, a few at a time

    mGroupQ1Locked = true;
    LLRebuildBatch::Scope rebuild_batch;       // <FS> R3b3 (a scope inside another does nothing: postSort and the shadow prep have their own)
    // census (LL_VK_ITEMCENSUS=1): the groups rebuilt here, by partition type: how many a frame and the time of their rebuildGeom
    static const bool q1_census = ItemCensus::on();
    static std::unordered_map<const LLSpatialGroup*, U64> q1_last_frame;       // <FS> the frame each group was last rebuilt here
    static U64 q1_again[LLViewerRegion::NUM_PARTITIONS + 1] = {}, q1_cycles_again[LLViewerRegion::NUM_PARTITIONS + 1] = {};
    static U64 q1_groups[LLViewerRegion::NUM_PARTITIONS + 1] = {}, q1_cycles[LLViewerRegion::NUM_PARTITIONS + 1] = {}, q1_frames = 0, q1_calls = 0;
    static U64 q1_av_groups = 0, q1_av_drawables = 0, q1_av_faces = 0, q1_av_rigged = 0, q1_av_texanim = 0, q1_av_avatars = 0, q1_av_flag[5] = {}, q1_av_dirty[4] = {}, q1_av_kind[2][7] = {};
    // Iterate through all drawables on the priority build queue,
    for (LLSpatialGroup::sg_vector_t::iterator iter = mGroupQ1.begin();
         iter != mGroupQ1.end(); ++iter)
    {
        LLSpatialGroup* group = *iter;
        const unsigned long long q1_t0 = q1_census ? __rdtsc() : 0;
        if (q1_census && !group->isDead() && group->getOctreeNode() && group->getSpatialPartition() && group->getSpatialPartition()->mPartitionType == LLViewerRegion::PARTITION_AVATAR)
        {
            // what is in an avatar bridge group that is rebuilt (they cost ~0.5 ms a frame, steady): its drawables, faces, how many are rigged or animate a texture, and which rebuild flags they carry
            ++q1_av_groups;
            for (LLSpatialGroup::element_iter e = group->getDataBegin(); e != group->getDataEnd(); ++e)
            {
                const LLDrawable* d = (const LLDrawable*)(*e)->getDrawable();
                if (!d) { continue; }
                ++q1_av_drawables;
                q1_av_faces += d->getNumFaces();
                const U32 st = d->getState();
                q1_av_rigged += (st & LLDrawable::RIGGED) != 0;
                q1_av_flag[0] += (st & LLDrawable::REBUILD_VOLUME) != 0;
                q1_av_flag[1] += (st & LLDrawable::REBUILD_TCOORD) != 0;
                q1_av_flag[2] += (st & LLDrawable::REBUILD_COLOR) != 0;
                q1_av_flag[3] += (st & LLDrawable::REBUILD_POSITION) != 0;
                q1_av_flag[4] += (st & LLDrawable::REBUILD_RIGGED) != 0;
                const LLViewerObject* vo = d->getVObj();
                if (vo && vo->getPCode() == LL_PCODE_VOLUME && ((const LLVOVolume*)vo)->mTextureAnimp) { ++q1_av_texanim; }
                if (vo && vo->isAvatar()) { ++q1_av_avatars; }
            }
            {
                // why a GEOM_DIRTY group (the full rebuild) is dirty: what its drawables carry
                bool volume = false, material = false, animated = false, flexi = false, positioned = false;
                for (LLSpatialGroup::element_iter e = group->getDataBegin(); e != group->getDataEnd(); ++e)
                {
                    const LLDrawable* d = (const LLDrawable*)(*e)->getDrawable();
                    if (!d) { continue; }
                    const U32 st = d->getState();
                    volume |= (st & LLDrawable::REBUILD_VOLUME) != 0;
                    material |= (st & (LLDrawable::REBUILD_TCOORD | LLDrawable::REBUILD_COLOR)) != 0;
                    positioned |= (st & LLDrawable::REBUILD_POSITION) != 0;
                    animated |= (st & LLDrawable::ANIMATED_CHILD) != 0;
                    const LLViewerObject* vo = d->getVObj();
                    flexi |= vo && vo->getPCode() == LL_PCODE_VOLUME && ((const LLVOVolume*)vo)->isFlexibleFast();
                }
                const bool geom = group->hasState(LLSpatialGroup::GEOM_DIRTY);
                ++q1_av_kind[geom ? 1 : 0][0];
                q1_av_kind[geom ? 1 : 0][1] += volume;
                q1_av_kind[geom ? 1 : 0][2] += material;
                q1_av_kind[geom ? 1 : 0][3] += animated;
                q1_av_kind[geom ? 1 : 0][4] += flexi;
                q1_av_kind[geom ? 1 : 0][5] += positioned;
                q1_av_kind[geom ? 1 : 0][6] += !(volume || material || animated);
            }
            q1_av_dirty[0] += group->hasState(LLSpatialGroup::GEOM_DIRTY);
            q1_av_dirty[1] += group->hasState(LLSpatialGroup::MESH_DIRTY);
            q1_av_dirty[2] += group->hasState(LLSpatialGroup::NEW_DRAWINFO);
            q1_av_dirty[3] += group->hasState(LLSpatialGroup::ALPHA_DIRTY);
        }
        group->rebuildGeom();
        if (q1_census)
        {
            const U32 part = group->getSpatialPartition() ? std::min<U32>(group->getSpatialPartition()->mPartitionType, LLViewerRegion::NUM_PARTITIONS) : LLViewerRegion::NUM_PARTITIONS;
            ++q1_groups[part];
            q1_cycles[part] += __rdtsc() - q1_t0;
            // <FS> is a group rebuilt again in the same frame (by the next call of this function: the shadow passes and the main view each sort)?
            U64& last = q1_last_frame[group];
            if (last == (U64)gFrameCount)
            {
                ++q1_again[part];
                q1_cycles_again[part] += __rdtsc() - q1_t0;
            }
            last = (U64)gFrameCount;
        }
        group->clearState(LLSpatialGroup::IN_BUILD_Q1);
    }
    if (q1_census && ++q1_calls % 2400 == 0)
    {
        // (rebuildPriorityGroups runs several times a frame: the shadow passes and the main view; the rates are per call)
        const double hz = 1.0e9 * 3.0;       // (a rough cycles to ms: the ItemCensus calibration is not shared; the cycles are logged raw too)
        std::string line;
        for (U32 k = 0; k <= LLViewerRegion::NUM_PARTITIONS; ++k)
        {
            if (q1_groups[k])
            {
                line += llformat(" | partition %u: %.2f groups a call, %.1f kcycles a call", k, (double)q1_groups[k] / 2400.0, (double)q1_cycles[k] / 2400.0 / 1000.0);
            }
        }
        LL_INFOS("Q1Census") << "rebuildPriorityGroups per call over 2400 calls:" << line << LL_ENDL;
        {
            std::string again;
            for (U32 k = 0; k <= LLViewerRegion::NUM_PARTITIONS; ++k)
            {
                if (q1_again[k]) { again += llformat(" | partition %u: %llu rebuilds of a group already rebuilt in the same frame (%.1f kcycles a call)", k, (unsigned long long)q1_again[k], (double)q1_cycles_again[k] / 2400.0 / 1000.0); }
            }
            LL_INFOS("Q1Census") << "rebuilt again in the same frame:" << (again.empty() ? std::string(" none") : again) << LL_ENDL;
            memset(q1_again, 0, sizeof(q1_again));
            memset(q1_cycles_again, 0, sizeof(q1_cycles_again));
        }
        if (q1_av_groups)
        {
            const double g = (double)q1_av_groups;
            LL_INFOS("Q1Census") << "avatar bridge groups rebuilt (" << q1_av_groups << " in the window): drawables per group " << q1_av_drawables / g << " (avatars " << q1_av_avatars << "), faces " << q1_av_faces / g
                << ", rigged drawables " << q1_av_rigged / g << ", with a texture animation " << q1_av_texanim / g << " | drawable rebuild flags per group: volume " << q1_av_flag[0] / g << ", tcoord " << q1_av_flag[1] / g
                << ", color " << q1_av_flag[2] / g << ", position " << q1_av_flag[3] / g << ", rigged " << q1_av_flag[4] / g << " | group state: geom dirty " << q1_av_dirty[0] / g << ", mesh dirty " << q1_av_dirty[1] / g
                << ", new draw info " << q1_av_dirty[2] / g << ", alpha dirty " << q1_av_dirty[3] / g << LL_ENDL;
            for (int k = 1; k >= 0; --k)
            {
                const double n = (double)std::max<U64>(1, q1_av_kind[k][0]);
                LL_INFOS("Q1Census") << (k ? "GEOM_DIRTY (full rebuild)" : "mesh only (not geom dirty)") << " avatar groups: " << q1_av_kind[k][0] << " | share whose drawables carry: REBUILD_VOLUME " << q1_av_kind[k][1] / n
                    << ", tcoord/color " << q1_av_kind[k][2] / n << ", animated child " << q1_av_kind[k][3] / n << ", a flexible prim " << q1_av_kind[k][4] / n << ", REBUILD_POSITION " << q1_av_kind[k][5] / n
                    << ", none of volume/material/animated " << q1_av_kind[k][6] / n << LL_ENDL;
            }
            memset(q1_av_kind, 0, sizeof(q1_av_kind));
            q1_av_groups = q1_av_drawables = q1_av_faces = q1_av_rigged = q1_av_texanim = q1_av_avatars = 0;
            memset(q1_av_flag, 0, sizeof(q1_av_flag));
            memset(q1_av_dirty, 0, sizeof(q1_av_dirty));
        }
        memset(q1_groups, 0, sizeof(q1_groups));
        memset(q1_cycles, 0, sizeof(q1_cycles));
        (void)hz; (void)q1_frames;
    }

    rebuild_batch.flush();
    mGroupSaveQ1 = mGroupQ1;
    mGroupQ1.clear();
    mGroupQ1Locked = false;

}

void LLPipeline::updateGeom(F32 max_dtime)
{
    LL_CPU_ZONE("pipeline: updateGeom");
    LLTimer update_timer;
    LLPointer<LLDrawable> drawablep;

    LL_RECORD_BLOCK_TIME(FTM_GEO_UPDATE);
    if (gCubeSnapshot)
    {
        return;
    }

    assertInitialized();

    // notify various object types to reset internal cost metrics, etc.
    // for now, only LLVOVolume does this to throttle LOD changes
    LLVOVolume::preUpdateGeom();

    // Iterate through all drawables on the priority build queue,
    for (LLDrawable::drawable_list_t::iterator iter = mBuildQ1.begin();
         iter != mBuildQ1.end();)
    {
        LLDrawable::drawable_list_t::iterator curiter = iter++;
        LLDrawable* drawablep = *curiter;
        if (drawablep && !drawablep->isDead())
        {
            if (drawablep->isUnload())
            {
                drawablep->unload();
                drawablep->clearState(LLDrawable::FOR_UNLOAD);
            }

            if (updateDrawableGeom(drawablep))
            {
                drawablep->clearState(LLDrawable::IN_REBUILD_Q);
                mBuildQ1.erase(curiter);
            }
        }
        else
        {
            mBuildQ1.erase(curiter);
        }
    }

    updateMovedList(mMovedBridge);
}

void LLPipeline::markVisible(LLDrawable *drawablep, LLCamera& camera)
{
    if(drawablep && !drawablep->isDead())
    {
        if (drawablep->isSpatialBridge())
        {
            const LLDrawable* root = ((LLSpatialBridge*) drawablep)->mDrawable;
            llassert(root); // trying to catch a bad assumption

            if (root && //  // this test may not be needed, see above
                    root->getVObj()->isAttachment())
            {
                LLDrawable* rootparent = root->getParent();
                if (rootparent) // this IS sometimes NULL
                {
                    LLViewerObject *vobj = rootparent->getVObj();
                    llassert(vobj); // trying to catch a bad assumption
                    if (vobj) // this test may not be needed, see above
                    {
                        LLVOAvatar* av = vobj->asAvatar();
                        if (av &&
                            ((!sImpostorRender && av->isImpostor()) //ignore impostor flag during impostor pass
                             //|| av->isInMuteList() // <FS:Ansariel> Partially undo MAINT-5700: Draw imposter for muted avatars
                             || (LLVOAvatar::AOA_JELLYDOLL == av->getOverallAppearance() && !av->needsImpostorUpdate()) ))
                        {
                            return;
                        }
                    }
                }
            }
            sCull->pushBridge((LLSpatialBridge*) drawablep);
        }
        else
        {

            sCull->pushDrawable(drawablep);
        }

        drawablep->setVisible(camera);
    }
}

void LLPipeline::markMoved(LLDrawable *drawablep, bool damped_motion)
{
    if (!drawablep)
    {
        //LL_ERRS() << "Sending null drawable to moved list!" << LL_ENDL;
        return;
    }

    if (drawablep->isDead())
    {
        LL_WARNS() << "Marking NULL or dead drawable moved!" << LL_ENDL;
        return;
    }

    if (drawablep->getParent())
    {
        //ensure that parent drawables are moved first
        markMoved(drawablep->getParent(), damped_motion);
    }

    assertInitialized();

    if (!drawablep->isState(LLDrawable::ON_MOVE_LIST))
    {
        if (drawablep->isSpatialBridge())
        {
            if (sAvSink) { sAvSink->push_back({ AvOp::MOVED_BRIDGE, drawablep, nullptr, nullptr, 0 }); }
            else { mMovedBridge.push_back(drawablep); }
        }
        else
        {
            if (sAvSink) { sAvSink->push_back({ AvOp::MOVED_LIST, drawablep, nullptr, nullptr, 0 }); }
            else { mMovedList.push_back(drawablep); }
        }
        drawablep->setState(LLDrawable::ON_MOVE_LIST);
    }
    if (! damped_motion)
    {
        drawablep->setState(LLDrawable::MOVE_UNDAMPED); // UNDAMPED trumps DAMPED
    }
    else if (drawablep->isState(LLDrawable::MOVE_UNDAMPED))
    {
        drawablep->clearState(LLDrawable::MOVE_UNDAMPED);
    }
}

void LLPipeline::markShift(LLDrawable *drawablep)
{
    if (!drawablep || drawablep->isDead() || !drawablep->getVObj())
    {
        return;
    }

    assertInitialized();

    if (!drawablep->isState(LLDrawable::ON_SHIFT_LIST))
    {
        drawablep->getVObj()->setChanged(LLXform::SHIFTED | LLXform::SILHOUETTE);
        if (drawablep->getParent())
        {
            markShift(drawablep->getParent());
        }
        mShiftList.push_back(drawablep);
        drawablep->setState(LLDrawable::ON_SHIFT_LIST);
    }
}

void LLPipeline::shiftObjects(const LLVector3 &offset)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    assertInitialized();

    gRender.clearBuffers(ClearBits::Depth);
    gDepthDirty = true;

    LLVector4a offseta;
    offseta.load3(offset.mV);

    for (LLDrawable::drawable_vector_t::iterator iter = mShiftList.begin();
            iter != mShiftList.end(); iter++)
    {
        LLDrawable *drawablep = *iter;
        if (drawablep->isDead() || !drawablep->getVObj())
        {
            continue;
        }
        drawablep->shiftPos(offseta);
        drawablep->clearState(LLDrawable::ON_SHIFT_LIST);
    }
    mShiftList.resize(0);

    for (LLWorld::region_list_t::const_iterator iter = LLWorld::getInstance()->getRegionList().begin();
            iter != LLWorld::getInstance()->getRegionList().end(); ++iter)
    {
        LLViewerRegion* region = *iter;
        for (U32 i = 0; i < LLViewerRegion::NUM_PARTITIONS; i++)
        {
            LLSpatialPartition* part = region->getSpatialPartition(i);
            if (part)
            {
                part->shift(offseta);
            }
        }
    }

    mReflectionMapManager.shift(offseta);

    LLHUDText::shiftAll(offset);
    LLHUDNameTag::shiftAll(offset);

    display_update_camera();
}

void LLPipeline::markTextured(LLDrawable *drawablep)
{
    if (drawablep && !drawablep->isDead() && assertInitialized())
    {
        mRetexturedList.insert(drawablep);
    }
}

void LLPipeline::markRenderRebuild(LLRenderUpdate* glu)
{
    if (glu && !glu->mInQ)
    {
        LLRenderUpdate::sUpdateQueue.push_back(glu);
        glu->mInQ = true;
    }
}

thread_local std::vector<LLPipeline::SortDelta>* LLPipeline::sSortSink = nullptr;
thread_local std::vector<LLPipeline::SortDelta>* LLPipeline::sSortTee = nullptr;
thread_local std::vector<LLDrawable*>* LLPipeline::sSortPoolSink = nullptr;
bool LLPipeline::sSortJournalOn = false;

void LLPipeline::markPartitionMove(LLDrawable* drawable)
{
    if (sSortSink || sSortTee)
    {
        const SortDelta delta = { SortDelta::PARTITION_MOVE, 0, drawable, nullptr, 0.f };
        if (sSortSink)
        {
            sSortSink->push_back(delta);
            return;
        }
        sSortTee->push_back(delta);
    }
    if (!drawable->isState(LLDrawable::PARTITION_MOVE) &&
        !drawable->getPositionGroup().equals3(LLVector4a::getZero()))
    {
        drawable->setState(LLDrawable::PARTITION_MOVE);
        mPartitionQ.push_back(drawable);
    }
}

void LLPipeline::processPartitionQ()
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;

    // <FS:ND> A vector is much better suited for the use case of mPartitionQ
    // for (LLDrawable::drawable_list_t::iterator iter = mPartitionQ.begin(); iter != mPartitionQ.end(); ++iter)
    for (LLDrawable::drawable_vector_t::iterator iter = mPartitionQ.begin(); iter != mPartitionQ.end(); ++iter)
    // </FS:ND>
    {
        LLDrawable* drawable = *iter;
        if (!drawable->isDead())
        {
            drawable->updateBinRadius();
            drawable->movePartition();
        }
        drawable->clearState(LLDrawable::PARTITION_MOVE);
    }

    mPartitionQ.clear();
}

void LLPipeline::markMeshDirty(LLSpatialGroup* group)
{
    mMeshDirtyGroup.push_back(group);
}

void LLPipeline::markRebuild(LLSpatialGroup* group)
{
    if (sSortSink || sSortTee)
    {
        const SortDelta delta = { SortDelta::REBUILD_GROUP, 0, nullptr, group, 0.f };
        if (sSortSink)
        {
            sSortSink->push_back(delta);
            return;
        }
        sSortTee->push_back(delta);
    }
    if (group && !group->isDead() && group->getSpatialPartition())
    {
        if (!group->hasState(LLSpatialGroup::IN_BUILD_Q1))
        {
            llassert_always(!mGroupQ1Locked);

            mGroupQ1.push_back(group);
            group->setState(LLSpatialGroup::IN_BUILD_Q1);
        }
    }
}

void LLPipeline::markRebuild(LLDrawable *drawablep, LLDrawable::EDrawableFlags flag)
{
    // <FS> LL_VK_REBUILDCENSUS=1: who asks for REBUILD_POSITION of a drawable that belongs to an avatar (attachments and their children), by call site (counted before the sort split sinks the call, so
    // the caller is still the original one); every 3000 asks the top sites are logged (tag RebuildCensus). The avatar bridge groups go through the volume geometry rebuild every frame (lap rqb).
    static const bool rebuild_census = getenv("LL_VK_REBUILDCENSUS") != nullptr;
    if (rebuild_census && drawablep && (flag & LLDrawable::REBUILD_POSITION))
    {
        LLViewerObject* vo = drawablep->getVObj().get();
        if (vo && vo->getAvatar())
        {
            extern std::string fs_describe_address(const void* pc);
            static std::mutex lock;
            static std::unordered_map<const void*, U64> sites;
            static U64 total = 0;
            std::lock_guard<std::mutex> guard(lock);
            ++sites[_ReturnAddress()];
            if (++total % 3000 == 0)
            {
                std::vector<std::pair<U64, const void*>> rows;
                for (const auto& kv : sites) { rows.push_back({ kv.second, kv.first }); }
                std::sort(rows.rbegin(), rows.rend());
                std::string text;
                for (size_t i = 0; i < rows.size() && i < 8; ++i)
                {
                    text += llformat(" [%llu: %s]", (unsigned long long)rows[i].first, fs_describe_address(rows[i].second).c_str());
                }
                LL_INFOS("RebuildCensus") << "REBUILD_POSITION asked for avatar-worn drawables, last " << 3000 << " asks, by caller:" << text << LL_ENDL;
                sites.clear();
            }
        }
    }
    if (sSortSink || sSortTee)
    {
        const SortDelta delta = { SortDelta::REBUILD_DRAWABLE, (U32)flag, drawablep, nullptr, 0.f };
        if (sSortSink)
        {
            sSortSink->push_back(delta);
            return;
        }
        sSortTee->push_back(delta);
    }
    if (drawablep && !drawablep->isDead() && assertInitialized())
    {
        if (!drawablep->isState(LLDrawable::IN_REBUILD_Q))
        {
            mBuildQ1.push_back(drawablep);
            drawablep->setState(LLDrawable::IN_REBUILD_Q); // mark drawable as being in priority queue
        }

        // <FS:Ansariel> FIRE-16485: Crash when calling texture refresh on an object that has a blacklisted copy
        //if (flag & (LLDrawable::REBUILD_VOLUME | LLDrawable::REBUILD_POSITION))
        if ((flag & (LLDrawable::REBUILD_VOLUME | LLDrawable::REBUILD_POSITION)) && drawablep->getVObj().notNull())
        // </FS:Ansariel>
        {
            drawablep->getVObj()->setChanged(LLXform::SILHOUETTE);
        }
        drawablep->setState(flag);
    }
}

static bool sVisSortOn = false;     // <FS> S7 C0 (LL_VK_VISCENSUS=1): this stateSort is the main view's

// <FS> ---- the stateSort split (doc/vulkan/PLAN-statesort-offmain.md, stage 1) ----
// The loops of the main view's stateSort write to state that other code shares: the rebuild queue and the partition move queue (markRebuild, markPartitionMove, called from LLVOVolume::updateLOD),
// the LOD update of avatars and other objects that are not volumes (LLDrawable::updateDistance), and the mesh rebuilds. With a sink set (sSortSink) those calls only record a SortDelta; the apply
// pass makes them in the order they were recorded, which is the order the loops made them, so nothing that reads that state sees a different value, except the code inside the loops itself:
// the check (LL_VK_SORT_SPLIT=2) finds out whether any of it does, by running the loops deferred and then as before and comparing what each one asked for.
// LL_VK_SORT_SPLIT=<mode> (3 = the compute on the pool, default; 0 off, 1 serial split, 2 and 4 checks).
namespace
{
struct SortJournal
{
    struct Vol { LLVOVolume* mVol; LLVOVolume::LODState mState; };
    struct Grp { LLSpatialGroup* mGroup; F32 mDistance; };
    std::vector<Vol> mVols;
    std::vector<Grp> mGroups;
};
thread_local SortJournal* sSortJournal = nullptr;

int sort_split_setting()
{
    static const int env_mode = getenv("LL_VK_SORT_SPLIT") ? atoi(getenv("LL_VK_SORT_SPLIT")) : 3;
    return env_mode;
}
}

// <FS> a rebuildMesh of the loops: recorded in the ledger (and made at the apply pass) when a sink is set, made here and recorded when the check tees
static void sort_rebuild_mesh(LLSpatialGroup* group)
{
    if (!group->hasState(LLSpatialGroup::MESH_DIRTY))
    {
        return;         // (LLSpatialGroup::rebuildMesh does nothing for a group whose mesh is not dirty, and nothing the loops do before it makes one dirty: the 2,000 calls of a sort are not recorded)
    }
    if (LLPipeline::sSortSink)
    {
        LLPipeline::sSortSink->push_back({ LLPipeline::SortDelta::REBUILD_MESH, 0, nullptr, group, 0.f });
        return;
    }
    if (LLPipeline::sSortTee)
    {
        LLPipeline::sSortTee->push_back({ LLPipeline::SortDelta::REBUILD_MESH, 0, nullptr, group, 0.f });
    }
    group->rebuildMesh();
}

// the field of a group the loops write (the check puts it back after the deferred run)
static void sort_journal_group(LLSpatialGroup* group)
{
    if (sSortJournal)
    {
        sSortJournal->mGroups.push_back({ group, group->row().lastUpdateDistance });
    }
}

//static
void LLPipeline::sortJournalVolume(LLVOVolume* volume)
{
    if (sSortJournal)
    {
        sSortJournal->mVols.push_back({ volume, volume->saveLODState() });
    }
}

static int sort_split_mode(const LLPipeline::View& view, bool defer_pools)
{
    const int mode = sort_split_setting();
    if (mode <= 0)
    {
        return 0;
    }
    static const bool census = getenv("LL_VK_VISCENSUS") != nullptr || getenv("LL_VK_OCCCENSUS") != nullptr;
    static LLCachedControl<bool> debug_lods(gSavedSettings, "DebugObjectLODs", false);
    if (census || sVisSortOn || LLOccCensus::sOn || debug_lods || gPipeline.hasRenderDebugMask(LLPipeline::RENDER_DEBUG_TRIANGLE_COUNT) || gPipeline.hasRenderDebugMask(LLPipeline::RENDER_DEBUG_LOD_INFO))
    {
        return 0;
    }
    if (!view.isMainWorldSort())
    {
        return 0;
    }
    if (mode >= 2 && !defer_pools)
    {
        return mode == 3 ? 1 : 0;       // (the check does not run the loops twice where they fill the pools; the parallel sort needs the pool lists deferred)
    }
    return mode > 4 ? 1 : mode;
}

void LLPipeline::applySortDeltas(std::vector<SortDelta>& deltas)
{
    applySortDeltasRange(deltas.data(), deltas.data() + deltas.size());
}

void LLPipeline::applySortDeltasRange(const SortDelta* begin, const SortDelta* end)
{
    sSortSink = nullptr;
    sSortTee = nullptr;
    for (const SortDelta* delta_ptr = begin; delta_ptr != end; ++delta_ptr)
    {
        const SortDelta& d = *delta_ptr;
        switch (d.mKind)
        {
        case SortDelta::REBUILD_DRAWABLE:
            markRebuild(d.mDrawable, (LLDrawable::EDrawableFlags)d.mFlag);
            break;
        case SortDelta::PARTITION_MOVE:
            markPartitionMove(d.mDrawable);
            break;
        case SortDelta::REBUILD_GROUP:
            markRebuild(d.mGroup);
            break;
        case SortDelta::OBJECT_LOD:
            if (d.mDrawable && !d.mDrawable->isDead())
            {
                d.mDrawable->mDistanceWRTCamera = d.mDistance;
                if (LLViewerObject* object = d.mDrawable->getVObj())
                {
                    object->updateLOD();
                }
            }
            break;
        case SortDelta::REBUILD_MESH:
            if (d.mGroup && !d.mGroup->isDead())
            {
                d.mGroup->rebuildMesh();
            }
            break;
        case SortDelta::BRIDGE_DEAD:
            if (d.mDrawable)
            {
                d.mDrawable->markDead();
            }
            break;
        case SortDelta::WAKE_GROUP:
            if (d.mGroup)
            {
                wakeRequest(d.mGroup);
            }
            break;
        }
    }
}

// the check: the loops deferred (into a scratch result, nothing applied, what they write put back), then as before with every call recorded, and the two lists compared
void LLPipeline::sortSplitCheck(LLCamera& camera, std::vector<SortDelta>& ledger_a, std::vector<SortDelta>& ledger_b)
{
    LL_CPU_ZONE("stateSort: split check");
    static LLCullResult scratch;
    static U64 checked = 0, mismatched = 0, entries = 0, kinds[5] = {};
    LLCullResult& real = *sCull;
    scratch.clear();
    // the deferred run reads and pushes into its own copy of the lists the loops use (the visible drawables and bridges are made by the first loop and read by the later ones)
    for (LLCullResult::sg_iterator i = real.beginDrawableGroups(); i != real.endDrawableGroups(); ++i) { scratch.pushDrawableGroup(*i); }
    for (LLCullResult::sg_iterator i = real.beginVisibleGroups(); i != real.endVisibleGroups(); ++i) { scratch.pushVisibleGroup(*i); }
    for (LLCullResult::sg_iterator i = real.beginOcclusionGroups(); i != real.endOcclusionGroups(); ++i) { scratch.pushOcclusionGroup(*i); }
    for (LLCullResult::bridge_iterator i = real.beginVisibleBridge(); i != real.endVisibleBridge(); ++i) { scratch.pushBridge(*i); }
    for (LLCullResult::drawable_iterator i = real.beginVisibleList(); i != real.endVisibleList(); ++i) { scratch.pushDrawable(*i); }

    SortJournal journal;
    sSortJournal = &journal;
    LLPipeline::sSortJournalOn = true;
    std::vector<LLDrawable*> pool_save;
    pool_save.swap(mDeferredPoolFill);
    ledger_a.clear();
    LLPipeline::sSortSink = &ledger_a;
    sCull = &scratch;
    sortLoops(camera, scratch);
    sCull = &real;
    LLPipeline::sSortSink = nullptr;
    mDeferredPoolFill.swap(pool_save);
    LLPipeline::sSortJournalOn = false;
    sSortJournal = nullptr;
    for (auto it = journal.mVols.rbegin(); it != journal.mVols.rend(); ++it)
    {
        it->mVol->restoreLODState(it->mState);
    }
    for (auto it = journal.mGroups.rbegin(); it != journal.mGroups.rend(); ++it)
    {
        it->mGroup->row().lastUpdateDistance = it->mDistance;
    }

    ledger_b.clear();
    LLPipeline::sSortTee = &ledger_b;
    sortLoops(camera, real);
    LLPipeline::sSortTee = nullptr;

    ++checked;
    entries += ledger_b.size();
    for (const LLPipeline::SortDelta& d : ledger_b)
    {
        ++kinds[d.mKind];
    }
    bool same = ledger_a.size() == ledger_b.size();
    size_t first = 0;
    const size_t common = std::min(ledger_a.size(), ledger_b.size());
    for (; first < common; ++first)
    {
        const LLPipeline::SortDelta& x = ledger_a[first];
        const LLPipeline::SortDelta& y = ledger_b[first];
        if (x.mKind != y.mKind || x.mFlag != y.mFlag || x.mDrawable != y.mDrawable || x.mGroup != y.mGroup || memcmp(&x.mDistance, &y.mDistance, sizeof(F32)) != 0)
        {
            same = false;
            break;
        }
    }
    if (!same)
    {
        ++mismatched;
        static U32 said = 0;
        if (said++ < 12)
        {
            const size_t at = first;
            LL_WARNS("SortSplit") << "check: deferred run asked for " << ledger_a.size() << " effects, the direct run for " << ledger_b.size() << "; the first difference is at " << at << ": deferred "
                                  << (at < ledger_a.size() ? std::to_string(ledger_a[at].mKind) + " flag " + std::to_string(ledger_a[at].mFlag) : std::string("(end)")) << ", direct "
                                  << (at < ledger_b.size() ? std::to_string(ledger_b[at].mKind) + " flag " + std::to_string(ledger_b[at].mFlag) : std::string("(end)")) << LL_ENDL;
        }
    }
    if (checked % 600 == 0)
    {
        LL_INFOS("SortSplit") << "check: " << checked << " sorts, " << mismatched << " with a different list of effects; per sort " << (double)entries / (double)checked << " effects (rebuild drawable "
                              << (double)kinds[0] / checked << ", partition move " << (double)kinds[1] / checked << ", rebuild group " << (double)kinds[2] / checked << ", object LOD " << (double)kinds[3] / checked
                              << ", rebuild mesh " << (double)kinds[4] / checked << ")" << LL_ENDL;
    }
}

// <FS> ---- stage 2: the compute on the pool ----
// The four loops are split into chunks of their lists. Fork-join 1: the drawable groups (the visible drawables and bridges are pushed into a result of the chunk's own, appended in chunk order) and the visible
// groups. Between: the bridges' group decisions (the order dependent part of the bridge loop) are made serially. Fork-join 2: the bridges' distances and the visible drawables. Every chunk records
// the effects it asks for in a ledger of its own; the ledgers are joined in the order of the loops (drawable groups, bridges, visible groups, visible drawables), which is the order of the serial sort.
// A sort stays serial when there is no pool, when it is not the early sort, or when a group needs the main thread to change its occlusion state.
namespace
{
struct SortChunk
{
    U8 mKind = 0;                       // 0 drawable groups, 1 visible groups, 2 bridges, 3 visible drawables
    U32 mBegin = 0, mEnd = 0;
    std::vector<LLPipeline::SortDelta> mLedger;
    std::vector<LLDrawable*> mPool;
    LLCullResult* mLocal = nullptr;
    SortJournal mJournal;
};

// the thread-local state of a chunk, put back afterwards (the calling thread runs chunks too)
struct SortTaskScope
{
    LLCullResult* mCull = sCull;
    std::vector<LLPipeline::SortDelta>* mSink = LLPipeline::sSortSink;
    std::vector<LLDrawable*>* mPool = LLPipeline::sSortPoolSink;
    SortJournal* mJournal = sSortJournal;
    bool mParallel = LLPipeline::sParallelPrep;
    ViewScope mView;

    SortTaskScope(SortChunk& chunk, bool journaling, const LLPipeline::View& view) : mView(view)
    {
        LLPipeline::sParallelPrep = true;       // (the bridges' octrees are locked while they are culled, and the statistics are not shared)
        if (chunk.mLocal)
        {
            sCull = chunk.mLocal;
        }
        LLPipeline::sSortSink = &chunk.mLedger;
        LLPipeline::sSortPoolSink = &chunk.mPool;
        sSortJournal = journaling ? &chunk.mJournal : nullptr;
    }
    ~SortTaskScope()
    {
        sCull = mCull;
        LLPipeline::sSortSink = mSink;
        LLPipeline::sSortPoolSink = mPool;
        sSortJournal = mJournal;
        LLPipeline::sParallelPrep = mParallel;
    }
};

std::vector<std::unique_ptr<LLCullResult>> sSortLocals;

U32 sort_chunk_size(size_t items, size_t workers)
{
    static const U32 forced = getenv("LL_VK_SORT_CHUNK") ? (U32)atoi(getenv("LL_VK_SORT_CHUNK")) : 0;
    if (forced)
    {
        return forced;
    }
    const size_t tasks = (workers + 1) * 2;
    return (U32)std::max<size_t>(24, (items + tasks - 1) / tasks);
}
}

bool LLPipeline::sortLoopsParallel(const View& view, LLCullResult& read, std::vector<SortDelta>& ledger, void* journal_ptr)
{
    LLCamera& camera = *view.mCamera;
    LLForkJoinPool* pool = LLForkJoinPool::shared();
    if (!pool || &read != sCull || !mDeferPoolFill || LLGpuZoneTimer::isActive())
    {
        return false;
    }
    SortJournal* journal = (SortJournal*)journal_ptr;
    const U32 n_dg = read.getDrawableGroupsSize();
    const U32 n_vg = read.getVisibleGroupsSize();
    if (n_dg + n_vg < 600)
    {
        return false;       // (too little work to be worth a wake-up)
    }
    if (view.mUseOcclusion > 1)
    {
        LL_CPU_ZONE("stateSort: pre-scan");
        // checkOcclusion and markOccluder change the occlusion state of a group, its parent and its subtree: the main thread's, when any group needs it
        for (LLCullResult::sg_iterator i = read.beginDrawableGroups(); i != read.endDrawableGroups(); ++i)
        {
            LLSpatialGroup* g = *i;
            if (!g->isDead() && (g->isOcclusionState(LLSpatialGroup::OCCLUDED) || g->hizNeedsMainThread())) return false;
        }
        for (LLCullResult::sg_iterator i = read.beginVisibleGroups(); i != read.endVisibleGroups(); ++i)
        {
            LLSpatialGroup* g = *i;
            if (!g->isDead() && (g->isOcclusionState(LLSpatialGroup::OCCLUDED) || g->hizNeedsMainThread())) return false;
        }
    }
    const bool journaling = journal != nullptr;
    const size_t workers = pool->workerCount();

    // the body of the first loop for one group, and of the third: the same on a chunk and in the serial passes below
    auto first_loop_body = [&](LLSpatialGroup* group)
    {
        if (group->isDead())
        {
            return;
        }
        group->checkOcclusion();
        if (view.mUseOcclusion > 1 && group->isOcclusionState(LLSpatialGroup::OCCLUDED))
        {
            markOccluder(group);
        }
        else
        {
            group->setVisible();
            for (LLSpatialGroup::element_iter i = group->getDataBegin(); i != group->getDataEnd(); ++i)
            {
                markVisible((LLDrawable*)(*i)->getDrawable(), camera);
            }
            sort_rebuild_mesh(group);
        }
    };
    auto third_loop_body = [&](LLSpatialGroup* group)
    {
        if (group->isDead())
        {
            return;
        }
        group->checkOcclusion();
        if (view.mUseOcclusion > 1 && group->isOcclusionState(LLSpatialGroup::OCCLUDED))
        {
            markOccluder(group);
        }
        else
        {
            group->setVisible();
            stateSort(group, camera);
            sort_rebuild_mesh(group);
        }
    };

    // ---- fork-join 1: the drawable groups and the visible groups the cull found
    std::vector<SortChunk> first;
    {
        const U32 cs0 = sort_chunk_size(n_dg, workers), cs1 = sort_chunk_size(n_vg, workers);
        for (U32 b = 0; b < n_dg; b += cs0)
        {
            first.emplace_back();
            first.back().mKind = 0;
            first.back().mBegin = b;
            first.back().mEnd = std::min(n_dg, b + cs0);
        }
        const size_t n_first_dg = first.size();
        for (U32 b = 0; b < n_vg; b += cs1)
        {
            first.emplace_back();
            first.back().mKind = 1;
            first.back().mBegin = b;
            first.back().mEnd = std::min(n_vg, b + cs1);
        }
        for (size_t c = 0; c < n_first_dg; ++c)
        {
            if (sSortLocals.size() <= c)
            {
                sSortLocals.push_back(std::make_unique<LLCullResult>());
            }
            sSortLocals[c]->clear();
            first[c].mLocal = sSortLocals[c].get();
        }
    }
    LLCullResult::sg_iterator drawable_groups = read.beginDrawableGroups();
    LLCullResult::sg_iterator visible_groups = read.beginVisibleGroups();
    const std::function<void(size_t)> first_job = [&](size_t c)
    {
        SortChunk& chunk = first[c];
        SortTaskScope scope(chunk, journaling, view);
        for (U32 k = chunk.mBegin; k < chunk.mEnd; ++k)
        {
            if (chunk.mKind == 0)
            {
                first_loop_body(drawable_groups[k]);
            }
            else
            {
                third_loop_body(visible_groups[k]);
            }
        }
    };
    { LL_CPU_ZONE("stateSort: compute 1 (wait for the pool)"); pool->runLabeled("stateSort: compute 1", first.size(), first_job); }

    // what the first loop found, in chunk order: the visible drawables and bridges, and the groups that a bridge's own cull (LLSpatialBridge::setVisible) added to the lists
    {
        LL_CPU_ZONE("stateSort: merge 1");
        for (SortChunk& chunk : first)
        {
            if (chunk.mKind != 0)
            {
                continue;
            }
            for (LLCullResult::drawable_iterator d = chunk.mLocal->beginVisibleList(); d != chunk.mLocal->endVisibleList(); ++d) sCull->pushDrawable(*d);
            for (LLCullResult::bridge_iterator b = chunk.mLocal->beginVisibleBridge(); b != chunk.mLocal->endVisibleBridge(); ++b) sCull->pushBridge(*b);
            for (LLCullResult::sg_iterator g = chunk.mLocal->beginDrawableGroups(); g != chunk.mLocal->endDrawableGroups(); ++g) sCull->pushDrawableGroup(*g);
            for (LLCullResult::sg_iterator g = chunk.mLocal->beginVisibleGroups(); g != chunk.mLocal->endVisibleGroups(); ++g) sCull->pushVisibleGroup(*g);
            for (LLCullResult::sg_iterator g = chunk.mLocal->beginOcclusionGroups(); g != chunk.mLocal->endOcclusionGroups(); ++g) sCull->pushOcclusionGroup(*g);
        }
    }

    // ---- serial: the drawable groups added by the bridges (the first loop of the serial sort goes on over them: its end is the end of the list as it grows)
    std::vector<SortDelta> ledger_x;
    {
        LL_CPU_ZONE("stateSort: serial added groups (drawable)");
        SortJournal* saved_journal = sSortJournal;
        std::vector<SortDelta>* saved_sink = sSortSink;
        sSortJournal = journal;
        sSortSink = &ledger_x;
        for (U32 k = n_dg; k < read.getDrawableGroupsSize(); ++k)
        {
            first_loop_body(read.beginDrawableGroups()[k]);
        }
        sSortSink = saved_sink;
        sSortJournal = saved_journal;
    }

    // ---- between the two: the bridges' group decisions, in list order (they depend on each other through mLastUpdateDistance)
    const U32 n_br = read.getVisibleBridgeSize();
    const U32 n_vd = read.getVisibleListSize();
    std::vector<char> do_distance(n_br, 0);
    {
        LL_CPU_ZONE("stateSort: bridge decisions");
        SortJournal* saved_journal = sSortJournal;
        sSortJournal = journal;
        if (view.mWorldCameraID && !view.mCubeSnapshot)
        {
            LLCullResult::bridge_iterator bridges = read.beginVisibleBridge();
            LLSpatialGroup* last_group = NULL;
            const bool fov_changed = LLViewerCamera::getInstance()->isDefaultFOVChanged();
            for (U32 k = 0; k < n_br; ++k)
            {
                LLSpatialBridge* bridge = bridges[k];
                LLSpatialGroup* group = bridge->getSpatialGroup();
                if (last_group == NULL)
                {
                    last_group = group;
                }
                if (!bridge->isDead() && group && !group->isOcclusionState(LLSpatialGroup::OCCLUDED))
                {
                    do_distance[k] = group->changeLOD() || fov_changed;
                }
                if (last_group && last_group != group && last_group->changeLOD())
                {
                    sort_journal_group(last_group);
                    last_group->row().lastUpdateDistance = last_group->row().distance;
                }
                last_group = group;
            }
            if (last_group && last_group->changeLOD())
            {
                sort_journal_group(last_group);
                last_group->row().lastUpdateDistance = last_group->row().distance;
            }
        }
        sSortJournal = saved_journal;
    }

    // ---- fork-join 2: the bridges' distances and the visible drawables
    std::vector<SortChunk> second;
    {
        const U32 cs2 = sort_chunk_size(n_br, workers), cs3 = sort_chunk_size(n_vd, workers);
        for (U32 b = 0; b < n_br; b += cs2)
        {
            second.emplace_back();
            second.back().mKind = 2;
            second.back().mBegin = b;
            second.back().mEnd = std::min(n_br, b + cs2);
        }
        for (U32 b = 0; b < n_vd; b += cs3)
        {
            second.emplace_back();
            second.back().mKind = 3;
            second.back().mBegin = b;
            second.back().mEnd = std::min(n_vd, b + cs3);
        }
    }
    LLCullResult::bridge_iterator bridges = read.beginVisibleBridge();
    LLCullResult::drawable_iterator visible_list = read.beginVisibleList();
    const std::function<void(size_t)> second_job = [&](size_t c)
    {
        SortChunk& chunk = second[c];
        SortTaskScope scope(chunk, journaling, view);
        if (chunk.mKind == 2)
        {
            for (U32 k = chunk.mBegin; k < chunk.mEnd; ++k)
            {
                if (do_distance[k])
                {
                    bool force_update = false;
                    bridges[k]->updateDistance(camera, force_update);
                }
            }
        }
        else
        {
            for (U32 k = chunk.mBegin; k < chunk.mEnd; ++k)
            {
                LLDrawable* drawablep = visible_list[k];
                if (!drawablep->isDead())
                {
                    stateSort(drawablep, camera);
                }
            }
        }
    };
    { LL_CPU_ZONE("stateSort: compute 2 (wait for the pool)"); pool->runLabeled("stateSort: compute 2", second.size(), second_job); }

    // ---- serial: the visible groups the bridges' culls added (the third loop of the serial sort goes over the whole list, these at its end)
    std::vector<SortDelta> ledger_y;
    std::vector<LLDrawable*> pool_y;
    {
        LL_CPU_ZONE("stateSort: serial added groups (visible)");
        SortJournal* saved_journal = sSortJournal;
        std::vector<SortDelta>* saved_sink = sSortSink;
        std::vector<LLDrawable*>* saved_pool = sSortPoolSink;
        sSortJournal = journal;
        sSortSink = &ledger_y;
        sSortPoolSink = &pool_y;
        for (U32 k = n_vg; k < read.getVisibleGroupsSize(); ++k)
        {
            third_loop_body(read.beginVisibleGroups()[k]);
        }
        sSortPoolSink = saved_pool;
        sSortSink = saved_sink;
        sSortJournal = saved_journal;
    }

    // ---- the ledgers in the order of the serial loops, and the pool lists (visible groups, visible drawables)
    {
        LL_CPU_ZONE("stateSort: join");
        for (SortChunk& chunk : first) if (chunk.mKind == 0) ledger.insert(ledger.end(), chunk.mLedger.begin(), chunk.mLedger.end());
        ledger.insert(ledger.end(), ledger_x.begin(), ledger_x.end());
        for (SortChunk& chunk : second) if (chunk.mKind == 2) ledger.insert(ledger.end(), chunk.mLedger.begin(), chunk.mLedger.end());
        for (SortChunk& chunk : first)
        {
            if (chunk.mKind == 1)
            {
                ledger.insert(ledger.end(), chunk.mLedger.begin(), chunk.mLedger.end());
                mDeferredPoolFill.insert(mDeferredPoolFill.end(), chunk.mPool.begin(), chunk.mPool.end());
            }
        }
        ledger.insert(ledger.end(), ledger_y.begin(), ledger_y.end());
        mDeferredPoolFill.insert(mDeferredPoolFill.end(), pool_y.begin(), pool_y.end());
        for (SortChunk& chunk : second)
        {
            if (chunk.mKind == 3)
            {
                ledger.insert(ledger.end(), chunk.mLedger.begin(), chunk.mLedger.end());
                mDeferredPoolFill.insert(mDeferredPoolFill.end(), chunk.mPool.begin(), chunk.mPool.end());
            }
        }
        if (journaling)
        {
            for (SortChunk& chunk : first)
            {
                journal->mVols.insert(journal->mVols.end(), chunk.mJournal.mVols.begin(), chunk.mJournal.mVols.end());
                journal->mGroups.insert(journal->mGroups.end(), chunk.mJournal.mGroups.begin(), chunk.mJournal.mGroups.end());
            }
            for (SortChunk& chunk : second)
            {
                journal->mVols.insert(journal->mVols.end(), chunk.mJournal.mVols.begin(), chunk.mJournal.mVols.end());
                journal->mGroups.insert(journal->mGroups.end(), chunk.mJournal.mGroups.begin(), chunk.mJournal.mGroups.end());
            }
        }
    }
    return true;
}

// what one run of the loops left, for the parallel check
namespace
{
struct SortDryResult
{
    std::vector<LLPipeline::SortDelta> mLedger;
    std::vector<LLDrawable*> mPool, mVisible;
    std::vector<LLSpatialBridge*> mBridges;
    std::vector<std::pair<LLVOVolume*, LLVOVolume::LODState>> mFinalVols;
    std::vector<std::pair<LLSpatialGroup*, F32>> mFinalGroups;
    std::vector<LLSpatialGroup*> mVisibleGroups, mDrawableGroups;       // the group lists the run worked from, as the run left them
    bool mParallel = false;
};

bool lod_state_equal(const LLVOVolume::LODState& a, const LLVOVolume::LODState& b)
{
    return memcmp(&a.mLOD, &b.mLOD, sizeof(S32)) == 0 && a.mLODDistance == b.mLODDistance && a.mLODAdjustedDistance == b.mLODAdjustedDistance && a.mLODRadius == b.mLODRadius
        && a.mAppAngle == b.mAppAngle && a.mLODChanged == b.mLODChanged;
}
}

// the loops deferred into a scratch copy of the cull lists (serial or on the pool): nothing applied, the fields they write put back, what they asked for and left kept in 'result'
void LLPipeline::sortDryRun(const View& view, bool parallel, void* result_ptr)
{
    LLCamera& camera = *view.mCamera;
    SortDryResult& out = *(SortDryResult*)result_ptr;
    static LLCullResult scratch_serial, scratch_parallel;
    LLCullResult& scratch = parallel ? scratch_parallel : scratch_serial;
    LLCullResult& real = *sCull;
    scratch.clear();
    for (LLCullResult::sg_iterator i = real.beginDrawableGroups(); i != real.endDrawableGroups(); ++i) { scratch.pushDrawableGroup(*i); }
    for (LLCullResult::sg_iterator i = real.beginVisibleGroups(); i != real.endVisibleGroups(); ++i) { scratch.pushVisibleGroup(*i); }
    for (LLCullResult::sg_iterator i = real.beginOcclusionGroups(); i != real.endOcclusionGroups(); ++i) { scratch.pushOcclusionGroup(*i); }
    for (LLCullResult::bridge_iterator i = real.beginVisibleBridge(); i != real.endVisibleBridge(); ++i) { scratch.pushBridge(*i); }
    for (LLCullResult::drawable_iterator i = real.beginVisibleList(); i != real.endVisibleList(); ++i) { scratch.pushDrawable(*i); }

    SortJournal journal;
    sSortJournal = &journal;
    sSortJournalOn = true;
    std::vector<LLDrawable*> pool_save;
    pool_save.swap(mDeferredPoolFill);
    out.mLedger.clear();
    sCull = &scratch;
    out.mParallel = parallel && sortLoopsParallel(view, scratch, out.mLedger, &journal);
    if (!out.mParallel)
    {
        out.mLedger.clear();
        mDeferredPoolFill.clear();
        sSortSink = &out.mLedger;
        sortLoops(camera, scratch);
        sSortSink = nullptr;
    }
    sCull = &real;
    out.mPool = mDeferredPoolFill;
    mDeferredPoolFill.swap(pool_save);
    out.mBridges.assign(scratch.beginVisibleBridge(), scratch.endVisibleBridge());
    out.mVisibleGroups.assign(scratch.beginVisibleGroups(), scratch.endVisibleGroups());
    out.mDrawableGroups.assign(scratch.beginDrawableGroups(), scratch.endDrawableGroups());
    out.mVisible.assign(scratch.beginVisibleList(), scratch.endVisibleList());
    sSortJournalOn = false;
    sSortJournal = nullptr;

    // what the loops left in the fields they wrote (one entry per object), then put back what they found
    out.mFinalVols.clear();
    out.mFinalGroups.clear();
    {
        std::vector<LLVOVolume*> vols;
        for (const auto& v : journal.mVols) vols.push_back(v.mVol);
        std::sort(vols.begin(), vols.end());
        vols.erase(std::unique(vols.begin(), vols.end()), vols.end());
        for (LLVOVolume* v : vols) out.mFinalVols.push_back({ v, v->saveLODState() });
        std::vector<LLSpatialGroup*> groups;
        for (const auto& g : journal.mGroups) groups.push_back(g.mGroup);
        std::sort(groups.begin(), groups.end());
        groups.erase(std::unique(groups.begin(), groups.end()), groups.end());
        for (LLSpatialGroup* g : groups) out.mFinalGroups.push_back({ g, g->row().lastUpdateDistance });
    }
    for (auto it = journal.mVols.rbegin(); it != journal.mVols.rend(); ++it) it->mVol->restoreLODState(it->mState);
    for (auto it = journal.mGroups.rbegin(); it != journal.mGroups.rend(); ++it) it->mGroup->row().lastUpdateDistance = it->mDistance;
}

// LL_VK_SORT_SPLIT=4: the compute on this thread against the compute on the pool, on the same input; then the sort runs as before (the frame is made by the old loops)
void LLPipeline::sortParallelCheck(const View& view)
{
    LL_CPU_ZONE("stateSort: parallel check");
    static U64 checked = 0, same_count = 0, differed = 0, serial_only = 0;
    static SortDryResult a, b;
    sortDryRun(view, false, &a);
    sortDryRun(view, true, &b);
    if (!b.mParallel)
    {
        ++serial_only;
    }
    else
    {
        ++checked;
        std::string why;
        {
            // the lists of effects: sizes, by kind, and the first place where they part
            U32 count_a[6] = {}, count_b[6] = {};
            for (const SortDelta& d : a.mLedger) ++count_a[d.mKind];
            for (const SortDelta& d : b.mLedger) ++count_b[d.mKind];
            const size_t common = std::min(a.mLedger.size(), b.mLedger.size());
            size_t first = 0;
            for (; first < common; ++first)
            {
                const SortDelta& x = a.mLedger[first];
                const SortDelta& y = b.mLedger[first];
                if (x.mKind != y.mKind || x.mFlag != y.mFlag || x.mDrawable != y.mDrawable || x.mGroup != y.mGroup || memcmp(&x.mDistance, &y.mDistance, sizeof(F32)) != 0) break;
            }
            if (first < common || a.mLedger.size() != b.mLedger.size())
            {
                why = "ledger sizes " + std::to_string(a.mLedger.size()) + " / " + std::to_string(b.mLedger.size()) + ", first difference at " + std::to_string(first) + " (kind "
                    + (first < a.mLedger.size() ? std::to_string(a.mLedger[first].mKind) : std::string("end")) + " / " + (first < b.mLedger.size() ? std::to_string(b.mLedger[first].mKind) : std::string("end"))
                    + "), by kind serial / pool: rebuild drawable " + std::to_string(count_a[0]) + "/" + std::to_string(count_b[0]) + ", partition move " + std::to_string(count_a[1]) + "/" + std::to_string(count_b[1])
                    + ", object LOD " + std::to_string(count_a[3]) + "/" + std::to_string(count_b[3]) + ", rebuild mesh " + std::to_string(count_a[4]) + "/" + std::to_string(count_b[4]) + ", bridge dead " + std::to_string(count_a[5]) + "/" + std::to_string(count_b[5]);
            }
        }
        if (why.empty() && a.mPool != b.mPool) why = "pool lists " + std::to_string(a.mPool.size()) + " / " + std::to_string(b.mPool.size());
        if (why.empty() && a.mBridges != b.mBridges) why = "visible bridges " + std::to_string(a.mBridges.size()) + " / " + std::to_string(b.mBridges.size());
        if (why.empty() && a.mVisible != b.mVisible) why = "visible drawables " + std::to_string(a.mVisible.size()) + " / " + std::to_string(b.mVisible.size());
        if (why.empty() && a.mFinalVols.size() != b.mFinalVols.size()) why = "volumes touched " + std::to_string(a.mFinalVols.size()) + " / " + std::to_string(b.mFinalVols.size());
        for (size_t k = 0; why.empty() && k < a.mFinalVols.size(); ++k)
        {
            if (a.mFinalVols[k].first != b.mFinalVols[k].first || !lod_state_equal(a.mFinalVols[k].second, b.mFinalVols[k].second)) why = "volume LOD state of entry " + std::to_string(k);
        }
        if (why.empty() && a.mFinalGroups.size() != b.mFinalGroups.size()) why = "groups touched " + std::to_string(a.mFinalGroups.size()) + " / " + std::to_string(b.mFinalGroups.size());
        for (size_t k = 0; why.empty() && k < a.mFinalGroups.size(); ++k)
        {
            if (a.mFinalGroups[k].first != b.mFinalGroups[k].first || a.mFinalGroups[k].second != b.mFinalGroups[k].second) why = "group distance of entry " + std::to_string(k);
        }
        if (why.empty())
        {
            ++same_count;
        }
        else
        {
            ++differed;
            static U32 said = 0;
            if (said++ < 12)
            {
                LL_WARNS("SortSplit") << "parallel check: the compute on the pool differs from the serial one: " << why << LL_ENDL;
                // the groups whose mesh rebuild the serial run recorded and the pool did not
                std::unordered_map<LLSpatialGroup*, int> in_pool;
                for (const SortDelta& d : b.mLedger) if (d.mKind == SortDelta::REBUILD_MESH) ++in_pool[d.mGroup];
                int shown = 0;
                for (size_t k = 0; k < a.mLedger.size() && shown < 4; ++k)
                {
                    const SortDelta& d = a.mLedger[k];
                    if (d.mKind != SortDelta::REBUILD_MESH) continue;
                    auto it = in_pool.find(d.mGroup);
                    if (it != in_pool.end() && it->second > 0) { --it->second; continue; }
                    ++shown;
                    int in_visible = -1, in_drawable = -1, at = 0;
                    for (LLCullResult::sg_iterator i = sCull->beginVisibleGroups(); i != sCull->endVisibleGroups(); ++i, ++at) if (*i == d.mGroup) { in_visible = at; break; }
                    at = 0;
                    for (LLCullResult::sg_iterator i = sCull->beginDrawableGroups(); i != sCull->endDrawableGroups(); ++i, ++at) if (*i == d.mGroup) { in_drawable = at; break; }
 int in_a_visible = -1, in_b_visible = -1, in_a_drawable = -1, in_b_drawable = -1;
                    for (size_t q = 0; q < a.mVisibleGroups.size(); ++q) if (a.mVisibleGroups[q] == d.mGroup) { in_a_visible = (int)q; break; }
                    for (size_t q = 0; q < b.mVisibleGroups.size(); ++q) if (b.mVisibleGroups[q] == d.mGroup) { in_b_visible = (int)q; break; }
                    for (size_t q = 0; q < a.mDrawableGroups.size(); ++q) if (a.mDrawableGroups[q] == d.mGroup) { in_a_drawable = (int)q; break; }
                    for (size_t q = 0; q < b.mDrawableGroups.size(); ++q) if (b.mDrawableGroups[q] == d.mGroup) { in_b_drawable = (int)q; break; }
                    LL_WARNS("SortSplit") << "  lists the runs worked from: visible groups serial " << in_a_visible << " (of " << a.mVisibleGroups.size() << ") pool " << in_b_visible << " (of " << b.mVisibleGroups.size()
                                          << "), drawable groups serial " << in_a_drawable << " (of " << a.mDrawableGroups.size() << ") pool " << in_b_drawable << " (of " << b.mDrawableGroups.size() << ")" << LL_ENDL;
                    LL_WARNS("SortSplit") << "  missing in the pool: ledger entry " << k << ", group partition " << (d.mGroup->getSpatialPartition() ? (int)d.mGroup->getSpatialPartition()->mPartitionType : -1)
                                          << ", at " << in_visible << " in the visible groups (of " << sCull->getVisibleGroupsSize() << "), " << in_drawable << " in the drawable groups (of " << sCull->getDrawableGroupsSize()
                                          << "), MESH_DIRTY now " << d.mGroup->hasState(LLSpatialGroup::MESH_DIRTY) << ", dead " << d.mGroup->isDead() << LL_ENDL;
                }
            }
        }
    }
    if ((checked + serial_only) % 600 == 0)
    {
        LL_INFOS("SortSplit") << "parallel check: " << checked << " sorts compared, " << differed << " differed, " << serial_only << " could not run on the pool (per sort: " << a.mLedger.size() << " effects, "
                              << a.mVisible.size() << " visible drawables, " << a.mBridges.size() << " bridges, " << a.mFinalVols.size() << " volumes with their LOD computed)" << LL_ENDL;
    }
    // the frame is made by the old loops
    sortLoops(*view.mCamera, *sCull);
}

// the loops of stateSort for the main view: the occlusion check and the visibility stamp of every group and drawable the cull found, the distance and LOD of the bridges and drawables, and the mesh
// rebuilds. They read the cull result they are given and push what is visible into sCull.
void LLPipeline::sortLoops(LLCamera& camera, LLCullResult& read)
{
    {
        LL_PROFILE_ZONE_NAMED_CATEGORY_PIPELINE("checkOcclusionAndRebuildMesh");
        LL_CPU_ZONE("stateSort: drawable groups (occlusion + rebuild)");
    for (LLCullResult::sg_iterator iter = read.beginDrawableGroups(); iter != read.endDrawableGroups(); ++iter)
    {
        LLSpatialGroup* group = *iter;
        if (group->isDead())
        {
            continue;
        }
        {
            const U64 vis_k0 = sVisSortOn ? LLVisCensus::now() : 0;
            group->checkOcclusion();
            if (sVisSortOn) { LLVisCensus::sSortTicksCheck += LLVisCensus::now() - vis_k0; ++LLVisCensus::sSortCheckCalls; ++LLVisCensus::sSortDrawableGroups; }
        }
        if (LLOccCensus::sOn)
        {
            LLOccCensus::sortNote(LLViewerCamera::sCurCameraID, group->isOcclusionState(LLSpatialGroup::OCCLUDED), group->getElementCount());
        }
        if (LLPipeline::useOcclusion() > 1 && group->isOcclusionState(LLSpatialGroup::OCCLUDED))
        {
            markOccluder(group);
            if (sVisSortOn) { ++LLVisCensus::sSortOccluded; }
        }
        else
        {
            group->setVisible();
            const U64 vis_m0 = sVisSortOn ? LLVisCensus::now() : 0;
            for (LLSpatialGroup::element_iter i = group->getDataBegin(); i != group->getDataEnd(); ++i)
            {
                LLDrawable* drawablep = (LLDrawable*)(*i)->getDrawable();
                markVisible(drawablep, camera);
                if (sVisSortOn)
                {
                    ++LLVisCensus::sSortMarkVisN;
                    LLVisCensus::sMarkActive += drawablep->isActive();
                    LLVisCensus::sMarkAvatar += drawablep->isAvatar();
                    LLVisCensus::sMarkBridge += drawablep->isSpatialBridge();
                }
            }
            if (sVisSortOn) { LLVisCensus::sSortTicksMarkVis += LLVisCensus::now() - vis_m0; }

            { //rebuild mesh as soon as we know it's visible
                { LL_CPU_ZONE("stateSort: rebuildMesh"); sort_rebuild_mesh(group); }
            }
        }
    }
    }

    if (LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD && !gCubeSnapshot)
    {
        LL_PROFILE_ZONE_NAMED_CATEGORY_PIPELINE("WorldCamera");
        LL_CPU_ZONE("stateSort: visible bridges");
        LLSpatialGroup* last_group = NULL;
        bool fov_changed = LLViewerCamera::getInstance()->isDefaultFOVChanged();
        for (LLCullResult::bridge_iterator i = read.beginVisibleBridge(); i != read.endVisibleBridge(); ++i)
        {
            LLCullResult::bridge_iterator cur_iter = i;
            LLSpatialBridge* bridge = *cur_iter;
            LLSpatialGroup* group = bridge->getSpatialGroup();

            if (last_group == NULL)
            {
                last_group = group;
            }

            const U64 vis_b0 = sVisSortOn ? LLVisCensus::now() : 0;
            if (!bridge->isDead() && group && !group->isOcclusionState(LLSpatialGroup::OCCLUDED))
            {
                stateSort(bridge, camera, fov_changed);
            }

            if (LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD &&
                last_group != group && last_group->changeLOD())
            {
                sort_journal_group(last_group); last_group->row().lastUpdateDistance = last_group->row().distance;
            }
            if (sVisSortOn) { LLVisCensus::sSortTicksBridge += LLVisCensus::now() - vis_b0; ++LLVisCensus::sSortBridgeCalls; }

            last_group = group;
        }

        if (LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD &&
            last_group && last_group->changeLOD())
        {
            sort_journal_group(last_group); last_group->row().lastUpdateDistance = last_group->row().distance;
        }
    }
    {
        LL_PROFILE_ZONE_NAMED_CATEGORY_PIPELINE("StateSort: visible groups");
        LL_CPU_ZONE("stateSort: visible groups");
    for (LLCullResult::sg_iterator iter = read.beginVisibleGroups(); iter != read.endVisibleGroups(); ++iter)
    {
        LLSpatialGroup* group = *iter;
        if (group->isDead())
        {
            continue;
        }
        {
            const U64 vis_k0 = sVisSortOn ? LLVisCensus::now() : 0;
            group->checkOcclusion();
            if (sVisSortOn) { LLVisCensus::sSortTicksCheck += LLVisCensus::now() - vis_k0; ++LLVisCensus::sSortCheckCalls; ++LLVisCensus::sSortVisibleGroups; }
        }
        if (LLOccCensus::sOn)
        {
            LLOccCensus::sortNote(LLViewerCamera::sCurCameraID, group->isOcclusionState(LLSpatialGroup::OCCLUDED), group->getElementCount());
        }
        if (LLPipeline::useOcclusion() > 1 && group->isOcclusionState(LLSpatialGroup::OCCLUDED))
        {
            markOccluder(group);
            if (sVisSortOn) { ++LLVisCensus::sSortOccluded; }
        }
        else
        {
            group->setVisible();
            stateSort(group, camera);

            { //rebuild mesh as soon as we know it's visible
                { LL_CPU_ZONE("stateSort: rebuildMesh"); sort_rebuild_mesh(group); }
            }
        }
    }}

    {
        LL_PROFILE_ZONE_NAMED_CATEGORY_DRAWABLE("stateSort"); // LL_RECORD_BLOCK_TIME(FTM_STATESORT_DRAWABLE);
        LL_CPU_ZONE("stateSort: visible drawables");
        for (LLCullResult::drawable_iterator iter = read.beginVisibleList();
             iter != read.endVisibleList(); ++iter)
        {
            LLDrawable *drawablep = *iter;
            if (!drawablep->isDead())
            {
                stateSort(drawablep, camera);
            }
        }
    }

}

void LLPipeline::stateSort(LLCamera& camera, LLCullResult &result, bool defer_pools)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    LL_PROFILE_GPU_ZONE("stateSort");

    const View view = currentView(camera, false);
    sVisSortOn = LLVisCensus::sOn && view.isMainWorldSort();
    struct VisSortEnd
    {
        U64 mT0;
        ~VisSortEnd() { if (sVisSortOn) { LLVisCensus::sSortTicks += LLVisCensus::now() - mT0; ++LLVisCensus::sSortCalls; sVisSortOn = false; } }
    } vis_sort_end = { sVisSortOn ? LLVisCensus::now() : 0 };

    mDeferPoolFill = defer_pools;
    if (defer_pools)
    {
        mDeferredPoolFill.clear();
    }

    if (!defer_pools && hasAnyRenderType(LLPipeline::RENDER_TYPE_AVATAR,
                      LLPipeline::RENDER_TYPE_CONTROL_AV,
                      LLPipeline::RENDER_TYPE_TERRAIN,
                      LLPipeline::RENDER_TYPE_TREE,
                      LLPipeline::RENDER_TYPE_SKY,
                      LLPipeline::RENDER_TYPE_VOIDWATER,
                      LLPipeline::RENDER_TYPE_WATER,
                      LLPipeline::END_RENDER_TYPES))
    {
        //clear faces from face pools
        gPipeline.resetDrawOrders();
    }

    //LLVertexBuffer::unbind();

    { LL_CPU_ZONE("grabReferences"); grabReferences(result); }

    // <FS> the split (see sortLoops): 0 as before, 1 compute then apply, 2 the check
    const int split = sort_split_mode(view, defer_pools);
    // (the loops and the apply pass timed per path, logged every 600 sorts of the main view: 0 the loops as before, 1 the split run serially, 2 the split with the compute on the pool)
    static double time_compute[3] = {}, time_apply[3] = {};
    static U32 sorts[3] = {}, effects[3] = {}, window = 0, fallbacks = 0;
    const bool timed = split != 2 && split != 4 && defer_pools;
    const auto t_start = std::chrono::steady_clock::now();
    int path = 0;
    if (split == 0)
    {
        sortLoops(camera, *sCull);
    }
    else
    {
        static std::vector<SortDelta> ledger_a, ledger_b;
        if (split == 1 || split == 3)
        {
            ledger_a.clear();
            path = 1;
            if (split == 3)
            {
                if (sortLoopsParallel(view, *sCull, ledger_a, nullptr))
                {
                    path = 2;
                }
                else
                {
                    ++fallbacks;
                    ledger_a.clear();
                }
            }
            if (path == 1)
            {
                sSortSink = &ledger_a;
                sortLoops(camera, *sCull);
                sSortSink = nullptr;
            }
            const auto t_mid = std::chrono::steady_clock::now();
            {
                LL_CPU_ZONE("stateSort: apply deltas");
                applySortDeltas(ledger_a);
            }
            if (timed)
            {
                time_apply[path] += std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t_mid).count();
                time_compute[path] += std::chrono::duration<double, std::milli>(t_mid - t_start).count();
                effects[path] += (U32)ledger_a.size();
                ++sorts[path];
            }
        }
        else if (split == 4)
        {
            sortParallelCheck(view);
        }
        else
        {
            sortSplitCheck(camera, ledger_a, ledger_b);
        }
    }
    if (timed && split == 0)
    {
        time_compute[0] += std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t_start).count();
        ++sorts[0];
    }
    if (timed && ++window % 600 == 0)
    {
        static const char* const names[3] = { "split off (the loops as before)", "split on, compute on this thread", "split on, compute on the pool" };
        std::string line;
        for (int k = 0; k < 3; ++k)
        {
            if (sorts[k])
            {
                line += llformat(" | %s: %.3f ms compute + %.3f apply = %.3f over %u sorts, %.0f effects a sort", names[k], time_compute[k] / sorts[k], time_apply[k] / sorts[k], (time_compute[k] + time_apply[k]) / sorts[k], sorts[k], (double)effects[k] / sorts[k]);
            }
            time_compute[k] = time_apply[k] = 0.0;
            sorts[k] = effects[k] = 0;
        }
        LL_INFOS("SortSplit") << "stateSort loops (early sort, ms per sort):" << line << "; sorts the pool could not take " << fallbacks << LL_ENDL;
    }

    { LL_CPU_ZONE("stateSort: postSort"); postSort(camera); }
    mDeferPoolFill = false;
}

// <FS> after the shadow passes (which reset the pool face lists and fill them with their own): the lists of the main view, as the sort that ran before them would have made them
void LLPipeline::refillPools(LLCullResult& result)
{
    LL_CPU_ZONE("refill pools");
    grabReferences(result);        // the shadow passes and the impostors left sCull pointing at their own results
    if (hasAnyRenderType(LLPipeline::RENDER_TYPE_AVATAR,
                      LLPipeline::RENDER_TYPE_CONTROL_AV,
                      LLPipeline::RENDER_TYPE_TERRAIN,
                      LLPipeline::RENDER_TYPE_TREE,
                      LLPipeline::RENDER_TYPE_SKY,
                      LLPipeline::RENDER_TYPE_VOIDWATER,
                      LLPipeline::RENDER_TYPE_WATER,
                      LLPipeline::END_RENDER_TYPES))
    {
        gPipeline.resetDrawOrders();
    }
    for (LLDrawable* drawablep : mDeferredPoolFill)
    {
        if (drawablep->isDead())
        {
            continue;
        }
        for (LLDrawable::face_list_t::iterator iter = drawablep->mFaces.begin(); iter != drawablep->mFaces.end(); iter++)
        {
            LLFace* facep = *iter;
            if (facep->hasGeometry())
            {
                if (facep->getPool())
                {
                    facep->getPool()->enqueue(facep);
                }
                else
                {
                    break;
                }
            }
        }
    }
    mDeferredPoolFill.clear();
}

// <FS> a check for the early sort: the render map of a view holds pointers to draw infos that belong to groups; a group that is rebuilt after the map was made frees them. Every entry
// of the map must still be one of the draw infos its group holds now.
void LLPipeline::checkRenderMapLive(LLCullResult& result)
{
    std::unordered_set<const LLDrawInfo*> live;
    for (LLCullResult::sg_iterator i = result.beginVisibleGroups(); i != result.endVisibleGroups(); ++i)
    {
        LLSpatialGroup* group = *i;
        if (group->isDead())
        {
            continue;
        }
        for (auto& entry : group->mDrawMap)
        {
            for (LLDrawInfo* info : entry.second)
            {
                live.insert(info);
            }
        }
    }
    size_t stale = 0, total = 0;
    for (U32 type = 0; type < LLRenderPass::NUM_RENDER_TYPES; ++type)
    {
        for (LLCullResult::drawinfo_iterator it = result.beginRenderMap(type); it != result.endRenderMap(type); ++it)
        {
            ++total;
            if (!live.count(*it))
            {
                ++stale;
            }
        }
    }
    static U32 frames = 0, bad_frames = 0;
    ++frames;
    if (stale)
    {
        ++bad_frames;
        if (bad_frames <= 8)
        {
            LL_WARNS("VkBuilder") << "early sort: " << stale << " of " << total << " draw infos in the render map are no longer held by their group" << LL_ENDL;
        }
    }
    if (frames % 600 == 1)
    {
        LL_INFOS("VkBuilder") << "early sort check: " << frames << " frames, " << bad_frames << " with stale draw infos in the render map" << LL_ENDL;
    }
}

void LLPipeline::stateSort(LLSpatialGroup* group, LLCamera& camera)
{
    const U64 vis_l0 = sVisSortOn ? LLVisCensus::now() : 0;
    const bool vis_lod = group->changeLOD();
    if (sVisSortOn) { LLVisCensus::sSortTicksLod += LLVisCensus::now() - vis_l0; ++LLVisCensus::sSortLodCalls; LLVisCensus::sSortLodTrue += vis_lod; }
    if (vis_lod)
    {
        for (LLSpatialGroup::element_iter i = group->getDataBegin(); i != group->getDataEnd(); ++i)
        {
            LLDrawable* drawablep = (LLDrawable*)(*i)->getDrawable();
            stateSort(drawablep, camera);
        }

        if (LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD && !gCubeSnapshot)
        { //avoid redundant stateSort calls
            sort_journal_group(group);
            group->row().lastUpdateDistance = group->row().distance;
        }
    }
}

void LLPipeline::stateSort(LLSpatialBridge* bridge, LLCamera& camera, bool fov_changed)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    if (bridge->getSpatialGroup()->changeLOD() || fov_changed)
    {
        bool force_update = false;
        bridge->updateDistance(camera, force_update);
    }
}

void LLPipeline::stateSort(LLDrawable* drawablep, LLCamera& camera)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    struct VisDrawableEnd
    {
        U64 mT0;
        ~VisDrawableEnd() { if (sVisSortOn) { LLVisCensus::sSortTicksDrawable += LLVisCensus::now() - mT0; ++LLVisCensus::sSortDrawableCalls; } }
    } vis_drawable_end = { sVisSortOn ? LLVisCensus::now() : 0 };
    if (!drawablep
        || drawablep->isDead()
        || !hasRenderType(drawablep->getRenderType()))
    {
        return;
    }

    // SL-11353
    // ignore our own geo when rendering spotlight shadowmaps...
    //
    if ((RenderSpotLight && drawablep == RenderSpotLight) || (sPrepExclude && drawablep == sPrepExclude))
    {
        return;
    }

    if (LLSelectMgr::getInstance()->mHideSelectedObjects)
    {
//      if (drawablep->getVObj().notNull() &&
//          drawablep->getVObj()->isSelected())
// [RLVa:KB] - Checked: 2010-09-28 (RLVa-1.2.1f) | Modified: RLVa-1.2.1f
        const LLViewerObject* pObj = drawablep->getVObj();
        if ( (pObj) && (pObj->isSelected()) &&
             ( (!RlvActions::isRlvEnabled()) ||
               ( ((!pObj->isHUDAttachment()) || (!gRlvAttachmentLocks.isLockedAttachment(pObj->getRootEdit()))) &&
                 (RlvActions::canEdit(pObj)) ) ) )
// [/RVLa:KB]
        {
            return;
        }
    }

    if (drawablep->isAvatar())
    { //don't draw avatars beyond render distance or if we don't have a spatial group.
        if ((drawablep->getSpatialGroup() == NULL) ||
            (drawablep->getSpatialGroup()->row().distance > LLVOAvatar::sRenderDistance))
        {
            return;
        }

        LLVOAvatar* avatarp = (LLVOAvatar*) drawablep->getVObj().get();
        if (!avatarp->isVisible())
        {
            return;
        }
    }

    assertInitialized();

    if (hasRenderType(drawablep->getRenderType()))
    {
        if (!drawablep->isState(LLDrawable::INVISIBLE|LLDrawable::FORCE_INVISIBLE))
        {
            drawablep->setVisible(camera, NULL, false);
        }
    }

    if (LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD && !gCubeSnapshot)
    {
        //if (drawablep->isVisible()) isVisible() check here is redundant, if it wasn't visible, it wouldn't be here
        const U64 vis_d0 = sVisSortOn ? LLVisCensus::now() : 0;
        if (sVisSortOn)
        {
            if (drawablep->isAvatar()) { ++LLVisCensus::sDrawAvatar; }
            else if (drawablep->isActive()) { ++LLVisCensus::sDrawActive; }
            else { ++LLVisCensus::sDrawStatic; }
        }
        {
            if (!drawablep->isActive())
            {
                bool force_update = false;
                drawablep->updateDistance(camera, force_update);
            }
            else if (drawablep->isAvatar())
            {
                bool force_update = false;
                drawablep->updateDistance(camera, force_update); // calls vobj->updateLOD() which calls LLVOAvatar::updateVisibility()
            }
        }
        if (sVisSortOn) { LLVisCensus::sSortTicksDist += LLVisCensus::now() - vis_d0; ++LLVisCensus::sSortDistCalls; }
    }

    if (!drawablep->getVOVolume())
    {
        if (sVisSortOn)
        {
            // S7 C0: the drawables the pools take by face (terrain, water, trees, grass, sky, avatars, particles), the faces by the pool they go to
            ++LLVisCensus::sPoolDrawables;
            for (LLFace* facep : drawablep->mFaces)
            {
                if (facep->hasGeometry() && facep->getPool())
                {
                    const U32 pt = facep->getPool()->getType();
                    ++LLVisCensus::sPoolFaces[pt < (U32)LLVisCensus::POOLS ? pt : LLVisCensus::POOLS - 1];
                }
            }
        }
        if (mDeferPoolFill)
        {
            if (sSortPoolSink)
            {
                sSortPoolSink->push_back(drawablep);        // <FS> a chunk of the parallel sort: merged into mDeferredPoolFill in chunk order
            }
            else
            {
                mDeferredPoolFill.push_back(drawablep);     // queued by refillPools(), after the shadow passes
            }
        }
        else
        for (LLDrawable::face_list_t::iterator iter = drawablep->mFaces.begin();
                iter != drawablep->mFaces.end(); iter++)
        {
            LLFace* facep = *iter;

            if (facep->hasGeometry())
            {
                if (facep->getPool())
                {
                    facep->getPool()->enqueue(facep);
                }
                else
                {
                    break;
                }
            }
        }
    }

    mNumVisibleFaces.fetch_add(drawablep->getNumFaces(), std::memory_order_relaxed);
}


void forAllDrawables(LLCullResult::sg_iterator begin,
                     LLCullResult::sg_iterator end,
                     void (*func)(LLDrawable*))
{
    for (LLCullResult::sg_iterator i = begin; i != end; ++i)
    {
        LLSpatialGroup* group = *i;
        if (group->isDead())
        {
            continue;
        }
        for (LLSpatialGroup::element_iter j = group->getDataBegin(); j != group->getDataEnd(); ++j)
        {
            if((*j)->hasDrawable())
            {
                func((LLDrawable*)(*j)->getDrawable());
            }
        }
    }
}

void LLPipeline::forAllVisibleDrawables(void (*func)(LLDrawable*))
{
    forAllDrawables(sCull->beginDrawableGroups(), sCull->endDrawableGroups(), func);
    forAllDrawables(sCull->beginVisibleGroups(), sCull->endVisibleGroups(), func);
}

//function for creating scripted beacons
void renderScriptedBeacons(LLDrawable* drawablep)
{
    LLViewerObject *vobj = drawablep->getVObj();
    if (vobj
        && !vobj->isAvatar()
        && !vobj->getParent()
        && vobj->flagScripted())
    {
        if (gPipeline.sRenderBeacons)
        {
            gObjectList.addDebugBeacon(vobj->getPositionAgent(), "", LLColor4(1.f, 0.f, 0.f, 0.5f), LLColor4(1.f, 1.f, 1.f, 0.5f), LLPipeline::DebugBeaconLineWidth);
        }

        if (gPipeline.sRenderHighlight)
        {
            S32 face_id;
            S32 count = drawablep->getNumFaces();
            for (face_id = 0; face_id < count; face_id++)
            {
                LLFace * facep = drawablep->getFace(face_id);
                if (facep)
                {
                    gPipeline.mHighlightFaces.push_back(facep);
                }
            }
        }
    }
}

