{
    mDeferredVB = new LLVertexBuffer(DEFERRED_VB_MASK);
    if (!mDeferredVB->allocateBuffer(8, 0))
    {
        // Most likely going to crash...
        LL_WARNS() << "Failed to allocate Vertex Buffer for deferred rendering" << LL_ENDL;
    }
}
